import type { Prompt } from "../prompt-types";

export const PARENTING_PROMPTS: Prompt[] = [
  // ---- Parenting & Family (1025) ----
  { id: "parenting-1", title: "First foods plan for your baby", category: "parenting", text: "My baby is [6 months] old and I want to start first foods. Suggest a simple first-food plan for two weeks using rice, dal, banana and vegetables easily available in [your city]. Explain how much to give each day, how to mash it safely, and which signs show the baby is ready for the next food." },
  { id: "parenting-2", title: "Calm bedtime routine for toddlers", category: "parenting", text: "Help me build a calm bedtime routine for my [2-year-old] who wakes up many times at night. Give a step-by-step routine from dinner to lights out, with simple activities, a fixed time, and gentle ways to settle the child back to sleep without screen time." },
  { id: "parenting-3", title: "Calm responses for toddler tantrums", category: "parenting", text: "My [3-year-old] has big tantrums in shops and at home. Explain in simple words why toddlers have tantrums, then give me five calm responses I can use in the moment. Add three daily habits that reduce tantrums and tell me when to ask a doctor for advice." },
  { id: "parenting-4", title: "Night feeds and tired parents plan", category: "parenting", text: "My [4-month-old] baby wakes for feeds every two hours at night and I feel very tired. Suggest a feeding and sleep plan for the night, with tips for the mother and father to share the work. Explain what is normal at this age and when feeding patterns usually change." },
  { id: "parenting-5", title: "Milestones at 18 months explained simply", category: "parenting", text: "My child is [18 months] old. List the common milestones for talking, walking, eating and playing at this age in simple words. Tell me which signs are normal, which need a little more time, and when I should talk to a doctor about a delay." },
  { id: "parenting-6", title: "Prepare your child for school", category: "parenting", text: "My child is [5 years] old and starts school next year. Give me a simple plan to prepare them for school at home over [two months]. Cover letters, numbers, holding a pencil, sitting for a short time, and sharing with other children in fun daily activities." },
  { id: "parenting-7", title: "Help your child love reading", category: "parenting", text: "Help my [6-year-old] enjoy reading at home. Suggest a daily 15-minute reading routine, five fun book types for this age, and simple questions I can ask after each story. Tell me how to pick books in [your language] that match my child's interests." },
  { id: "parenting-8", title: "Daily manners for young children", category: "parenting", text: "Teach my [7-year-old] good manners at home and at school. List ten polite habits to practise daily, such as greeting elders, saying please and thank you, and waiting for their turn. Give me simple ways to praise good behaviour without giving sweets or gifts every time." },
  { id: "parenting-9", title: "Simple play ideas at home", category: "parenting", text: "Give me ten simple play ideas for my [4-year-old] at home using things we already have, like boxes, spoons, water and old cloth. Each idea should help them learn counting, colours or words. Tell me how long each game takes and how I can join in." },
  { id: "parenting-10", title: "Calm homework routine for children", category: "parenting", text: "My [10-year-old] hates homework and delays it every evening. Help me set a calm daily homework routine with a fixed time, a tidy study spot, short breaks, and a simple reward chart. Explain how much help I should give and when to let them try alone." },
  { id: "parenting-11", title: "Fair screen time rules for children", category: "parenting", text: "My [11-year-old] spends too much time on a phone and gets upset when I take it away. Suggest fair screen-time rules for weekdays and weekends, with a family agreement we can write together. Give me five screen-free activities to replace evening phone time." },
  { id: "parenting-12", title: "Pocket money lessons for children", category: "parenting", text: "I want to start giving my [9-year-old] pocket money of ₹[100] a week. Explain in simple words how to teach saving, spending and sharing with this money. Give me a weekly plan with three small jars, and simple questions to talk about money each Sunday." },
  { id: "parenting-13", title: "Help a child facing teasing", category: "parenting", text: "My [12-year-old] says friends at school are teasing them and they do not want to go to school. Give me gentle questions to ask, steps to help them feel safe, and advice on talking to the teacher. Explain what to watch for over the next two weeks." },
  { id: "parenting-14", title: "Exam study timetable for children", category: "parenting", text: "Help my [13-year-old] make a study timetable for exams in [three weeks]. Cover all subjects, revision, breaks, sleep and one rest day each week. Give me a simple daily template and tips to keep them calm when they feel stressed before an exam." },
  { id: "parenting-15", title: "Talking with your quiet teenager", category: "parenting", text: "My [15-year-old] barely talks to me and stays in their room. Suggest ten open questions I can ask that do not sound like an interrogation, plus the best times to talk, such as during a walk or a drive. Explain how to listen without judging or giving instant advice." },
  { id: "parenting-16", title: "Supporting a teen before board exams", category: "parenting", text: "My [16-year-old] is very stressed about board exams and sleeps badly. Give me a plan to support them at home with study breaks, healthy food, sleep, and calm words before the exam. Explain what signs of worry need a counsellor and how to suggest it gently." },
  { id: "parenting-17", title: "Phone rules your teen will accept", category: "parenting", text: "Help me agree on phone rules with my [14-year-old] instead of just taking the phone away. Suggest a family phone plan covering night time, meals, homework hours and one phone-free day each week. Give me ways to handle arguments calmly when the rules are broken." },
  { id: "parenting-18", title: "Trust and freedom for teenagers", category: "parenting", text: "My [17-year-old] wants more freedom with friends and I worry about their safety. Help me talk about trust, curfew times, and checking in by phone without sounding strict. Suggest a family agreement that balances freedom with safety on outings in [your city]." },
  { id: "parenting-19", title: "One family meal together daily", category: "parenting", text: "Our family eats at different times and we hardly talk. Help me plan one family meal together each day for a week, with simple Jain vegetarian dishes, a fixed time, and no phones at the table. Give me three conversation starters for each meal to get everyone talking." },
  { id: "parenting-20", title: "Diwali traditions your children will love", category: "parenting", text: "I want my children to enjoy [Diwali] as a family tradition, not just as a holiday. Give me a simple plan for the week of the festival with cleaning, cooking, stories, and one act of giving. Suggest activities for children aged [5] and [12] that both can enjoy together." },
  { id: "parenting-21", title: "Seven nights of bedtime stories", category: "parenting", text: "Give me a seven-night bedtime story plan for my [5-year-old], with one short story each night about kindness, honesty or courage. Each story should take about ten minutes to tell and end with one simple question. Use Indian settings like a village, a school or a train journey." },
  { id: "parenting-22", title: "Yearly health checkups for family", category: "parenting", text: "Help me organise yearly health checkups for our family of [four]. List which basic checkups each person needs by age, how often to go, and what questions to ask the doctor. Add a simple record I can keep at home with dates, reports and next visit reminders." },
  { id: "parenting-23", title: "Fair rules for sibling fights", category: "parenting", text: "My two children aged [6] and [9] fight every day over toys and the TV remote. Give me five fair rules for sharing, plus calm steps I can use when a fight starts. Explain how to help them solve small fights themselves without me taking sides every time." },
  { id: "parenting-24", title: "Prepare your child for a sibling", category: "parenting", text: "We are expecting a second baby and my [3-year-old] feels left out. Give me a gentle plan to prepare them before the baby arrives, with simple words to explain the change, small jobs they can do, and daily one-to-one time ideas for the first month after birth." },
  { id: "parenting-25", title: "Low-cost family weekend plan", category: "parenting", text: "Plan a low-cost family weekend in [your city] for two parents and two children aged [7] and [11]. Include one outdoor activity, one indoor game, a simple meal we cook together, and a Sunday plan that ends early so Monday feels calm. Keep the total budget under ₹[2,000]." },
  { id: "parenting-26", title: "Breastfeeding schedule for a newborn", category: "parenting", text: "Help me make a simple breastfeeding plan for my [age]-old baby. Tell me how often to feed, how long each feed should last, and the signs that my baby has had enough. Add tips for sore nipples and for feeding at night without waking the whole house." },
  { id: "parenting-27", title: "Signs my baby is hungry", category: "parenting", text: "List the early hunger signs in a [age]-old baby before crying starts, such as rooting, sucking fingers and restlessness. Explain how these signs differ from tiredness or a wet nappy. Tell me what to do if my baby keeps crying even after a full feed." },
  { id: "parenting-28", title: "How much milk does my baby need", category: "parenting", text: "Tell me how much breast milk or formula a [age]-old baby usually needs in one day, in millilitres. Explain how the amount changes as the baby grows. Add the signs of overfeeding and underfeeding, and when I should ask a doctor." },
  { id: "parenting-29", title: "Burping my baby after every feed", category: "parenting", text: "Explain three easy ways to burp a [age]-old baby after a feed: over the shoulder, sitting on the lap, and lying face down on the lap. Tell me how long to try, what to do if no burp comes, and why burping helps with gas." },
  { id: "parenting-30", title: "Choosing the right baby formula", category: "parenting", text: "Help me choose a formula for my [age]-old baby. Compare the main types in simple words and explain what to look for on the packet. Tell me how to mix it safely, how much to give per feed, and how to store prepared formula." },
  { id: "parenting-31", title: "Sterilising bottles and feeding equipment", category: "parenting", text: "Give me a simple daily routine for cleaning and sterilising my baby's bottles, teats and bowls. Explain boiling, steam steriliser and cold-water methods in plain words. Tell me how often to replace teats and when sterilising can stop." },
  { id: "parenting-32", title: "Night feeds without losing sleep", category: "parenting", text: "Give me a calm night-feed routine for my [age]-old baby that helps us both get back to sleep quickly. Cover dim lights, quiet feeding, changing the nappy only when needed, and settling the baby down again. Add tips for parents who take turns." },
  { id: "parenting-33", title: "My baby spits up after feeds", category: "parenting", text: "Explain why babies spit up milk after feeds and when it is normal. Tell me the difference between simple spitting up and reflux that needs a doctor. Give me feeding positions and habits that reduce spitting up in a [age]-old baby." },
  { id: "parenting-34", title: "Feeding a fussy baby who refuses milk", category: "parenting", text: "My [age]-old baby keeps turning away from the breast or bottle. List the common reasons, such as teething, a blocked nose or a change in routine. Give me gentle ways to try again without forcing, and signs that need a doctor." },
  { id: "parenting-35", title: "Increasing breast milk supply naturally", category: "parenting", text: "Give me safe, practical ways to increase my breast milk supply, such as feeding more often, drinking enough water and resting. Explain which foods are commonly suggested in Indian homes and what to avoid. Tell me when low supply needs medical advice." },
  { id: "parenting-36", title: "Feeding twins at the same time", category: "parenting", text: "Help me plan feeding two babies of [age] at the same time. Explain tandem breastfeeding positions and how to bottle-feed both babies together. Add tips for keeping track of who ate how much, and how to ask family for help." },
  { id: "parenting-37", title: "Weaning my baby off the breast", category: "parenting", text: "Help me plan a gentle weaning schedule for my [age]-old baby over [number] weeks. Explain how to drop one feed at a time, what to offer instead, and how to handle sore breasts. Add tips for comforting a baby who still wants to feed." },
  { id: "parenting-38", title: "Feeding my baby during travel", category: "parenting", text: "Help me plan feeding my [age]-old baby on a [train/flight/car] trip to [place]. Tell me what milk, water and food to pack, how to keep bottles clean on the road, and how to feed comfortably in public places. Add a simple packing checklist." },
  { id: "parenting-39", title: "Colic and evening crying in babies", category: "parenting", text: "Explain what colic is and why a [age]-old baby may cry for hours in the evening. Give me soothing ideas such as rocking, gentle tummy massage and white noise. Tell me when crying is normal and when I should call the doctor." },
  { id: "parenting-40", title: "Baby hiccups after feeding", category: "parenting", text: "Explain why my [age]-old baby gets hiccups after feeds and whether they are harmful. Give me simple ways to stop hiccups, such as burping, holding the baby upright or offering a small feed. Tell me when hiccups need a doctor." },
  { id: "parenting-41", title: "Expressing and storing breast milk", category: "parenting", text: "Teach me how to express breast milk by hand and with a pump. Explain how to store it in clean containers, how long it keeps in the fridge and freezer, and how to warm it safely. Add tips for labelling and for going back to work." },
  { id: "parenting-42", title: "Feeding a premature baby at home", category: "parenting", text: "Help me plan feeds for my premature baby, now [age] old. Explain smaller, more frequent feeds, watching weight gain, and keeping the baby warm during feeds. Tell me which warning signs mean I should contact the doctor at once." },
  { id: "parenting-43", title: "When my baby bites while breastfeeding", category: "parenting", text: "My [age]-old baby has started biting during breastfeeding, especially while teething. Explain why babies bite and how to react calmly without scaring them. Give me tips to prevent biting and to heal sore nipples." },
  { id: "parenting-44", title: "Cluster feeding in the evening", category: "parenting", text: "Explain cluster feeding, when a [age]-old baby wants to feed again and again in the evening. Tell me why it happens, how long it usually lasts, and how to cope. Add tips for resting, eating well and getting help from family." },
  { id: "parenting-45", title: "Mixing breast milk and formula", category: "parenting", text: "Explain how to combine breastfeeding and formula for my [age]-old baby. Tell me how to introduce one bottle a day, which feeds to replace first, and how to keep my milk supply going. Add tips for choosing feeding times that suit the family." },
  { id: "parenting-46", title: "Baby refuses the bottle completely", category: "parenting", text: "My [age]-old baby refuses every bottle I offer. List the likely reasons, such as teat shape, milk temperature or preferring the breast. Give me gentle steps to try over a few days, including who should offer the bottle and when." },
  { id: "parenting-47", title: "Feeding positions that prevent gas", category: "parenting", text: "Show me feeding positions for a [age]-old baby that reduce swallowed air and gas. Cover upright holds, cradle hold and laid-back feeding in simple words. Explain how to keep the teat full of milk and why a slow pace helps." },
  { id: "parenting-48", title: "How to know my baby is full", category: "parenting", text: "List the signs that a [age]-old baby is full after a feed, such as relaxed hands, turning away and falling asleep. Explain how these signs differ from a baby who is still hungry. Tell me why I should not force extra milk." },
  { id: "parenting-49", title: "Feeding my baby in hot weather", category: "parenting", text: "Help me feed my [age]-old baby safely during a hot Indian summer. Explain whether extra water is needed, how to spot dehydration, and how to keep milk fresh in the heat. Add tips for feeding outdoors and on long outings." },
  { id: "parenting-50", title: "Switching formula brands safely", category: "parenting", text: "Explain how to switch my [age]-old baby from one formula brand to another. Tell me whether to change suddenly or mix gradually over a few days, and what tummy changes to expect. Add warning signs that mean I should stop and ask a doctor." },
  { id: "parenting-51", title: "My baby feeds only on one side", category: "parenting", text: "My [age]-old baby prefers feeding from one breast only. Explain why this happens and whether it is a problem. Give me gentle ways to encourage the other side, and tips for keeping milk supply balanced on both sides." },
  { id: "parenting-52", title: "Feeding schedule for a six-month-old", category: "parenting", text: "Make a simple daily feeding schedule for my six-month-old baby who has just started solids. Show how milk feeds and small meals fit together through the day. Add the timing of each feed and meal, and how much to offer at each one." },
  { id: "parenting-53", title: "Dream feeding my baby at night", category: "parenting", text: "Explain dream feeding, where I feed my [age]-old baby while they are still asleep at night. Tell me the best time to do it, how to do it gently, and whether it really helps babies sleep longer. Add the downsides and when to stop." },
  { id: "parenting-54", title: "Baby feeding chart for the first year", category: "parenting", text: "Make a simple month-by-month feeding chart for my baby from birth to one year. Show milk feeds, first foods and meal counts at each stage. Keep it in a table I can print and stick on the fridge, with a note to check with my doctor." },
  { id: "parenting-55", title: "Feeding a baby with a blocked nose", category: "parenting", text: "My [age]-old baby has a blocked nose and struggles to feed. Give me safe ways to clear the nose before feeds, such as saline drops and steam. Explain feeding positions that help, and warning signs that need a doctor." },
  { id: "parenting-56", title: "Introducing a cup to my baby", category: "parenting", text: "Help me introduce a small open cup or sippy cup to my [age]-old baby. Explain when to start, which cup to choose, and how to practise with a little water at meals. Add tips for spills and for moving away from bottles." },
  { id: "parenting-57", title: "Baby spits out the bottle teat", category: "parenting", text: "My [age]-old baby keeps pushing the bottle teat out with the tongue. Explain whether this is normal at this age and what it may mean. Give me ways to check the teat flow, milk temperature and feeding position before trying again." },
  { id: "parenting-58", title: "Feeding my baby at a wedding", category: "parenting", text: "Help me plan feeding my [age]-old baby at a family wedding in [city]. Tell me what to pack, where to feed comfortably, and how to keep milk and food fresh for hours. Add tips for handling noise, crowds and late-night functions." },
  { id: "parenting-59", title: "Comfort feeding versus hunger feeding", category: "parenting", text: "Explain the difference between a baby feeding because they are hungry and a baby feeding for comfort. Tell me how to spot each one in my [age]-old baby. Add gentle ways to comfort without feeding, such as rocking, singing or a dummy." },
  { id: "parenting-60", title: "Feeding a baby who vomits often", category: "parenting", text: "My [age]-old baby vomits after many feeds. Explain the common causes, such as overfeeding, fast flow or reflux. Give me feeding changes to try, like smaller feeds and keeping the baby upright. Tell me the red flags that need a doctor urgently." },
  { id: "parenting-61", title: "Making feeding time calm and happy", category: "parenting", text: "Give me ideas to make feeding time calm for my [age]-old baby. Cover a quiet corner, soft talking or singing, eye contact and unhurried feeding. Explain how a calm routine helps bonding and digestion, and what to avoid during feeds." },
  { id: "parenting-62", title: "Feeding my baby while I am ill", category: "parenting", text: "I have [fever/cold/stomach upset] and I am feeding my [age]-old baby. Explain whether I can keep breastfeeding, what medicines to avoid, and how to protect the baby from infection. Tell me when to rest and when to seek medical help." },
  { id: "parenting-63", title: "Baby weight gain worries explained", category: "parenting", text: "My [age]-old baby seems to gain weight slowly and I am worried. Explain normal weight gain patterns, how doctors use growth charts, and what matters more than a single weighing. Tell me when slow gain needs a doctor." },
  { id: "parenting-64", title: "Feeding twins with different appetites", category: "parenting", text: "My twin babies of [age] eat very different amounts. Explain why this is normal and how to feed each baby as per their hunger. Give me a simple log to track feeds, and tips for not comparing the twins with each other." },
  { id: "parenting-65", title: "Starting solids after exclusive breastfeeding", category: "parenting", text: "My baby is [age] old and has been only breastfed so far. Explain how to start solids gently, one new food at a time. Tell me which foods to begin with, how much to offer, and how to keep breastfeeding alongside meals." },
  { id: "parenting-66", title: "Feeding a baby who wakes to feed", category: "parenting", text: "My [age]-old baby still wakes twice every night to feed. Explain whether this is normal at this age and how night hunger changes as babies grow. Give me gentle steps to reduce night feeds without leaving the baby crying alone." },
  { id: "parenting-67", title: "Sterilising bottles while travelling", category: "parenting", text: "Help me keep my baby's bottles clean on a [number]-day trip to [place]. Explain portable sterilising options, ready-to-use formula and safe water choices. Give me a packing list and a simple cleaning routine for hotel rooms and trains." },
  { id: "parenting-68", title: "Feeding a baby during a power cut", category: "parenting", text: "Help me feed my [age]-old baby during a long power cut in summer. Explain how to keep expressed milk cool without a fridge, how to warm milk without a heater, and safe water options. Add a short emergency feeding kit list." },
  { id: "parenting-69", title: "When to stop sterilising bottles", category: "parenting", text: "Explain when it is safe to stop sterilising my baby's bottles and bowls. Tell me the usual age, how to move to simple hot-water washing, and why hygiene still matters. Add tips for keeping feeding things clean in a busy Indian kitchen." },
  { id: "parenting-70", title: "Baby feeding and teething pain", category: "parenting", text: "My [age]-old baby is teething and refuses to feed. Explain how sore gums affect feeding and what helps, such as a cool teether before feeds or a clean wet cloth to chew. Tell me when refusal to feed needs a doctor." },
  { id: "parenting-71", title: "Feeding my baby at daycare", category: "parenting", text: "Help me plan feeding for my [age]-old baby at daycare in [city]. Tell me how much expressed milk or formula to send, how to label bottles, and what instructions to give the carer. Add questions to ask the daycare before the first day." },
  { id: "parenting-72", title: "Feeding a baby after vaccination", category: "parenting", text: "My [age]-old baby has a vaccination tomorrow. Explain whether feeding should change before or after the injection, and how to comfort a baby who feeds less after the jab. Tell me which reactions are normal and which need a doctor." },
  { id: "parenting-73", title: "Introducing water to my baby", category: "parenting", text: "Explain when and how to introduce water to my [age]-old baby. Tell me how much to offer, which water is safe, and whether boiled and cooled water is needed. Add the signs of too little water in hot weather." },
  { id: "parenting-74", title: "Baby feeding log for busy parents", category: "parenting", text: "Make a simple daily feeding log for my [age]-old baby that both parents can use. Include columns for time, breast or bottle, amount, nappy changes and sleep. Keep it easy to fill on a phone, and explain what patterns to look for." },
  { id: "parenting-75", title: "Feeding a baby with tongue tie", category: "parenting", text: "Explain tongue tie in babies in simple words and how it can affect feeding for a [age]-old baby. List the signs, such as poor latch and slow weight gain. Tell me what a doctor checks and what the usual options are." },
  { id: "parenting-76", title: "Baby sleep routine for newborns", category: "parenting", text: "Help me build a simple bedtime routine for my [age]-old baby. Cover a warm bath, a feed, a lullaby and dim lights in the same order every night. Explain how a fixed routine helps the baby learn that night is for sleeping." },
  { id: "parenting-77", title: "How much sleep does my baby need", category: "parenting", text: "Tell me how many hours of sleep a [age]-old baby usually needs in a day, including naps. Explain how sleep changes month by month in the first year. Add the signs of an overtired baby and what to do when naps are too short." },
  { id: "parenting-78", title: "Helping my baby sleep through the night", category: "parenting", text: "Give me gentle steps to help my [age]-old baby sleep for longer stretches at night. Cover day and night differences, a calm bedtime, and responding to waking without bright lights or play. Explain that progress is slow and every baby is different." },
  { id: "parenting-79", title: "Nap schedule for a six-month-old", category: "parenting", text: "Make a simple daytime nap schedule for my six-month-old baby. Show how many naps, how long each one should be, and the wake windows between them. Add tips for naps at home, at grandmother's house and while travelling." },
  { id: "parenting-80", title: "Baby wakes up every hour at night", category: "parenting", text: "My [age]-old baby wakes up almost every hour at night. List the common reasons, such as hunger, teething, a wet nappy or room temperature. Give me calm ways to settle the baby back to sleep, and signs that need a doctor." },
  { id: "parenting-81", title: "Safe sleeping position for babies", category: "parenting", text: "Explain the safest sleeping position for a [age]-old baby and why sleeping on the back is advised. Tell me what the cot should and should not contain, and how to keep the room at a safe temperature. Add common mistakes Indian parents should avoid." },
  { id: "parenting-82", title: "Swaddling my baby safely", category: "parenting", text: "Teach me how to swaddle my [age]-old baby safely with a light cotton cloth. Explain the steps, how snug it should be, and why the hips must stay loose. Tell me when to stop swaddling and what to use instead." },
  { id: "parenting-83", title: "White noise for baby sleep", category: "parenting", text: "Explain what white noise is and whether it helps a [age]-old baby sleep. Tell me how loud it should be, how far from the cot to keep it, and when to switch it off. Add other soothing sounds such as a fan or soft humming." },
  { id: "parenting-84", title: "Sleep training without crying it out", category: "parenting", text: "Give me a gentle sleep plan for my [age]-old baby that does not leave the baby crying alone. Explain gradual steps such as staying close, patting and slowly reducing help. Tell me how long it may take and when to pause the plan." },
  { id: "parenting-85", title: "Toddler bedtime battles every night", category: "parenting", text: "My [age]-old toddler refuses bed every night and asks for water, stories and one more hug. Explain why toddlers resist bedtime and give me a firm but kind routine. Add tips for staying consistent when grandparents give in." },
  { id: "parenting-86", title: "My baby only sleeps in my arms", category: "parenting", text: "My [age]-old baby sleeps only when held and wakes the moment I put them down. Explain why this happens and give me gentle steps to help the baby sleep in the cot. Add tips for the drowsy-but-awake method and for tired parents." },
  { id: "parenting-87", title: "Day and night confusion in newborns", category: "parenting", text: "My newborn sleeps all day and stays awake all night. Explain why newborns mix up day and night, and how to fix it gently. Cover bright daylight, daytime activity, and a dark quiet room at night. Tell me how many weeks it usually takes." },
  { id: "parenting-88", title: "Toddler nap refusal at home", category: "parenting", text: "My [age]-old toddler has started refusing the afternoon nap. Explain whether this is normal and how to tell if they still need it. Give me a quiet-time routine for days without a nap, and tips for earlier bedtime." },
  { id: "parenting-89", title: "Baby sleep and room temperature", category: "parenting", text: "Explain the best room temperature for a [age]-old baby to sleep in Indian weather. Tell me how to dress the baby for sleep in summer and winter, and how to check if the baby is too hot or too cold. Add tips for fans and coolers." },
  { id: "parenting-90", title: "Moving my baby from cradle to cot", category: "parenting", text: "Help me move my [age]-old baby from the cradle to a cot. Explain when to make the change, how to make the cot feel familiar, and how to handle the first few unsettled nights. Add safety checks for the cot and mattress." },
  { id: "parenting-91", title: "Toddler wakes up too early", category: "parenting", text: "My [age]-old toddler wakes up at 5 in the morning every day. List the likely causes, such as early bedtime, light in the room or hunger. Give me practical fixes and a gentle way to teach the child to wait until morning." },
  { id: "parenting-92", title: "Sleep regression at four months", category: "parenting", text: "Explain the four-month sleep regression in simple words and why my baby suddenly wakes more at night. Tell me how long it usually lasts and what helps, such as a steady routine and extra daytime feeds. Reassure me that it passes." },
  { id: "parenting-93", title: "Rocking my baby to sleep safely", category: "parenting", text: "Explain how to rock a [age]-old baby to sleep safely and how to slowly reduce rocking over time. Tell me why gentle motion soothes babies and when rocking becomes a habit that is hard to break. Add alternatives such as patting or singing." },
  { id: "parenting-94", title: "Baby naps only for twenty minutes", category: "parenting", text: "My [age]-old baby naps for only twenty minutes and wakes up cranky. Explain why short naps happen and whether they are a problem. Give me ways to extend naps, such as a dark room, white noise and watching wake windows." },
  { id: "parenting-95", title: "Bedtime stories for toddlers", category: "parenting", text: "Give me a list of simple bedtime story ideas for my [age]-old toddler, using Indian settings such as a village, a train journey or a festival. Explain how to tell a short story with voices and questions. Add tips for a calm story routine." },
  { id: "parenting-96", title: "Toddler nightmares and night waking", category: "parenting", text: "My [age]-old toddler wakes up scared at night and cries for me. Explain the difference between a nightmare and a night terror in simple words. Give me calm ways to comfort the child and a bedtime routine that reduces night fears." },
  { id: "parenting-97", title: "Sleeping with my baby in the same bed", category: "parenting", text: "Explain co-sleeping with a [age]-old baby in simple, honest words. List the safety rules, such as a firm mattress, no pillows near the baby and no alcohol or smoking. Tell me when bed-sharing is not safe and what the alternatives are." },
  { id: "parenting-98", title: "Baby sleep while travelling by train", category: "parenting", text: "Help me plan sleep for my [age]-old baby on an overnight train to [place]. Tell me what to pack, how to make a small sleeping space on the berth, and how to keep the baby safe and settled. Add tips for noise and changing nappies." },
  { id: "parenting-99", title: "Toddler sleep after starting playgroup", category: "parenting", text: "My [age]-old toddler started playgroup and now sleeps badly at night. Explain why new routines disturb sleep and how long it usually takes to settle. Give me a calm evening routine and tips for earlier bedtime on school days." },
  { id: "parenting-100", title: "Helping twins sleep at the same time", category: "parenting", text: "Help me get my twin babies of [age] to sleep at the same time. Explain syncing naps and bedtime, what to do when one wakes the other, and how to settle both together. Add tips for tired parents and asking family for help." },
  { id: "parenting-101", title: "Baby sleep and teething nights", category: "parenting", text: "My [age]-old baby is teething and wakes up crying at night. Explain how teething disturbs sleep and what helps, such as a cool teether before bed or a gentle gum massage. Tell me when waking needs a doctor." },
  { id: "parenting-102", title: "Lullabies to soothe my baby", category: "parenting", text: "Give me a list of simple Indian lullabies and rhymes I can sing to my [age]-old baby at bedtime, in Hindi and English. Explain how singing helps the baby relax and bond with me. Add tips for parents who feel shy about singing." },
  { id: "parenting-103", title: "Toddler wants only mummy at bedtime", category: "parenting", text: "My [age]-old toddler wants only me at bedtime and cries when daddy tries. Explain why this phase is normal and how to share bedtime gently. Give me a plan for daddy to join the routine step by step without tears." },
  { id: "parenting-104", title: "Baby sleep schedule after illness", category: "parenting", text: "My [age]-old baby had a fever last week and now the sleep routine is broken. Explain how illness disturbs sleep and how to rebuild the routine gently. Give me a day-by-day plan for the first week back to normal." },
  { id: "parenting-105", title: "Choosing a cot and mattress for baby", category: "parenting", text: "Help me choose a safe cot and mattress for my [age]-old baby within a budget of ₹[amount]. Explain what to check, such as slat gaps, a firm mattress and no drop sides. Add tips for bedding, mosquito nets and where to place the cot." },
  { id: "parenting-106", title: "Toddler sleep and screen time", category: "parenting", text: "Explain how TV and phone screens before bed affect sleep in a [age]-old toddler. Tell me how long before bedtime screens should stop and what calm activities to do instead. Give me a simple evening plan with no screens." },
  { id: "parenting-107", title: "Baby wakes when I leave the room", category: "parenting", text: "My [age]-old baby wakes the moment I leave the room at bedtime. Explain separation anxiety in simple words and why it peaks at this age. Give me gentle steps to help the baby feel safe, such as a comfort toy and a short goodbye routine." },
  { id: "parenting-108", title: "Nap routine for a one-year-old", category: "parenting", text: "Make a simple daily nap routine for my one-year-old baby. Show the number of naps, their timing and how long they should last. Add tips for naps when we are out, at a relative's house or during a festival." },
  { id: "parenting-109", title: "Baby sleep and feeding at night", category: "parenting", text: "Explain how night feeds and sleep are linked for a [age]-old baby. Tell me when night feeds are needed and when babies can sleep longer without milk. Give me gentle steps to reduce night feeds one at a time." },
  { id: "parenting-110", title: "Toddler sleeps late every night", category: "parenting", text: "My [age]-old toddler sleeps at 11 pm every night and wakes up tired. Explain why late bedtime hurts the next day and give me a plan to move bedtime earlier by fifteen minutes each week. Add tips for the whole family to wind down." },
  { id: "parenting-111", title: "Baby sleep in a joint family home", category: "parenting", text: "Help me protect my [age]-old baby's sleep in a busy joint family home. Give me ways to ask relatives for quiet time, handle visitors at nap time, and keep a fixed bedtime. Add polite words to use when elders want to play with the baby." },
  { id: "parenting-112", title: "Sleep cues I should watch for", category: "parenting", text: "List the sleep cues in a [age]-old baby, such as yawning, rubbing eyes and staring blankly. Explain how to act quickly when I see them and what happens if I miss the window. Add the difference between tired signs and hunger signs." },
  { id: "parenting-113", title: "Toddler bedtime routine chart", category: "parenting", text: "Make a simple bedtime routine chart for my [age]-old toddler with pictures I can describe. Include bath, brushing teeth, pyjamas, a story and lights out. Explain how to use it every night and reward the child for following it." },
  { id: "parenting-114", title: "Baby sleep after a festival night", category: "parenting", text: "My [age]-old baby stayed up late during Diwali and now the sleep routine is broken. Explain how to reset the routine over a few days. Give me a plan for earlier bedtime, quiet days and handling fireworks noise next time." },
  { id: "parenting-115", title: "Comfort toy for baby sleep", category: "parenting", text: "Explain how a small comfort toy or cloth can help a [age]-old baby sleep. Tell me how to choose a safe one, how to introduce it, and how to keep it clean. Add advice for babies who lose the toy in the middle of the night." },
  { id: "parenting-116", title: "Toddler naps at daycare and home", category: "parenting", text: "My [age]-old toddler naps well at daycare but not at home on weekends. Explain why the setting matters and how to copy the daycare routine at home. Give me a simple weekend nap plan with the same timing and steps." },
  { id: "parenting-117", title: "Baby sleep and growth spurts", category: "parenting", text: "Explain growth spurts in simple words and how they disturb sleep in a [age]-old baby. Tell me the common ages for spurts, the signs to watch for, and how extra feeds help. Reassure me that sleep settles again in a few days." },
  { id: "parenting-118", title: "Waking my baby for a feed", category: "parenting", text: "Explain when I should wake my [age]-old baby for a feed and when I can let them sleep. Cover newborns, low birth weight babies and older babies who sleep long stretches. Tell me what my doctor usually advises at this age." },
  { id: "parenting-119", title: "Toddler sleepwalking and talking", category: "parenting", text: "My [age]-old toddler talks and sometimes walks in sleep. Explain why this happens and whether it is normal at this age. Give me safety steps, such as locking doors and clearing the floor, and tell me when to ask a doctor." },
  { id: "parenting-120", title: "Baby sleep diary for tired parents", category: "parenting", text: "Make a simple sleep diary for my [age]-old baby that I can fill in quickly. Include bedtime, wake-ups, naps and feeds in a small table. Explain how to spot patterns after one week and what to change first." },
  { id: "parenting-121", title: "Helping my baby nap in the pram", category: "parenting", text: "Help me get my [age]-old baby to nap in the pram during a walk or outing. Give me tips for shade, gentle motion and a familiar blanket. Explain when pram naps are fine and when the baby needs a proper cot nap." },
  { id: "parenting-122", title: "Toddler bedtime and new sibling", category: "parenting", text: "My [age]-old toddler's sleep has become disturbed since the new baby arrived. Explain why this happens and how to give the toddler special bedtime attention. Give me a simple plan that includes the toddler in the new routine." },
  { id: "parenting-123", title: "Baby sleep and hot summer nights", category: "parenting", text: "Help my [age]-old baby sleep on hot summer nights without an air conditioner. Explain light cotton clothes, a fan at a safe distance, and a cool sponge bath before bed. Tell me how to check if the baby is too hot." },
  { id: "parenting-124", title: "Dropping from two naps to one", category: "parenting", text: "Explain how to move my [age]-old baby from two naps a day to one nap. List the signs they are ready, such as refusing the second nap. Give me a step-by-step plan over two weeks and tips for the tricky middle days." },
  { id: "parenting-125", title: "Baby sleep myths Indian parents hear", category: "parenting", text: "List five common baby sleep myths Indian parents hear, such as keeping the baby awake all day so they sleep at night. Explain why each one is wrong in simple words and what actually helps. Keep the tone kind towards grandparents." },
  { id: "parenting-126", title: "First foods for a six-month-old", category: "parenting", text: "List the best first foods for my six-month-old baby, such as rice porridge, mashed banana and dal water. Explain how to prepare each one simply and how much to offer at first. Tell me which foods to avoid before one year." },
  { id: "parenting-127", title: "Making ragi porridge for babies", category: "parenting", text: "Teach me to make ragi porridge for my [age]-old baby. Give the exact quantity of ragi flour and water, the cooking steps and how to make it smooth. Tell me how to add milk or mashed fruit, and how often to serve it." },
  { id: "parenting-128", title: "Baby's first khichdi recipe", category: "parenting", text: "Teach me to make a soft moong dal khichdi for my [age]-old baby. List the ingredients, the cooking steps and how to mash it well. Tell me when to add vegetables and ghee, and how to store leftovers safely." },
  { id: "parenting-129", title: "Introducing vegetables to my baby", category: "parenting", text: "Help me introduce vegetables to my [age]-old baby one at a time. Suggest easy first vegetables such as carrot, pumpkin and potato, and how to steam and mash them. Tell me how to watch for reactions and when to try a new one." },
  { id: "parenting-130", title: "Fruits my baby can eat first", category: "parenting", text: "List the safest first fruits for my [age]-old baby, such as banana, papaya, apple and chikoo. Explain how to prepare each one and how much to give. Tell me which fruits to wait on and how to avoid choking." },
  { id: "parenting-131", title: "Baby food chart from six months", category: "parenting", text: "Make a simple food chart for my baby from six months to one year. Show what to introduce each month, from purees to soft finger foods. Keep it in a table with meal ideas and a note to check with my doctor." },
  { id: "parenting-132", title: "My baby refuses to eat solids", category: "parenting", text: "My [age]-old baby pushes away every spoon of solid food. List the common reasons, such as not being ready, teething or a new taste. Give me gentle ways to try again, including finger foods and eating together as a family." },
  { id: "parenting-133", title: "Finger foods for my nine-month-old", category: "parenting", text: "List safe finger foods for my nine-month-old baby, such as soft idli pieces, steamed carrot sticks and banana slices. Explain how to cut them safely and how to sit the baby for meals. Add the foods to avoid because of choking." },
  { id: "parenting-134", title: "Baby food allergies to watch for", category: "parenting", text: "Explain the common food allergies in babies in simple words, such as egg, peanut and milk. Tell me how to introduce a new food safely, what signs to watch for, and what to do if my baby reacts. Add when to call a doctor." },
  { id: "parenting-135", title: "Making homemade baby food", category: "parenting", text: "Teach me to make and store homemade baby food for my [age]-old baby. Explain steaming, mashing and freezing in small portions. Tell me how long each food keeps in the fridge and freezer, and how to reheat it safely." },
  { id: "parenting-136", title: "Baby's first taste of curd", category: "parenting", text: "Explain when and how to give curd to my [age]-old baby. Tell me how much to offer, whether to use homemade curd, and how to mix it with rice or fruit. Add the signs that curd suits the baby and when to stop." },
  { id: "parenting-137", title: "Introducing egg to my baby", category: "parenting", text: "Explain when and how to introduce egg to my [age]-old baby. Tell me whether to start with yolk or the whole egg, how to cook it, and how much to give. Add the signs of an egg allergy and what to do if I see them." },
  { id: "parenting-138", title: "Baby meals for a busy working mum", category: "parenting", text: "Help me plan quick baby meals for my [age]-old baby while I work full time. Give me five meals I can cook in ten minutes, plus weekend batch-cooking ideas. Add a simple shopping list and storage tips for the week." },
  { id: "parenting-139", title: "My toddler is a picky eater", category: "parenting", text: "My [age]-old toddler eats only rice and curd and refuses everything else. Explain why picky eating is common at this age and give me gentle ways to offer new foods. Add tips for calm mealtimes and for not forcing bites." },
  { id: "parenting-140", title: "Introducing spices to baby food", category: "parenting", text: "Explain when and how to add mild spices such as turmeric, cumin and ajwain to my [age]-old baby's food. Tell me which spices to start with, how much to use, and which hot spices to avoid. Add a simple spiced khichdi recipe." },
  { id: "parenting-141", title: "Baby's first birthday food ideas", category: "parenting", text: "Give me simple, baby-friendly food ideas for my baby's first birthday party at home. Suggest soft foods the baby can eat and a small cake without too much sugar. Add tips for feeding the baby during the party rush." },
  { id: "parenting-142", title: "Feeding my baby at a restaurant", category: "parenting", text: "Help me feed my [age]-old baby at a restaurant in [city]. Tell me what to pack, which menu items are safe to share, and how to ask for plain food. Add tips for high chairs, mess and keeping the baby happy." },
  { id: "parenting-143", title: "My baby throws food on the floor", category: "parenting", text: "My [age]-old baby throws food on the floor at every meal. Explain why babies do this and whether it is normal. Give me calm ways to respond, such as a small portion, a mat under the chair and ending the meal gently." },
  { id: "parenting-144", title: "Iron-rich foods for my baby", category: "parenting", text: "List iron-rich foods for my [age]-old baby, such as dal, ragi, spinach and egg yolk. Explain why iron matters and how vitamin C from fruit helps the body absorb it. Give me three simple iron-rich meal ideas." },
  { id: "parenting-145", title: "Baby's first taste of fish", category: "parenting", text: "Explain when and how to introduce fish to my [age]-old baby. Tell me which fish are safest, how to cook and debone them, and how much to offer. Add the signs of a fish allergy and which fish to avoid." },
  { id: "parenting-146", title: "Making baby food while travelling", category: "parenting", text: "Help me feed my [age]-old baby on a [number]-day trip to [place]. Tell me what ready foods to pack, how to ask hotels for plain khichdi or porridge, and how to keep food fresh. Add a simple travel food checklist." },
  { id: "parenting-147", title: "My baby gags on lumpy food", category: "parenting", text: "My [age]-old baby gags when I offer lumpy food. Explain the difference between gagging and choking, and why gagging is a normal learning step. Give me ways to move slowly from smooth purees to soft lumps." },
  { id: "parenting-148", title: "Introducing nuts to my toddler", category: "parenting", text: "Explain when and how to introduce nuts to my [age]-old toddler safely. Tell me why whole nuts are a choking risk and how to use nut powders or smooth pastes instead. Add the signs of a nut allergy to watch for." },
  { id: "parenting-149", title: "Baby food and constipation", category: "parenting", text: "My [age]-old baby has become constipated since starting solids. Explain which foods help, such as papaya, prunes and water, and which foods can worsen it. Tell me when constipation needs a doctor." },
  { id: "parenting-150", title: "Mealtime routine for a toddler", category: "parenting", text: "Help me build a simple mealtime routine for my [age]-old toddler. Show three meals and two snacks at fixed times, with the family eating together. Add tips for a calm table, no TV during meals and a fixed meal length." },
  { id: "parenting-151", title: "My baby rolls over for the first time", category: "parenting", text: "My baby is [age] old and has just started rolling over. Explain what this milestone means, what comes next, and how to keep the baby safe now that they can move. Give me simple play ideas that build rolling and tummy strength." },
  { id: "parenting-152", title: "Tummy time for my newborn", category: "parenting", text: "Explain tummy time for my [age]-old baby in simple words. Tell me how long to do it each day, the best times, and how to make it fun with toys and talking. Add the signs that the baby is getting stronger." },
  { id: "parenting-153", title: "When will my baby sit up", category: "parenting", text: "Explain when babies usually sit up on their own and the stages before it, such as holding the head up and tripod sitting. Give me safe ways to practise sitting with pillows and play. Tell me when to ask a doctor." },
  { id: "parenting-154", title: "Helping my baby learn to crawl", category: "parenting", text: "Give me simple ways to help my [age]-old baby learn to crawl. Cover tummy time, placing toys just out of reach, and making a safe floor space. Explain that some babies skip crawling and go straight to walking." },
  { id: "parenting-155", title: "My baby's first steps", category: "parenting", text: "Explain how babies learn to walk, from pulling up to cruising along furniture to first steps. Tell me how to baby-proof the house, which shoes to choose, and how to cheer the baby on. Add when late walking needs a doctor." },
  { id: "parenting-156", title: "My baby's first words", category: "parenting", text: "Explain how babies learn to talk, from babbling to first words such as amma or appa. Tell me how to encourage talking by naming things, singing and reading. Add the signs of a speech delay and when to ask a doctor." },
  { id: "parenting-157", title: "Milestone chart for the first year", category: "parenting", text: "Make a simple milestone chart for my baby's first year, month by month. Show the usual skills for rolling, sitting, crawling, babbling and first words. Add a clear note that every baby develops at their own pace." },
  { id: "parenting-158", title: "My baby is not babbling yet", category: "parenting", text: "My [age]-old baby is not babbling much and I am worried. Explain when babbling usually starts, what counts as babbling, and how to encourage sounds through talking and songs. Tell me when to ask a doctor." },
  { id: "parenting-159", title: "Helping my baby hold their head up", category: "parenting", text: "Give me simple exercises to help my [age]-old baby hold their head up. Cover tummy time, carrying the baby upright and showing bright toys. Explain the usual age for head control and when to ask a doctor." },
  { id: "parenting-160", title: "My toddler is not walking yet", category: "parenting", text: "My [age]-old toddler is not walking yet and other children already are. Explain the normal range for first steps, the signs of steady progress, and how to encourage walking safely. Tell me when to ask a doctor." },
  { id: "parenting-161", title: "Play ideas for a six-month-old", category: "parenting", text: "Give me ten simple play ideas for my six-month-old baby using things at home, such as peekaboo, rattles and soft books. Explain how each game helps learning. Add tips for short play sessions and watching for tired signs." },
  { id: "parenting-162", title: "Play ideas for a one-year-old", category: "parenting", text: "Give me ten simple play ideas for my one-year-old baby, such as stacking steel vessels, rolling a ball and water play. Explain how each game builds hands, legs and talking. Add safety tips for play at home." },
  { id: "parenting-163", title: "My baby smiles and laughs", category: "parenting", text: "Explain when babies usually start smiling and laughing, and what these first social smiles mean. Tell me how to encourage smiles with faces, voices and peekaboo. Add when a lack of smiling needs a doctor." },
  { id: "parenting-164", title: "Teething signs and soothing tips", category: "parenting", text: "List the signs of teething in a [age]-old baby, such as drooling, chewing fingers and sore gums. Give me safe soothing ideas such as a cool teether, a clean wet cloth and gentle gum massage. Tell me which teething myths to ignore." },
  { id: "parenting-165", title: "My baby's first tooth care", category: "parenting", text: "Explain how to care for my baby's first teeth. Tell me when to start cleaning, how to wipe gums and teeth with a soft cloth, and when to use a tiny toothbrush. Add tips for the first dentist visit." },
  { id: "parenting-166", title: "Helping my baby wave and clap", category: "parenting", text: "Explain how babies learn gestures such as waving bye-bye and clapping. Tell me how to teach them through songs, games and copying. Add the usual age for these gestures and when a delay needs a doctor." },
  { id: "parenting-167", title: "My baby points at things now", category: "parenting", text: "My [age]-old baby has started pointing at things. Explain why pointing is an important milestone and how it links to talking. Give me ways to respond, such as naming the thing and asking simple questions." },
  { id: "parenting-168", title: "Milestones for a two-year-old", category: "parenting", text: "List the usual milestones for a two-year-old child, such as running, kicking a ball, two-word sentences and pretend play. Explain the wide normal range and how to support each skill. Add when to ask a doctor." },
  { id: "parenting-169", title: "My baby recognises family members", category: "parenting", text: "Explain when babies start recognising their mother, father and grandparents. Tell me how recognition shows, such as smiling or reaching out. Give me ways to help, like regular video calls with grandparents who live far away." },
  { id: "parenting-170", title: "Helping my baby learn to stack", category: "parenting", text: "Give me simple stacking games for my [age]-old baby using steel bowls, wooden blocks and plastic cups. Explain how stacking builds hand control and patience. Add tips for cheering the baby when the tower falls." },
  { id: "parenting-171", title: "My baby's first haircut at home", category: "parenting", text: "Help me plan my baby's first haircut at home. Explain the best time of day, how to keep the baby calm with a toy or snack, and which tools to use. Add safety tips and ideas for saving a small lock of hair." },
  { id: "parenting-172", title: "Baby's first words in two languages", category: "parenting", text: "Explain how babies learn two languages at home, such as Tamil and English. Tell me whether mixing languages confuses a baby and how to speak each language consistently. Give me simple ways to build words in both languages." },
  { id: "parenting-173", title: "My baby copies my actions", category: "parenting", text: "My [age]-old baby has started copying my actions, such as waving and brushing hair. Explain why copying is a key learning step and how to use it for teaching. Give me fun copy games to play together every day." },
  { id: "parenting-174", title: "Helping my baby learn to drink", category: "parenting", text: "Teach me how to help my [age]-old baby learn to drink from a cup. Explain the steps from a sippy cup to an open cup, how much water to offer, and how to handle spills calmly. Add tips for meals and outings." },
  { id: "parenting-175", title: "My toddler pretends to cook and talk", category: "parenting", text: "My [age]-old toddler pretends to cook, talk on the phone and feed dolls. Explain why pretend play matters and how it builds talking and imagination. Give me simple pretend play ideas using safe kitchen things at home." },
  { id: "parenting-176", title: "My baby has a fever", category: "parenting", text: "My [age]-old baby has a fever of [temperature]. Explain what to do at home, such as keeping the baby cool, offering fluids and checking the temperature. Tell me the warning signs that mean I should see a doctor at once." },
  { id: "parenting-177", title: "Baby cough and cold at home", category: "parenting", text: "My [age]-old baby has a cough and a runny nose. Give me safe home care tips, such as steam, saline drops and extra feeds. Tell me which signs, like fast breathing or poor feeding, mean I should see a doctor quickly." },
  { id: "parenting-178", title: "Diaper rash and how to heal it", category: "parenting", text: "My [age]-old baby has a red, sore bottom from nappies. Explain the common causes and how to heal it, such as frequent changes, air time and a barrier cream. Tell me when a rash needs a doctor." },
  { id: "parenting-179", title: "Baby vaccination schedule explained", category: "parenting", text: "Explain the vaccination schedule for my baby in the first year in simple words. List the main vaccines by age and what each one protects against. Tell me how to prepare, what reactions are normal, and when to call a doctor." },
  { id: "parenting-180", title: "My baby has loose motions", category: "parenting", text: "My [age]-old baby has had loose motions since yesterday. Explain the common causes and what to do at home, such as extra fluids and continued feeding. Tell me the danger signs of dehydration that need a doctor at once." },
  { id: "parenting-181", title: "Baby's first bath at home", category: "parenting", text: "Teach me to give my newborn their first bath at home. Explain the water temperature, what to prepare in advance, and how to hold and wash the baby safely. Add tips for drying, oiling and dressing the baby after the bath." },
  { id: "parenting-182", title: "Baby massage with coconut oil", category: "parenting", text: "Teach me a simple daily massage for my [age]-old baby using coconut oil. Explain gentle strokes for the legs, arms, tummy and back, and the best time of day. Tell me which oils to avoid and when not to massage." },
  { id: "parenting-183", title: "My baby cries for no reason", category: "parenting", text: "My [age]-old baby cries a lot and I cannot find the reason. List the things to check, such as hunger, a wet nappy, gas, tiredness or feeling hot. Give me calming steps and tell me when crying needs a doctor." },
  { id: "parenting-184", title: "Choosing baby clothes for summer", category: "parenting", text: "Help me choose comfortable clothes for my [age]-old baby in an Indian summer. Explain light cotton fabrics, loose fits and how many sets I need. Add tips for washing new clothes, sun protection and nightwear." },
  { id: "parenting-185", title: "Baby-proofing my home safely", category: "parenting", text: "Help me baby-proof my home before my [age]-old baby starts crawling. List the dangers room by room, such as sockets, sharp corners, small objects and stairs. Give me low-cost fixes and a checklist I can follow." },
  { id: "parenting-186", title: "My baby swallowed a small object", category: "parenting", text: "My [age]-old baby may have swallowed a small object. Explain what to do first, what not to do, and the signs of choking or trouble breathing. Tell me when to rush to the hospital and how to prevent it happening again." },
  { id: "parenting-187", title: "Baby's first visit to the doctor", category: "parenting", text: "Help me prepare for my [age]-old baby's first doctor visit. List the questions to ask, the records to carry, and what the doctor will check. Add tips for keeping the baby calm in the waiting room." },
  { id: "parenting-188", title: "My toddler has a temper tantrum", category: "parenting", text: "My [age]-old toddler throws tantrums in shops and at home. Explain why tantrums happen at this age and how to stay calm. Give me ways to prevent them, such as routines and choices, and what to do during one." },
  { id: "parenting-189", title: "Baby's cradle cap and dry scalp", category: "parenting", text: "My [age]-old baby has flaky yellow patches on the scalp. Explain what cradle cap is and why it happens. Give me gentle care steps, such as soft oiling and a soft brush. Tell me when it needs a doctor." },
  { id: "parenting-190", title: "My baby is scared of strangers", category: "parenting", text: "My [age]-old baby cries when strangers or relatives hold them. Explain stranger anxiety and why it is a normal stage. Give me ways to help, such as slow introductions and staying close, without forcing the baby." },
  { id: "parenting-191", title: "Choosing a safe baby carrier", category: "parenting", text: "Help me choose a safe baby carrier for my [age]-old baby within ₹[amount]. Explain what to check, such as hip support, back support and breathable fabric. Add tips for wearing it correctly and how long to carry the baby." },
  { id: "parenting-192", title: "My baby vomits in the car", category: "parenting", text: "My [age]-old baby vomits during car journeys. Explain why travel sickness happens in babies and how to reduce it, such as fresh air, a full stomach and frequent breaks. Tell me what to pack and when to see a doctor." },
  { id: "parenting-193", title: "Baby's first hair oil and skin care", category: "parenting", text: "Explain simple skin and hair care for my [age]-old baby. Tell me which mild oils and creams are safe, how often to apply them, and what to avoid. Add tips for dry skin in winter and rashes in summer." },
  { id: "parenting-194", title: "My baby bites other children", category: "parenting", text: "My [age]-old toddler bites other children while playing. Explain why toddlers bite and how to respond calmly in the moment. Give me ways to prevent biting, such as watching for tiredness and teaching gentle touch." },
  { id: "parenting-195", title: "Helping my baby adjust to daycare", category: "parenting", text: "Help me prepare my [age]-old baby for starting daycare in [city]. Explain how to visit first, leave for short periods, and keep a goodbye routine. Add tips for the first week and for handling tears at drop-off." },
  { id: "parenting-196", title: "My baby is afraid of the bath", category: "parenting", text: "My [age]-old baby cries every time I try to give a bath. Explain why babies fear baths and give me gentle steps to make bath time fun, such as warm water, toys and singing. Add tips for sponge baths as a break." },
  { id: "parenting-197", title: "Baby's nails and how to trim them", category: "parenting", text: "Teach me to trim my [age]-old baby's nails safely. Explain the best time, such as while the baby sleeps, and how to use baby nail clippers or a file. Tell me what to do if I nick the skin." },
  { id: "parenting-198", title: "My toddler hits when angry", category: "parenting", text: "My [age]-old toddler hits me when angry or frustrated. Explain why toddlers hit and how to respond without hitting back. Give me ways to teach words for feelings and to calm the child down." },
  { id: "parenting-199", title: "Baby's first flight journey", category: "parenting", text: "Help me plan my [age]-old baby's first flight to [place]. Tell me what documents to carry, how to feed during take-off and landing, and what to pack in the cabin bag. Add tips for ear pain and for keeping the baby settled." },
  { id: "parenting-200", title: "My baby wakes up with a cold", category: "parenting", text: "My [age]-old baby woke up with a blocked nose and mild fever. Explain how to tell a simple cold from something serious. Give me home care steps and a list of warning signs that mean I should see a doctor today." },
  { id: "parenting-201", title: "Choosing a pram for my baby", category: "parenting", text: "Help me choose a pram for my [age]-old baby within ₹[amount]. Compare light prams and sturdy prams in simple words. Tell me what to check, such as brakes, a flat seat for newborns and easy folding." },
  { id: "parenting-202", title: "My baby is constipated often", category: "parenting", text: "My [age]-old baby is constipated often and strains while passing stool. Explain the common causes at this age and safe home steps, such as fluids, fibre foods and tummy massage. Tell me when to see a doctor." },
  { id: "parenting-203", title: "Baby's first shoes and walking", category: "parenting", text: "Explain when my baby needs their first shoes and how to choose them. Tell me why bare feet help early walkers, what makes a good first shoe, and how to check the fit. Add tips for walking on different floors." },
  { id: "parenting-204", title: "My toddler refuses to brush teeth", category: "parenting", text: "My [age]-old toddler refuses to brush teeth every morning and night. Give me fun ways to make brushing a game, such as a song, a special brush and brushing together. Explain how much toothpaste to use at this age." },
  { id: "parenting-205", title: "Baby's first visit to grandparents", category: "parenting", text: "Help me plan my [age]-old baby's first long stay with grandparents in [city]. Tell me what to pack, how to share the feeding and sleep routine, and how to keep in touch by video calls. Add tips for a smooth goodbye." },
  { id: "parenting-206", title: "My baby has a heat rash", category: "parenting", text: "My [age]-old baby has small red bumps on the neck and chest in this heat. Explain what heat rash is and how to soothe it with cool baths, loose cotton clothes and air. Tell me when a rash needs a doctor." },
  { id: "parenting-207", title: "Helping my baby learn to share", category: "parenting", text: "My [age]-old toddler grabs toys and will not share. Explain why sharing is hard at this age and how to teach it gently through turn-taking games. Give me simple words to use when two children want the same toy." },
  { id: "parenting-208", title: "Baby's first monsoon care", category: "parenting", text: "Help me care for my [age]-old baby during the monsoon in [city]. Explain how to prevent damp clothes, mosquito bites and tummy infections. Add tips for drying clothes indoors, safe drinking water and keeping the home dry." },
  { id: "parenting-209", title: "My baby is a light sleeper", category: "parenting", text: "My [age]-old baby wakes at the smallest sound. Explain why some babies are light sleepers and how to help, such as a steady background sound and a dark room. Tell me whether light sleeping changes as the baby grows." },
  { id: "parenting-210", title: "Baby's first taste of cow milk", category: "parenting", text: "Explain when and how to introduce cow milk to my baby. Tell me the usual age, how much to give at first, and whether to boil it. Add the signs that cow milk suits the baby and when to ask a doctor." },
  { id: "parenting-211", title: "My toddler runs away in public", category: "parenting", text: "My [age]-old toddler runs away in markets and parks. Explain why toddlers run and how to keep them safe. Give me practical ideas, such as holding hands games, a wrist link and a meeting point rule." },
  { id: "parenting-212", title: "Baby's first dental checkup", category: "parenting", text: "Explain when to take my baby for the first dental checkup and what happens there. Tell me how to prepare a [age]-old baby, what the dentist checks, and how to make the visit calm. Add tips for daily tooth care." },
  { id: "parenting-213", title: "My baby is scared of loud sounds", category: "parenting", text: "My [age]-old baby cries at loud sounds such as mixer grinders and crackers. Explain why babies are sensitive to noise and how to comfort them. Give me ways to slowly get the baby used to everyday sounds." },
  { id: "parenting-214", title: "Helping my baby sleep in summer", category: "parenting", text: "Help my [age]-old baby sleep well on hot nights in [city]. Explain light bedding, a safe fan position and a cool bath before bed. Tell me how to check if the baby is too hot and what to avoid." },
  { id: "parenting-215", title: "Baby's first playgroup experience", category: "parenting", text: "Help me prepare my [age]-old toddler for their first playgroup in [city]. Explain what happens in a playgroup, what to pack, and how to handle separation tears. Add questions to ask the teacher on the first day." },
  { id: "parenting-216", title: "My baby refuses to wear shoes", category: "parenting", text: "My [age]-old baby pulls off shoes every time I put them on. Explain why babies dislike shoes and whether it matters. Give me tips for choosing soft, comfortable shoes and for letting the baby go barefoot safely indoors." },
  { id: "parenting-217", title: "Baby's first hair wash routine", category: "parenting", text: "Teach me a gentle hair wash routine for my [age]-old baby. Explain how often to wash, which mild shampoo to use, and how to keep soap out of the eyes. Add tips for drying the hair and for cradle cap." },
  { id: "parenting-218", title: "My toddler is jealous of the baby", category: "parenting", text: "My [age]-old toddler is jealous of the new baby and acts out. Explain why this happens and how to help, such as special time together and simple jobs like fetching a nappy. Give me words to use when feelings run high." },
  { id: "parenting-219", title: "Baby's first train journey", category: "parenting", text: "Help me plan my [age]-old baby's first train journey to [place]. Tell me what to pack, how to book a berth, and how to feed and change the baby on the train. Add safety tips for the platform and the journey." },
  { id: "parenting-220", title: "My baby has dry skin in winter", category: "parenting", text: "My [age]-old baby has dry, flaky skin in winter. Explain why winter dries baby skin and how to help with gentle oil, lukewarm baths and mild cream. Tell me when dry skin needs a doctor." },
  { id: "parenting-221", title: "Helping my baby learn names", category: "parenting", text: "Give me simple ways to help my [age]-old baby learn the names of family members, body parts and everyday things. Explain naming games, songs and picture books. Add the usual age for first words and when to ask a doctor." },
  { id: "parenting-222", title: "Baby's first birthday party at home", category: "parenting", text: "Help me plan a simple first birthday party for my baby at home with [number] guests. Give me a guest list, decoration ideas, food and a short schedule. Add tips for keeping the baby happy and rested during the party." },
  { id: "parenting-223", title: "My toddler will not sit still", category: "parenting", text: "My [age]-old toddler will not sit still for meals, stories or travel. Explain why toddlers need to move and how to channel that energy. Give me calm activities, such as puzzles and drawing, for short sitting times." },
  { id: "parenting-224", title: "Baby's first visit to the park", category: "parenting", text: "Help me plan my [age]-old baby's first visit to the park in [city]. Tell me what to pack, the best time of day, and how to protect the baby from sun and mosquitoes. Add simple play ideas for the grass." },
  { id: "parenting-225", title: "My baby's daily routine at one year", category: "parenting", text: "Make a simple daily routine for my one-year-old baby from waking up to bedtime. Include feeds, meals, naps, play, bath and story time with timings. Keep it flexible for festival days and outings with family." },
  { id: "parenting-226", title: "Help my child settle into school", category: "parenting", text: "My [5-year-old] starts school next month and feels nervous about it. Give me a simple two-week plan to prepare [him/her], including what to talk about, a morning practice routine, and how to handle tears on the first day. Keep the advice gentle and practical." },
  { id: "parenting-227", title: "Morning routine for a school child", category: "parenting", text: "Make a calm morning routine for my [6-year-old] who goes to school at [time]. Include wake-up time, brushing, breakfast, dressing, bag packing and leaving on time. Suggest what to prepare the night before so mornings feel less rushed." },
  { id: "parenting-228", title: "Pack a healthy school tiffin box", category: "parenting", text: "Suggest 5 easy tiffin box ideas for my [7-year-old] for one school week. Each lunch should take under 20 minutes to make, stay fresh till lunchtime, and use simple Indian food. Add one packing tip for each day." },
  { id: "parenting-229", title: "Choose the right school bag", category: "parenting", text: "Help me choose a school bag for my [6-year-old] in class [1]. Tell me what size to pick, how heavy it should be, which features matter most, and what to avoid. Give a simple checklist I can use while shopping in [your city]." },
  { id: "parenting-230", title: "Talk to my child after school", category: "parenting", text: "Give me 10 simple questions I can ask my [7-year-old] after school instead of saying how was your day. The questions should help [him/her] talk about friends, lessons and feelings. Keep them fun, short and easy for a young child to answer." },
  { id: "parenting-231", title: "Help my child make school friends", category: "parenting", text: "My [5-year-old] is shy and finds it hard to make friends at school. Give me 8 practical ideas I can use at home and in the park to build [his/her] confidence. Include simple games, phrases to practise, and what to say to the teacher." },
  { id: "parenting-232", title: "Prepare my child for the first exam", category: "parenting", text: "My [7-year-old] has [his/her] first small test at school next week. Give me a gentle 5-day revision plan with short 20-minute sessions, fun ways to revise, and tips to keep [him/her] calm. Do not add pressure or long study hours." },
  { id: "parenting-233", title: "Deal with school separation anxiety", category: "parenting", text: "My [4-year-old] cries every morning at the school gate and clings to me. Give me a step-by-step goodbye routine, things to say and things to avoid, and ideas to practise separation at home. Tell me when to speak to the teacher." },
  { id: "parenting-234", title: "Teach my child to write neatly", category: "parenting", text: "My [6-year-old] writes letters too big and uneven. Suggest 10 fun daily activities to improve handwriting, like tracing, drawing lines and holding the pencil correctly. Give a 15-minute practice plan for two weeks." },
  { id: "parenting-235", title: "Help my child learn numbers at home", category: "parenting", text: "Give me 12 playful ways to teach numbers to my [5-year-old] using things at home, like spoons, buttons, stairs and coins. Each activity should take under 10 minutes and feel like a game, not a lesson. Include counting up to 50." },
  { id: "parenting-236", title: "Support my child with homework", category: "parenting", text: "My [8-year-old] takes two hours to finish 30 minutes of homework. Help me set up a homework routine with a fixed time, a quiet corner, short breaks and a simple reward chart. Tell me how to help without doing the work for [him/her]." },
  { id: "parenting-237", title: "Talk to the teacher about my child", category: "parenting", text: "I have a parent-teacher meeting for my [6-year-old] next week. Give me 10 useful questions to ask the teacher about learning, behaviour and friendships. Also suggest how to share a concern politely and what to note down after the meeting." },
  { id: "parenting-238", title: "Help my child handle school bullying", category: "parenting", text: "My [7-year-old] says an older child teases [him/her] at school. Give me calm steps to take: what to ask my child, what to tell the teacher, and how to rebuild [his/her] confidence. Keep the advice gentle and practical for a young child." },
  { id: "parenting-239", title: "Plan a school holiday at home", category: "parenting", text: "School is closed for [10 days] and my [6-year-old] will be at home. Plan a simple daily schedule with play, reading, outdoor time, one learning activity and rest. Use things we already have at home and keep the cost under ₹500 for the whole break." },
  { id: "parenting-240", title: "Teach my child road safety", category: "parenting", text: "Teach my [5-year-old] basic road safety in simple words. Explain how to cross the road, what zebra crossings and traffic lights mean, and why to hold an adult's hand. Give 3 fun practice games we can play near our home in [your area]." },
  { id: "parenting-241", title: "Help my child learn the alphabet", category: "parenting", text: "Give me a 4-week plan to teach the alphabet to my [4-year-old] through songs, flashcards, sand tracing and naming things around the house. Keep each session to 10 minutes and make it playful. Tell me how to know when [he/she] is ready to move on." },
  { id: "parenting-242", title: "Build my childs confidence for class", category: "parenting", text: "My [7-year-old] is afraid to speak in class or answer questions. Give me 10 small daily confidence builders, like speaking games at dinner, show-and-tell practice at home, and praise that works. Explain how to talk to the teacher about it." },
  { id: "parenting-243", title: "Organise my childs school supplies", category: "parenting", text: "Help me organise my [6-year-old]'s school bag, books, pencils, crayons and water bottle for the new term. Give me a labelling system, a weekly bag-check routine, and ideas to stop things getting lost. Keep it simple enough for a child to follow." },
  { id: "parenting-244", title: "Help my child follow school rules", category: "parenting", text: "My [5-year-old] finds it hard to sit still and follow rules in class. Explain in simple words why school rules exist, and give me 8 home activities that practise listening, waiting and taking turns. Suggest what to discuss with the teacher." },
  { id: "parenting-245", title: "Teach my child to tie shoelaces", category: "parenting", text: "Teach my [6-year-old] to tie [his/her] shoelaces with a simple step-by-step method a young child can follow. Include a fun rhyme, a practice trick using a cardboard shoe, and how long to practise each day. Keep the steps short and clear." },
  { id: "parenting-246", title: "Prepare my child for a school trip", category: "parenting", text: "My [7-year-old] is going on a school trip to [place] next week. Give me a packing checklist, what to discuss the night before, and how to ease [his/her] worries about being away from home. Include food, water, clothes and safety tips." },
  { id: "parenting-247", title: "Help my child learn simple addition", category: "parenting", text: "Give me 10 fun ways to teach simple addition to my [6-year-old] using toys, fruits, fingers and coins. Each game should take under 10 minutes and build up to adding numbers up to 20. Tell me how to praise effort, not just correct answers." },
  { id: "parenting-248", title: "Handle my childs fear of the dark", category: "parenting", text: "My [5-year-old] is afraid of the dark at bedtime and wants the light on all night. Give me a gentle 2-week plan with a night light, a bedtime story routine, and brave-talk phrases. Explain what to avoid saying so the fear does not grow." },
  { id: "parenting-249", title: "Teach my child to share toys", category: "parenting", text: "My [4-year-old] refuses to share toys with cousins and friends. Give me 8 practical ways to teach sharing through play, turn-taking games and simple words [he/she] can use. Explain how to handle a fight over a toy calmly without taking sides." },
  { id: "parenting-250", title: "Make school mornings less stressful", category: "parenting", text: "Our school mornings are full of shouting and rushing. Give me a realistic plan to fix this for my [6-year-old]: a night-before checklist, a visual morning chart, and calm phrases to use when we are late. Keep the routine under one hour." },
  { id: "parenting-251", title: "Help my child remember spellings", category: "parenting", text: "My [8-year-old] forgets spellings for the weekly dictation test. Give me 10 fun memory tricks like breaking words into sounds, drawing, rhymes and spelling games. Plan 10-minute daily practice sessions for one week before the test." },
  { id: "parenting-252", title: "Teach my child to count money", category: "parenting", text: "Teach my [7-year-old] to recognise Indian coins and notes and count small amounts up to ₹100. Give me 5 shop games we can play at home with real coins, like buying pretend vegetables. Keep the games simple and fun." },
  { id: "parenting-253", title: "Help my child cope with losing a game", category: "parenting", text: "My [6-year-old] cries and gets angry every time [he/she] loses a board game. Give me phrases to use, simple games where losing happens often, and a plan to teach good sportsmanship over two weeks. Keep the tone kind and encouraging." },
  { id: "parenting-254", title: "Plan a birthday party for my child", category: "parenting", text: "Plan a simple birthday party at home for my [5-year-old] with [15] children. Give me a budget under ₹3,000, a 2-hour plan with games, food and cake, and a decoration list using things from home. Include Jain vegetarian food ideas." },
  { id: "parenting-255", title: "Teach my child to tell the time", category: "parenting", text: "Teach my [7-year-old] to tell the time using a wall clock and a paper clock we make together. Start with o'clock and half past, then move to quarter past. Give me 5 daily practice games and a simple way to check progress." },
  { id: "parenting-256", title: "Start a bedtime story routine", category: "parenting", text: "Start a 15-minute bedtime story routine for my [4-year-old]. Suggest how to pick stories, how to read with voices and questions, and how to end the night calmly. Give me a list of 10 story themes suitable for young children in India." },
  { id: "parenting-257", title: "Help my child read simple words", category: "parenting", text: "My [5-year-old] knows letters but struggles to read simple three-letter words. Give me a 3-week plan with daily 10-minute phonics games, word cards and simple books. Tell me how to celebrate small wins without pushing too hard." },
  { id: "parenting-258", title: "Choose first books for my child", category: "parenting", text: "Recommend 15 first books for my [6-year-old] who is just starting to read alone. Mix picture books, simple stories and Indian tales. For each book, give the reading level, why children enjoy it, and where to find it in [your city]." },
  { id: "parenting-259", title: "Make reading fun every day", category: "parenting", text: "Give me 12 ways to make reading fun for my [7-year-old] who says books are boring. Include reading under a blanket with a torch, comic books, reading to a pet, and choosing books together. Each idea should take under 20 minutes." },
  { id: "parenting-260", title: "Start a read-aloud routine with my child", category: "parenting", text: "Help me start a read-aloud routine with my [5-year-old] for fifteen minutes every night. Suggest how to pick the story together, use funny voices, ask one question after each page, and keep a small list of books we finished." },
  { id: "parenting-261", title: "Read with my child in two languages", category: "parenting", text: "We speak [Tamil/Hindi] at home and my [6-year-old] reads English at school. Give me a simple plan to read stories in both languages each week, with tips to keep [him/her] interested and not confused. Suggest 5 bilingual book ideas." },
  { id: "parenting-262", title: "Help my child understand a story", category: "parenting", text: "After reading a story, my [7-year-old] cannot retell what happened. Give me 10 simple questions to ask during and after reading, like who did what and why. Include a drawing activity to help [him/her] remember the story." },
  { id: "parenting-263", title: "Create a reading corner at home", category: "parenting", text: "Create a cosy reading corner for my [5-year-old] in a small flat with almost no extra money. Suggest where to place it, what to use for seating and light, and how to display books so [he/she] picks them up. Keep the setup under ₹500." },
  { id: "parenting-264", title: "Teach my child new words daily", category: "parenting", text: "Give me a 30-day plan to teach my [6-year-old] one new English word every day. Each word should come with a simple meaning, a sentence, and a fun way to use it at home. Include words about food, animals, school and feelings." },
  { id: "parenting-265", title: "Help my child write a short story", category: "parenting", text: "Help my [8-year-old] write a short story of 8 to 10 lines for a school competition. Give me a simple plan with a character, a place, a problem and a happy ending. Suggest story starters and how to help without writing it for [him/her]." },
  { id: "parenting-266", title: "Pick rhymes for my young child", category: "parenting", text: "Suggest 15 simple rhymes and songs for my [4-year-old] in English and [Hindi/Tamil], with actions to do while singing. Tell me how to use them during bath time, travel and bedtime. Keep the list easy for a parent to learn quickly." },
  { id: "parenting-267", title: "Help my child read shop signs", category: "parenting", text: "Turn everyday outings into reading practice for my [6-year-old]. Give me 10 games for reading shop boards, bus numbers, food packets and street signs in [your city]. Each game should take under 5 minutes and feel like a treasure hunt." },
  { id: "parenting-268", title: "Teach my child to love storybooks", category: "parenting", text: "My [5-year-old] prefers cartoons to books. Give me a 2-week plan to build a love of storybooks with short daily sessions, funny voices, choosing books together and a small reward chart. Tell me how to reduce screen time gently during this plan." },
  { id: "parenting-269", title: "Make a picture word book together", category: "parenting", text: "Help me make a picture word book with my [4-year-old] using old magazines, drawings and photos. Give me a step-by-step plan for 10 pages about home, food, animals and family. Tell me how to use the book for daily word practice." },
  { id: "parenting-270", title: "Help my child read aloud confidently", category: "parenting", text: "My [7-year-old] reads well silently but mumbles when reading aloud. Give me 8 fun read-aloud games, like reading to a toy, recording a story, and echo reading with me. Plan 10-minute daily practice for two weeks." },
  { id: "parenting-271", title: "Choose comics for a young reader", category: "parenting", text: "Recommend 10 comic books and picture comics suitable for my [7-year-old] who is learning to read. For each one, tell me the reading level, what it is about, and why it helps new readers. Include Indian comics and simple English ones." },
  { id: "parenting-272", title: "Help my child learn rhyming words", category: "parenting", text: "Give me 10 playful activities to teach rhyming words to my [5-year-old], like matching games, silly songs and rhyming pairs from daily life. Each activity should take under 10 minutes. Tell me how to build from easy pairs to harder ones." },
  { id: "parenting-273", title: "Read festival stories with my child", category: "parenting", text: "Suggest 8 simple festival stories I can read with my [6-year-old] for Diwali, Holi, Pongal and Raksha Bandhan. For each story, give a 2-line summary, one question to ask after reading, and a small craft or activity linked to the festival." },
  { id: "parenting-274", title: "Help my child sound out words", category: "parenting", text: "My [6-year-old] guesses words instead of sounding them out. Give me a simple phonics plan with letter sounds, blending games and word lists for two weeks. Tell me what to do when [he/she] gets stuck and how to keep practice short and fun." },
  { id: "parenting-275", title: "Start a family reading time", category: "parenting", text: "Start a 20-minute family reading time every evening for my [5-year-old] and [8-year-old]. Give me a weekly plan where everyone reads together, including what parents can read, how to handle different ages, and a simple way to track finished books." },
  { id: "parenting-276", title: "Help my child write a thank-you note", category: "parenting", text: "Help my [7-year-old] write a short thank-you note to [grandmother/teacher] after receiving a gift. Give me a simple 4-line structure, example sentences [he/she] can copy, and tips to make the note personal. Keep the note short and sincere." },
  { id: "parenting-277", title: "Teach my child to write a diary", category: "parenting", text: "Help my [8-year-old] start a simple diary with 3 lines a day about school, play and feelings. Give me a 2-week starter plan with prompts for each day, ideas for drawings, and tips to keep it private and fun, not homework." },
  { id: "parenting-278", title: "Make learning letters with playdough", category: "parenting", text: "Give me 8 playdough activities to teach letters to my [4-year-old], like rolling letter shapes, stamping letters and matching letters to pictures. Tell me how to make simple playdough at home and how long each activity should last." },
  { id: "parenting-279", title: "Help my child read a simple recipe", category: "parenting", text: "Let my [7-year-old] read a simple recipe and help me cook it. Choose a 5-step Indian snack recipe, and give me tips to let [him/her] read the steps, measure ingredients and follow the order. Include safety rules for the kitchen." },
  { id: "parenting-280", title: "Build vocabulary through nature walks", category: "parenting", text: "Give me a plan for weekly nature walks with my [5-year-old] in [your area] that build vocabulary. Include 10 things to spot and name, questions to ask, and a simple nature word book we can fill together after each walk." },
  { id: "parenting-281", title: "Teach my child the days of the week", category: "parenting", text: "Teach my [5-year-old] the days of the week with songs, a wall chart and daily questions. Give me a 2-week plan with one fun activity per day, like linking each day to a food or activity. Tell me how to check what [he/she] remembers." },
  { id: "parenting-282", title: "Help my child learn the months", category: "parenting", text: "Teach my [7-year-old] the 12 months of the year with a birthday chart, festival links and a simple song. Give me a 4-week plan with weekly activities and a drawing task for each season. Keep each session under 15 minutes." },
  { id: "parenting-283", title: "Make a weather chart with my child", category: "parenting", text: "Help me make a daily weather chart with my [6-year-old] for one month. Tell me what to record each morning, how to draw sun, rain and cloud symbols, and what simple questions to ask. Explain how this teaches observation and seasons." },
  { id: "parenting-284", title: "Teach my child to follow instructions", category: "parenting", text: "My [5-year-old] forgets multi-step instructions like wash hands, then sit for lunch. Give me 10 games that practise following 2-step and 3-step instructions, like Simon Says and cooking together. Tell me how to give instructions clearly at home." },
  { id: "parenting-285", title: "Help my child learn colours and shapes", category: "parenting", text: "Give me 12 home activities to teach colours and shapes to my [4-year-old] using toys, clothes, food and things in the kitchen. Each activity should take under 10 minutes. Include a simple sorting game and a colour hunt around the house." },
  { id: "parenting-286", title: "Build a bedtime routine that works", category: "parenting", text: "My [6-year-old] takes an hour to fall asleep and keeps getting out of bed. Build a calm 45-minute bedtime routine with bath, brushing, story and lights out. Give me phrases to use when [he/she] stalls and tips to keep the routine the same every night." },
  { id: "parenting-287", title: "Teach my child to brush teeth properly", category: "parenting", text: "Teach my [4-year-old] to brush teeth twice a day without a fight. Give me a fun 2-minute brushing song, a sticker chart plan for two weeks, and simple words to explain why brushing matters. Tell me how much toothpaste to use." },
  { id: "parenting-288", title: "Help my child eat vegetables happily", category: "parenting", text: "My [5-year-old] refuses to eat vegetables. Give me 10 gentle ideas like letting [him/her] pick vegetables at the shop, funny food faces on the plate, and hiding vegetables in parathas. Tell me what not to do so mealtimes stay peaceful." },
  { id: "parenting-289", title: "Set a healthy sleep schedule", category: "parenting", text: "My [7-year-old] sleeps at 11 pm and wakes up tired for school. Help me move bedtime to 9 pm over two weeks with small daily shifts, a wind-down routine, and rules about screens after dinner. Include a weekend plan that keeps the same timings." },
  { id: "parenting-290", title: "Teach my child to wash hands well", category: "parenting", text: "Teach my [4-year-old] to wash hands properly before meals and after using the toilet. Give me a 20-second handwash song, a step-by-step chart for the bathroom wall, and a fun glitter germ game that shows why soap matters." },
  { id: "parenting-291", title: "Make bath time fun and calm", category: "parenting", text: "My [5-year-old] hates bath time and runs away. Give me 10 ideas to make baths fun, like foam shapes, toy boats, songs and choosing a towel. Include safety tips and a simple routine that takes under 20 minutes." },
  { id: "parenting-292", title: "Teach my child to dress independently", category: "parenting", text: "Help my [5-year-old] learn to dress [himself/herself] without help. Give me a step-by-step plan for buttons, zips and putting clothes on the right way round. Include a morning clothes chart and tips to stay patient when it takes longer." },
  { id: "parenting-293", title: "Help my child stop sucking thumb", category: "parenting", text: "My [6-year-old] still sucks [his/her] thumb at bedtime. Give me a gentle plan with a comfort toy, praise for thumb-free nights, and a simple chart. Tell me what to avoid, like scolding or bitter creams, and when to ask a dentist." },
  { id: "parenting-294", title: "Plan a healthy weekly food menu", category: "parenting", text: "Plan a simple weekly food menu for my [7-year-old] with breakfast, lunch, snacks and dinner for 7 days. Use common Indian food, keep cooking time under 30 minutes per meal, and include one new food to try each week. Add a shopping list." },
  { id: "parenting-295", title: "Teach my child to drink enough water", category: "parenting", text: "My [6-year-old] forgets to drink water at school and comes home with a full bottle. Give me 8 fun ways to build a water habit, like a colourful bottle, water reminders and a daily chart. Tell me how much water a child this age needs." },
  { id: "parenting-296", title: "Help my child cope with a new sibling", category: "parenting", text: "We have a new baby and my [5-year-old] feels left out and acts up. Give me 10 ways to help [him/her] feel special, like a daily 10-minute one-to-one time, small helper jobs and honest words about the baby. Keep the ideas simple and loving." },
  { id: "parenting-297", title: "Set screen time rules for my child", category: "parenting", text: "Help me set fair screen time rules for my [7-year-old]: how much TV and tablet time per day, which times are screen-free, and what to offer instead. Give me a simple family agreement we can stick on the fridge and tips to handle protests." },
  { id: "parenting-298", title: "Teach my child to tidy toys", category: "parenting", text: "My [6-year-old] leaves toys everywhere and tidying ends in tears. Give me a simple tidy-up system with labelled boxes, a 5-minute tidy song, and a game that makes cleaning fun. Tell me how to praise effort and keep the rule consistent." },
  { id: "parenting-299", title: "Help my child eat breakfast daily", category: "parenting", text: "My [8-year-old] skips breakfast before school and feels hungry by 10 am. Give me 7 quick breakfast ideas that take under 10 minutes, plus tips to wake up 15 minutes earlier. Include options [he/she] can help prepare the night before." },
  { id: "parenting-300", title: "Teach my child to use the toilet alone", category: "parenting", text: "My [4-year-old] still needs help in the toilet at school. Give me a gentle plan to build independence with wiping, flushing, washing hands and asking the teacher for help. Include practice steps at home and words [he/she] can use at school." },
  { id: "parenting-301", title: "Build a weekend routine for family", category: "parenting", text: "Build a simple weekend routine for our family with my [6-year-old]: one outdoor outing, one learning activity, one helping task and free play. Give me a Saturday and Sunday plan that fits around chores and costs under ₹500 per weekend." },
  { id: "parenting-302", title: "Help my child stop nail biting", category: "parenting", text: "My [7-year-old] bites [his/her] nails when bored or worried. Give me a gentle 3-week plan with a stress ball, short nails, praise for calm hands and a simple chart. Tell me what to say when I notice it and what not to do." },
  { id: "parenting-303", title: "Teach my child to pack lunch alone", category: "parenting", text: "Teach my [8-year-old] to pack [his/her] own school lunch box the night before. Give me a simple checklist with a main dish, fruit, snack and water bottle. Include ideas [he/she] can choose from and a weekly menu chart for the fridge." },
  { id: "parenting-304", title: "Help my child handle a haircut", category: "parenting", text: "My [4-year-old] cries at every haircut and refuses to sit still. Give me a plan with a practice haircut at home, a favourite toy to hold, choosing the barber together, and a small treat after. Include words to prepare [him/her] the day before." },
  { id: "parenting-305", title: "Teach my child to cross the road safely", category: "parenting", text: "My [6-year-old] is starting to walk to a nearby shop with me. Teach [him/her] to stop, look both ways, listen for vehicles and cross only at safe spots. Give me 3 practice walks and simple rules to repeat every time we go out." },
  { id: "parenting-306", title: "Teach my child to say please", category: "parenting", text: "Teach my [4-year-old] to say please and thank you every day. Give me 8 fun practice games, like a polite words jar, role play at dinner, and praising polite words when I hear them. Tell me how to model good manners myself at home." },
  { id: "parenting-307", title: "Help my child greet guests politely", category: "parenting", text: "My [6-year-old] hides behind me when guests come home. Give me a gentle plan with practising greetings at home, a special greeting [he/she] can choose, and what to do when [he/she] feels shy. Keep the advice kind and pressure-free." },
  { id: "parenting-308", title: "Teach my child table manners", category: "parenting", text: "Teach my [7-year-old] simple table manners for family meals and eating at a relative's house. Cover washing hands, waiting for elders, chewing with mouth closed, and asking before leaving the table. Give me a fun weekly practice idea." },
  { id: "parenting-309", title: "Help my child apologise sincerely", category: "parenting", text: "My [6-year-old] says sorry quickly but does not mean it. Teach [him/her] how to apologise properly: what happened, how the other person felt, and what to do next time. Give me role-play examples and words [he/she] can practise." },
  { id: "parenting-310", title: "Teach my child to wait patiently", category: "parenting", text: "My [5-year-old] cannot wait for anything and interrupts constantly. Give me 10 games that build patience, like waiting for a turn, a timer challenge, and cooking together. Tell me how to praise waiting and what to do during long waits." },
  { id: "parenting-311", title: "Help my child respect elders", category: "parenting", text: "Help my [7-year-old] learn to respect elders in our Indian family: greeting grandparents, listening when they speak, and helping them with small tasks. Give me 8 daily habits and simple words to explain why respect matters." },
  { id: "parenting-312", title: "Teach my child not to interrupt", category: "parenting", text: "My [6-year-old] interrupts adults all the time. Give me a simple system with a hand-on-arm signal, a waiting spot, and praise for waiting. Include a 2-week practice plan and what to say when [he/she] forgets the rule." },
  { id: "parenting-313", title: "Help my child use kind words", category: "parenting", text: "My [5-year-old] uses rude words picked up from older children. Give me calm steps to respond, better words to teach instead, and a plan to check what [he/she] watches and hears. Tell me how to stay calm and consistent." },
  { id: "parenting-314", title: "Teach my child to knock before entering", category: "parenting", text: "Teach my [7-year-old] to knock before entering a closed room and to respect privacy at home. Give me a simple rule chart, a fun practice game, and words to explain why privacy matters. Include how to handle it when [he/she] forgets." },
  { id: "parenting-315", title: "Help my child behave at a wedding", category: "parenting", text: "We have a family wedding and my [6-year-old] gets restless at long functions. Give me a plan with what to pack, how to prepare [him/her] beforehand, quiet activities for the ceremony, and phrases to explain expected behaviour simply." },
  { id: "parenting-316", title: "Teach my child to share with siblings", category: "parenting", text: "My two children aged [5 and 7] fight over toys every day. Give me a fair sharing system with turn timers, shared toy rules, and a family meeting plan. Tell me how to step in calmly and how to praise good sharing." },
  { id: "parenting-317", title: "Help my child handle teasing from cousins", category: "parenting", text: "My [7-year-old] gets upset when cousins tease [him/her] at family gatherings. Give me words [he/she] can say back calmly, ways to walk away, and how I can support [him/her] without making it a big fight. Keep the advice practical." },
  { id: "parenting-318", title: "Teach my child honesty at home", category: "parenting", text: "My [6-year-old] tells small lies to avoid trouble. Give me a gentle approach that builds honesty: staying calm when [he/she] confesses, praising truth-telling, and simple stories about honesty. Tell me what never to do when a child lies." },
  { id: "parenting-319", title: "Help my child say sorry to a friend", category: "parenting", text: "My [5-year-old] pushed a friend at school and now feels bad. Guide me through helping [him/her] apologise the next day with simple words, a drawing or a kind gesture. Tell me what to say at home first and how to practise together." },
  { id: "parenting-320", title: "Teach my child to listen carefully", category: "parenting", text: "My [7-year-old] does not listen when I give instructions. Give me 10 listening games like whisper chain, following a story, and repeating back instructions. Tell me how to get [his/her] attention first and how to keep instructions short." },
  { id: "parenting-321", title: "Help my child behave in a restaurant", category: "parenting", text: "We are eating out with my [5-year-old] this weekend. Give me a plan with what to explain before we go, quiet activities to carry, how to order food together, and what to do if [he/she] gets restless. Keep the outing under one hour." },
  { id: "parenting-322", title: "Teach my child to take turns", category: "parenting", text: "My [4-year-old] grabs toys and will not wait for a turn. Give me 8 turn-taking games with a timer, a talking stick and simple board games. Tell me how to practise at home daily for two weeks and how to handle tears when waiting." },
  { id: "parenting-323", title: "Help my child respect other children", category: "parenting", text: "My [8-year-old] laughs when classmates make mistakes. Give me ways to build kindness: stories about feelings, praising kind behaviour, and simple words to use when [he/she] is unkind. Tell me how to talk to the teacher if it continues." },
  { id: "parenting-324", title: "Teach my child to keep promises", category: "parenting", text: "Teach my [7-year-old] why keeping small promises matters. Give me 5 everyday examples, like returning a borrowed pencil, and a simple promise chart for one week. Tell me how to model promise-keeping as a parent." },
  { id: "parenting-325", title: "Help my child greet the teacher daily", category: "parenting", text: "My [5-year-old] is too shy to greet the teacher in the morning. Give me a gentle plan with practising greetings at home, a wave or smile as a first step, and a small reward for trying. Tell me how to ask the teacher to help." },
  { id: "parenting-326", title: "Teach my child to ask for help", category: "parenting", text: "My [6-year-old] gets upset instead of asking for help with homework or opening a box. Teach [him/her] simple words to ask for help, like please help me with this. Give me 5 practice situations and tips to praise asking, not struggling alone." },
  { id: "parenting-327", title: "Help my child handle disappointment", category: "parenting", text: "My [7-year-old] falls apart when plans change, like a cancelled picnic. Give me words to comfort [him/her], a backup plan idea, and a 2-week plan to build flexibility with small changes. Keep the tone warm and realistic." },
  { id: "parenting-328", title: "Teach my child to be gentle with pets", category: "parenting", text: "We have a pet dog and my [5-year-old] pulls its ears and tail. Teach [him/her] gentle hands with simple rules, a practice game with a soft toy, and what to do when the dog walks away. Include safety rules for playing with pets." },
  { id: "parenting-329", title: "Help my child stop whining", category: "parenting", text: "My [6-year-old] whines for everything, from food to toys. Give me a calm plan: how to respond the first time, a simple phrase to teach instead of whining, and how to stay consistent for two weeks. Tell me what to do in public." },
  { id: "parenting-330", title: "Teach my child to care for books", category: "parenting", text: "My [5-year-old] tears pages and leaves books on the floor. Teach [him/her] to handle books gently with a book-care song, a special book shelf, and a repair kit for torn pages. Give me a 2-week plan to build the habit." },
  { id: "parenting-331", title: "Help my child make a new friend", category: "parenting", text: "My [8-year-old] wants to make a new friend at school but does not know how to start. Give me simple opening lines, ideas for playing together at break time, and how to invite a friend home. Tell me how to support [him/her] if it does not work." },
  { id: "parenting-332", title: "Teach my child to accept no", category: "parenting", text: "My [5-year-old] screams when I say no to a toy or a sweet. Give me a calm way to say no, words to explain the reason simply, and a plan to handle the tears without giving in. Include a practice game for accepting no gracefully." },
  { id: "parenting-333", title: "Help my child be kind to grandparents", category: "parenting", text: "Help my [6-year-old] build a warm bond with grandparents who live far away. Give me 10 ideas like weekly video calls, sending drawings by post, and asking them for stories. Tell me how to make calls fun and not a chore." },
  { id: "parenting-334", title: "Teach my child to clean up after play", category: "parenting", text: "My [7-year-old] never cleans up after playing. Give me a simple clean-up rule, like one toy out at a time, a 5-minute tidy-up race, and a chart for one week. Tell me how to stay firm without turning it into a daily fight." },
  { id: "parenting-335", title: "Help my child handle a broken toy", category: "parenting", text: "My [5-year-old] cries for hours when a toy breaks. Give me words to comfort [him/her], ideas to fix or reuse the toy together, and a plan to teach that things can break. Tell me when to replace a toy and when not to." },
  { id: "parenting-336", title: "Teach my child to speak softly indoors", category: "parenting", text: "My [6-year-old] shouts inside the house all day. Give me a fun voice-level game with indoor voice and outdoor voice, a volume chart for the wall, and tips to practise during meals and play. Tell me how to remind [him/her] gently." },
  { id: "parenting-337", title: "Help my child share food with friends", category: "parenting", text: "My [7-year-old] will not share tiffin food with classmates. Give me ideas like packing one extra snack to share, talking about sharing at dinner, and praising kind moments. Tell me how to respect [his/her] feelings while teaching generosity." },
  { id: "parenting-338", title: "Teach my child to say excuse me", category: "parenting", text: "Teach my [4-year-old] to say excuse me instead of pushing past people. Give me 5 role-play games for home, the lift and the market, plus a simple rhyme to remember the words. Tell me how to praise [him/her] when [he/she] uses it." },
  { id: "parenting-339", title: "Help my child behave on a train", category: "parenting", text: "We are taking a 4-hour train journey with my [6-year-old]. Give me a plan with what to pack, how to explain train manners, quiet games for the journey, and what to do if [he/she] gets restless. Include food and safety tips." },
  { id: "parenting-340", title: "Teach my child to respect personal space", category: "parenting", text: "My [5-year-old] hugs strangers and climbs on guests. Teach [him/her] about personal space with a simple arm's length rule, a hula hoop game, and words to ask before hugging. Tell me how to explain it without making [him/her] feel bad." },
  { id: "parenting-341", title: "Help my child stop hitting others", category: "parenting", text: "My [6-year-old] hits other children when angry. Give me a calm plan: what to do in the moment, words to teach instead of hitting, and a 3-week practice plan with role play. Tell me when to speak to the teacher and what to ask." },
  { id: "parenting-342", title: "Teach my child to finish what they start", category: "parenting", text: "My [7-year-old] starts puzzles and drawings but never finishes them. Give me 8 strategies like breaking tasks into small steps, a finish line chart, and choosing the right size of task. Tell me how to praise finishing, not just starting." },
  { id: "parenting-343", title: "Help my child handle a scolding", category: "parenting", text: "My [8-year-old] cries and shuts down when a teacher scolds [him/her]. Give me words to comfort [him/her] after school, questions to understand what happened, and how to talk to the teacher if the scolding was unfair. Keep the advice gentle." },
  { id: "parenting-344", title: "Teach my child to keep a secret safe", category: "parenting", text: "Teach my [7-year-old] the difference between a fun surprise, like a birthday gift, and a secret that should be told to a parent. Give me simple examples, words to use, and a rule about telling a trusted adult. Keep the explanation age-appropriate." },
  { id: "parenting-345", title: "Help my child apologise to a sibling", category: "parenting", text: "My [6-year-old] broke [his/her] younger sibling's toy and will not apologise. Guide me through a calm talk, helping [him/her] fix or replace the toy, and simple sorry words to practise. Tell me how to avoid forcing an apology." },
  { id: "parenting-346", title: "Calm my child during a tantrum", category: "parenting", text: "My [4-year-old] has loud tantrums in shops and at home. Give me a step-by-step plan for the moment it starts: what to say, what to do, and what to avoid. Include how to stay calm myself and what to do after the tantrum ends." },
  { id: "parenting-347", title: "Help my child name big feelings", category: "parenting", text: "My [5-year-old] cannot explain feelings and just cries or shouts. Give me a feelings chart with faces, simple words for happy, sad, angry and scared, and 5 daily games to practise naming feelings. Tell me how to use the chart at home." },
  { id: "parenting-348", title: "Prevent tantrums before they start", category: "parenting", text: "My [4-year-old] has tantrums every evening before dinner. Help me spot the triggers like hunger, tiredness and too many choices. Give me a prevention plan with snacks, rest, warnings before transitions, and a calm evening routine." },
  { id: "parenting-349", title: "Handle a tantrum in public places", category: "parenting", text: "My [5-year-old] had a big tantrum in a supermarket yesterday. Give me a calm plan for public tantrums: what to do first, what to say to onlookers, and when to leave the shop. Tell me how to prepare before the next outing." },
  { id: "parenting-350", title: "Teach my child to breathe when angry", category: "parenting", text: "Teach my [6-year-old] simple breathing tricks for anger, like smelling a flower and blowing a candle. Give me 5 fun breathing games to practise when [he/she] is calm, so [he/she] can use them when upset. Keep each game under 3 minutes." },
  { id: "parenting-351", title: "Help my child cope with jealousy", category: "parenting", text: "My [7-year-old] feels jealous when a friend gets praise or a new toy. Give me words to talk about jealousy, a plan to build [his/her] own strengths, and simple daily praise habits. Tell me what not to say when [he/she] compares [himself/herself] to others." },
  { id: "parenting-352", title: "Create a calm corner at home", category: "parenting", text: "Create a calm corner for my [5-year-old] to cool down when upset. Tell me where to set it up, what to put there like cushions, books and a stress ball, and how to introduce it. Give me rules so it feels safe, not like a punishment." },
  { id: "parenting-353", title: "Help my child handle fear of strangers", category: "parenting", text: "My [4-year-old] is scared of strangers and new people. Give me a gentle plan with small steps, like waving from a distance, meeting one new person at a time, and praising brave tries. Tell me what to avoid so the fear does not grow." },
  { id: "parenting-354", title: "Talk to my child about sadness", category: "parenting", text: "My [7-year-old] has been sad since [his/her] best friend moved away. Give me simple words to talk about sadness, activities to cheer [him/her] up, and ways to stay in touch with the friend. Tell me when sadness needs a doctor's advice." },
  { id: "parenting-355", title: "Help my child after a nightmare", category: "parenting", text: "My [5-year-old] wakes up crying from nightmares twice a week. Give me a calm night-time plan: what to say, how to check the room together, and a dream catcher craft. Tell me what to avoid before bed, like scary shows or stories." },
  { id: "parenting-356", title: "Teach my child to use words not fists", category: "parenting", text: "My [6-year-old] pushes and hits when frustrated. Give me 8 feeling words to teach, a feelings poster for the wall, and role-play games for saying I am angry instead of hitting. Include a 3-week practice plan and praise ideas." },
  { id: "parenting-357", title: "Help my child cope with moving house", category: "parenting", text: "We are moving to a new house and my [7-year-old] is upset about leaving friends and school. Give me a plan with a goodbye visit, a memory book, packing together, and ways to explore the new area. Tell me how to talk about the move honestly." },
  { id: "parenting-358", title: "Handle sibling fights calmly", category: "parenting", text: "My children aged [5 and 8] fight every day over small things. Give me a calm plan for stepping in, listening to both sides, and helping them solve it themselves. Include a family rule chart and a weekly sibling fun activity." },
  { id: "parenting-359", title: "Help my child handle a pet dying", category: "parenting", text: "Our pet fish died and my [6-year-old] is very sad. Give me simple honest words to explain death to a young child, a small goodbye ritual, and activities to remember the pet. Tell me what to avoid saying and when to seek extra support." },
  { id: "parenting-360", title: "Teach my child to bounce back", category: "parenting", text: "My [8-year-old] gives up after one mistake and says I cannot do it. Give me a 4-week plan to build resilience with small challenges, praising effort, and stories of famous people who failed first. Tell me how to respond when [he/she] fails." },
  { id: "parenting-361", title: "Help my child with test anxiety", category: "parenting", text: "My [7-year-old] feels sick before every school test and fears failing. Give me a gentle plan with short revision sessions, breathing before the test, and words to say the night before. Tell me how to talk to the teacher about it." },
  { id: "parenting-362", title: "Calm my child before a doctor visit", category: "parenting", text: "My [5-year-old] is scared of doctor visits and injections. Give me a plan with a toy doctor kit at home, a simple explanation of what will happen, and a small reward after. Tell me what to say and what not to promise." },
  { id: "parenting-363", title: "Help my child express anger safely", category: "parenting", text: "My [6-year-old] throws things when angry. Give me safe ways to let anger out, like squeezing a pillow, drawing the anger, and running outside. Include a 2-week plan and words to use after [he/she] calms down." },
  { id: "parenting-364", title: "Teach my child to ask for space", category: "parenting", text: "Teach my [7-year-old] to say I need some space when upset instead of shouting or running away. Give me simple phrases, a quiet spot at home, and a family rule about respecting space. Include a practice game for the whole family." },
  { id: "parenting-365", title: "Help my child feel brave at school", category: "parenting", text: "My [5-year-old] says school is scary and wants to stay home. Give me a 2-week bravery plan with a brave chart, small steps like greeting one friend, and morning pep talks. Tell me how to work with the teacher on this." },
  { id: "parenting-366", title: "Handle my childs meltdown after school", category: "parenting", text: "My [6-year-old] melts down every day after school with crying and shouting. Explain why this happens after holding it together all day, and give me a calm after-school routine with a snack, rest and free play before homework." },
  { id: "parenting-367", title: "Teach my child to handle teasing", category: "parenting", text: "My [8-year-old] gets teased about [his/her] glasses at school. Give me confident replies [he/she] can use, ways to stay calm, and how to tell an adult. Tell me how to rebuild confidence and when to speak to the teacher." },
  { id: "parenting-368", title: "Help my child sleep after a scare", category: "parenting", text: "My [4-year-old] saw a scary scene on TV and now fears bedtime. Give me a gentle plan with a room check together, a comfort toy, a happy story, and rules about what [he/she] watches. Tell me how long this fear usually lasts." },
  { id: "parenting-369", title: "Teach my child to wait for a turn", category: "parenting", text: "My [5-year-old] cannot wait for a turn on the swing or in games. Give me 8 waiting games with timers, songs and counting, plus a simple rule for the park. Tell me how to praise waiting and handle tears when the wait feels long." },
  { id: "parenting-370", title: "Help my child cope with parents arguing", category: "parenting", text: "My [7-year-old] gets scared when parents argue at home. Give me simple words to reassure [him/her], a plan to keep arguments away from children, and a calm routine after a row. Tell me how to answer [his/her] questions honestly and gently." },
  { id: "parenting-371", title: "Make a feelings diary for my child", category: "parenting", text: "Help my [8-year-old] keep a simple feelings diary with one drawing and one line each day. Give me a 2-week starter plan with daily prompts about school, friends and mood. Tell me how to read it together without making it feel like homework." },
  { id: "parenting-372", title: "Help my child handle a new teacher", category: "parenting", text: "My [6-year-old] misses [his/her] old teacher and dislikes the new one. Give me ways to help [him/her] adjust: talking about the change, finding one good thing about the new teacher, and a small greeting ritual each morning. Tell me when to speak to the school." },
  { id: "parenting-373", title: "Teach my child to solve small problems", category: "parenting", text: "My [7-year-old] comes to me for every small problem, like a lost pencil. Give me a 3-step problem-solving method to teach: name the problem, think of two ideas, try one. Include 5 practice problems and tips to praise independent thinking." },
  { id: "parenting-374", title: "Help my child feel proud of effort", category: "parenting", text: "My [6-year-old] only cares about winning and marks. Give me 10 ways to praise effort instead of results, like praising practice, trying again and helping others. Tell me how to talk about mistakes as part of learning." },
  { id: "parenting-375", title: "Calm my child on a long journey", category: "parenting", text: "We have a 6-hour road trip with my [5-year-old] next week. Give me a calm plan with snack breaks, quiet games, songs and a small surprise bag. Tell me how to handle restlessness and car sickness with simple tips." },
  { id: "parenting-376", title: "Plan indoor games for rainy days", category: "parenting", text: "Plan 10 indoor games for my [6-year-old] on rainy days using things at home, like pillow forts, treasure hunts and paper boats. Each game should need little setup and keep [him/her] busy for at least 20 minutes. Include one quiet game." },
  { id: "parenting-377", title: "Make playdough fun at home", category: "parenting", text: "Give me 10 playdough play ideas for my [4-year-old], like making food, animals and letters. Tell me how to make safe playdough at home with flour and salt, how to store it, and how long each play session should last." },
  { id: "parenting-378", title: "Build a fort with my child", category: "parenting", text: "Help me build a blanket fort with my [5-year-old] using chairs, bedsheets and pillows. Give me step-by-step building tips, safety checks, and 5 games to play inside the fort, like storytelling, shadow play and a pretend shop." },
  { id: "parenting-379", title: "Teach my child simple board games", category: "parenting", text: "Recommend 8 simple board games and card games for my [6-year-old] that teach counting, colours and taking turns. For each game, tell me how long it takes, how many players it needs, and what skill it builds. Keep the budget under ₹1,000." },
  { id: "parenting-380", title: "Plan outdoor play in a small space", category: "parenting", text: "We live in a flat with a small balcony and my [7-year-old] needs more outdoor play. Give me 12 play ideas for small spaces, like hopscotch, balloon games and water play. Include safety tips and ideas for the nearest park." },
  { id: "parenting-381", title: "Make a treasure hunt for my child", category: "parenting", text: "Plan a treasure hunt at home for my [6-year-old] with 10 picture clues leading to a small prize. Give me the clues, hiding spots, and a simple map to draw together. Keep the whole game under 30 minutes and use things from home." },
  { id: "parenting-382", title: "Teach my child to play with blocks", category: "parenting", text: "Give me 10 building block challenges for my [5-year-old], like building a bridge, a tower and a house. Tell me how to play together, ask questions that build thinking, and how to handle it when the tower falls down." },
  { id: "parenting-383", title: "Start a craft box for my child", category: "parenting", text: "Start a craft box for my [7-year-old] with paper, colours, glue, scissors and recycled boxes. Give me 10 easy craft projects for weekends, each under 30 minutes. Tell me how to store the box and keep the mess under control." },
  { id: "parenting-384", title: "Play pretend shop with my child", category: "parenting", text: "Set up a pretend shop at home with my [6-year-old] using empty packets, coins and a small table. Give me a step-by-step setup, roles for shopkeeper and customer, and how this teaches counting and polite talking. Keep the setup under ₹200." },
  { id: "parenting-385", title: "Teach my child to ride a bicycle", category: "parenting", text: "Teach my [6-year-old] to ride a bicycle with training wheels first, then without them. Give me a safe practice plan for two weeks, safety gear to buy, and tips to handle falls and fear. Tell me the best place to practise in [your area]." },
  { id: "parenting-386", title: "Make puppets with my child", category: "parenting", text: "Help me make simple puppets with my [5-year-old] using socks, paper bags and old buttons. Give me step-by-step instructions for 3 puppets and a short puppet show script we can perform for the family. Keep the craft under 30 minutes." },
  { id: "parenting-387", title: "Plan a nature scavenger hunt", category: "parenting", text: "Plan a nature scavenger hunt in a park for my [7-year-old] with 12 things to find, like a smooth stone, a yellow flower and a bird. Give me a printable-style list, safety rules, and a small prize idea. Keep the hunt under one hour." },
  { id: "parenting-388", title: "Teach my child to play hide and seek", category: "parenting", text: "Teach my [4-year-old] to play hide and seek safely at home. Give me simple rules, safe hiding spots, and how to count slowly to 10. Include a fun twist like hiding a toy instead of a person. Tell me how to keep the game calm indoors." },
  { id: "parenting-389", title: "Make a simple obstacle course", category: "parenting", text: "Make a simple obstacle course at home for my [6-year-old] using cushions, chairs and a skipping rope. Give me 8 stations, safety tips, and a timer game to make it exciting. Tell me how to change the course each week to keep it fresh." },
  { id: "parenting-390", title: "Play memory games with my child", category: "parenting", text: "Give me 10 memory games for my [7-year-old] using cards, trays of objects and songs. Each game should take under 15 minutes and build focus and recall. Tell me how to make the games harder as [he/she] improves." },
  { id: "parenting-391", title: "Teach my child to draw animals", category: "parenting", text: "Teach my [5-year-old] to draw simple animals like a cat, elephant and fish using circles and lines. Give me step-by-step instructions for 5 animals, plus colouring tips. Tell me how to display the drawings at home." },
  { id: "parenting-392", title: "Make music with kitchen utensils", category: "parenting", text: "Turn kitchen utensils into a music band with my [4-year-old]. Give me 8 ideas using spoons, steel plates and empty boxes as drums. Include a simple rhythm game and a family performance plan. Keep the noise fun and under 20 minutes." },
  { id: "parenting-393", title: "Plan a picnic with my child", category: "parenting", text: "Plan a simple picnic in a nearby park with my [6-year-old]. Give me a food list for 3 people under ₹500, games to play, and a packing checklist with a mat, water and wipes. Tell me how to let [him/her] help with the planning." },
  { id: "parenting-394", title: "Teach my child to skip and hop", category: "parenting", text: "Teach my [5-year-old] to skip with a rope and hop on one foot. Give me a 2-week practice plan with short daily sessions, safety tips, and fun counting games while skipping. Tell me how to celebrate progress without pushing too hard." },
  { id: "parenting-395", title: "Make a cardboard house together", category: "parenting", text: "Help me build a cardboard house with my [7-year-old] using old boxes, tape and colours. Give me step-by-step building instructions, decoration ideas, and 5 pretend play games for the house. Keep the project to one weekend afternoon." },
  { id: "parenting-396", title: "Play water games safely at home", category: "parenting", text: "Give me 8 safe water play ideas for my [5-year-old] on a hot day, like pouring, floating toys and sponge games. Include safety rules, what to wear, and how to clean up afterwards. Keep the play in a small tub or balcony." },
  { id: "parenting-397", title: "Teach my child to play cricket", category: "parenting", text: "Teach my [7-year-old] the basics of cricket with a plastic bat and a soft ball. Cover batting stance, bowling underarm and catching. Give me a 2-week practice plan with 20-minute sessions and safety tips for playing at home." },
  { id: "parenting-398", title: "Make a family talent show", category: "parenting", text: "Plan a fun family talent show at home where my [6-year-old] can sing, dance or tell a story. Give me a 1-hour plan with rehearsal tips, a simple stage setup, and how to make every child feel like a star. Keep it relaxed and joyful." },
  { id: "parenting-399", title: "Teach my child to grow a plant", category: "parenting", text: "Help my [5-year-old] grow a methi or tomato plant in a small pot. Give me step-by-step instructions for sowing seeds, watering daily, and watching it grow. Include a growth chart to fill in and what to do when the plant wilts." },
  { id: "parenting-400", title: "Play I spy on a car journey", category: "parenting", text: "Give me 10 I spy and car games for my [6-year-old] on a long car journey, like spotting colours, counting trucks and singing songs. Each game should need no equipment and keep [him/her] busy for at least 15 minutes. Include a quiet game for rest time." },
  { id: "parenting-401", title: "Make rangoli with my young child", category: "parenting", text: "Teach my [7-year-old] to make a simple rangoli with colours, flowers and stencils for Diwali. Give me step-by-step instructions for 3 easy designs, safety tips for colour powder, and how to clean up afterwards. Keep the activity under one hour." },
  { id: "parenting-402", title: "Teach my child to play ludo", category: "parenting", text: "Teach my [6-year-old] to play ludo with simple rules explained in easy words. Cover rolling the dice, moving tokens, and what happens on a six. Give me tips to keep the game friendly and handle losing gracefully." },
  { id: "parenting-403", title: "Plan a playdate at home", category: "parenting", text: "Plan a 2-hour playdate at home for my [5-year-old] and two friends. Give me a schedule with free play, a craft activity, snacks and a story. Include Jain vegetarian snack ideas and tips to handle small fights between children." },
  { id: "parenting-404", title: "Make a sensory bin for my child", category: "parenting", text: "Make a sensory bin for my [4-year-old] using rice, spoons, cups and small toys. Give me step-by-step setup instructions, 5 play ideas, and clean-up tips. Tell me how to keep the play safe and how long each session should last." },
  { id: "parenting-405", title: "Teach my child to dance at home", category: "parenting", text: "Teach my [6-year-old] simple dance steps at home with music [he/she] loves. Give me a 4-week plan with warm-ups, 3 easy steps per week, and a small performance for the family. Keep each session to 15 minutes and fun." },
  { id: "parenting-406", title: "Help my child choose a hobby", category: "parenting", text: "My [8-year-old] wants to try a hobby but cannot decide between drawing, music and cricket. Give me a simple trial plan with one month per hobby, questions to ask after each trial, and how to choose without pressure. Include low-cost options in [your city]." },
  { id: "parenting-407", title: "Prepare my child for sports day", category: "parenting", text: "My [7-year-old] has sports day at school next week and feels nervous. Give me a preparation plan with practice races at home, what to pack, and words to say before the event. Tell me how to celebrate effort whether [he/she] wins or not." },
  { id: "parenting-408", title: "Help my child with a class project", category: "parenting", text: "My [8-year-old] has a school project on [festivals of India] due next week. Give me a simple plan to help [him/her] research, make a chart and practise speaking about it. Tell me how to let [him/her] do most of the work." },
  { id: "parenting-409", title: "Teach my child to save pocket money", category: "parenting", text: "Teach my [8-year-old] to save pocket money of ₹50 a week using a piggy bank and a simple savings chart. Give me a 4-week plan with a small goal, like saving ₹200 for a book. Tell me how to talk about spending versus saving." },
  { id: "parenting-410", title: "Help my child deal with a strict teacher", category: "parenting", text: "My [7-year-old] is scared of a strict teacher at school. Give me words to comfort [him/her], questions to understand what happens in class, and how to speak to the teacher politely. Tell me when to raise it with the school principal." },
  { id: "parenting-411", title: "Teach my child about good touch", category: "parenting", text: "Teach my [6-year-old] about good touch and bad touch in simple, age-appropriate words. Give me a calm script to use at home, the swimsuit rule, and words to teach like my body belongs to me. Tell me how to answer questions honestly." },
  { id: "parenting-412", title: "Help my child handle a school change", category: "parenting", text: "We are changing my [7-year-old]'s school next term. Give me a plan to prepare [him/her]: visiting the new school, talking about what stays the same, and making a first friend. Tell me how to handle worries in the first month." },
  { id: "parenting-413", title: "Teach my child to use a dictionary", category: "parenting", text: "Teach my [8-year-old] to use a simple children's dictionary to find word meanings. Give me a 2-week plan with 5 word hunts, a game to find words fast, and tips to use new words in sentences. Keep each session under 15 minutes." },
  { id: "parenting-414", title: "Help my child learn a second language", category: "parenting", text: "Help my [6-year-old] learn basic [Hindi/Tamil] words alongside English. Give me a 4-week plan with 5 words a week, songs, labels around the house and simple conversations. Tell me how to keep it playful and not like extra homework." },
  { id: "parenting-415", title: "Plan a study corner for my child", category: "parenting", text: "Set up a small study corner for my [8-year-old] in our flat with a table, light and storage. Give me a checklist under ₹2,000, ideas to keep it tidy, and a rule for homework time. Tell me how to involve [him/her] in setting it up." },
  { id: "parenting-416", title: "Teach my child to revise for exams", category: "parenting", text: "My [8-year-old] has unit tests next month. Give me a simple revision plan with short sessions, flashcards, past paper practice and breaks. Tell me how to make revision fun and how to keep the last day before the test relaxed." },
  { id: "parenting-417", title: "Help my child speak up in class", category: "parenting", text: "My [7-year-old] knows the answers but never raises [his/her] hand in class. Give me a 3-week confidence plan with practising answers at home, a secret signal with the teacher, and small daily speaking challenges. Tell me how to praise each brave try." },
  { id: "parenting-418", title: "Teach my child about online safety", category: "parenting", text: "My [8-year-old] watches videos on a shared tablet. Teach [him/her] simple online safety rules: never share name, photo or school, and tell a parent about anything strange. Give me a family tablet agreement and 5 conversation starters." },
  { id: "parenting-419", title: "Help my child make a school presentation", category: "parenting", text: "My [8-year-old] must give a 2-minute talk in class about [my favourite animal]. Give me a simple structure with a start, 3 facts and an ending. Include practice tips, a drawing idea, and how to handle nerves on the day." },
  { id: "parenting-420", title: "Teach my child to manage time", category: "parenting", text: "My [7-year-old] takes forever to get ready and finish homework. Give me a simple time plan with a visual clock, a timer for tasks, and a morning and evening checklist. Tell me how to praise on-time days and handle slow mornings calmly." },
  { id: "parenting-421", title: "Help my child enjoy maths at home", category: "parenting", text: "My [6-year-old] says maths is boring. Give me 10 fun maths games using cooking, shopping and board games that practise counting, adding and shapes. Each game should take under 15 minutes and feel like play, not study." },
  { id: "parenting-422", title: "Teach my child to write neatly in exams", category: "parenting", text: "My [8-year-old] writes too fast in tests and the teacher cannot read it. Give me a 2-week practice plan with slow writing drills, spacing tips and a checklist for test day. Tell me how to practise without making writing feel like a punishment." },
  { id: "parenting-423", title: "Help my child handle peer pressure", category: "parenting", text: "My [8-year-old] copies friends to fit in, like teasing others or wasting food. Give me simple words to teach [him/her] to say no, role-play practice, and ways to build confidence in [his/her] own choices. Tell me how to talk about it weekly." },
  { id: "parenting-424", title: "Plan a reading challenge for holidays", category: "parenting", text: "Plan a 30-day reading challenge for my [7-year-old] during the summer holidays. Give me a book list of 10 books, a star chart, and small rewards for finishing each book. Tell me how to keep the challenge fun and not a chore." },
  { id: "parenting-425", title: "Help my child celebrate a small win", category: "parenting", text: "My [6-year-old] just learned to read a full page alone. Give me 10 simple ways to celebrate small wins at home, like a special dinner, a certificate, and a family cheer. Tell me how celebrating effort builds confidence for bigger goals." },
  { id: "parenting-426", title: "Daily study timetable for a 10-year-old", category: "parenting", text: "Make a simple daily study timetable for my 10-year-old in [class 5]. Include school, homework, play, reading and sleep times. Keep study blocks short with breaks, and add one fun learning activity each evening after dinner." },
  { id: "parenting-427", title: "Help my child focus on homework", category: "parenting", text: "My [11-year-old] gets distracted during homework and takes two hours for one hour of work. Suggest practical ways to help [him/her] focus, set up a quiet study corner, and use short timed sessions with small breaks." },
  { id: "parenting-428", title: "Make maths revision fun at home", category: "parenting", text: "My [12-year-old] finds maths boring and forgets formulas quickly. Give me five fun ways to revise maths at home using games, daily life examples like shopping and cooking, and short daily practice of [15 minutes]." },
  { id: "parenting-429", title: "Prepare a weekly homework planner", category: "parenting", text: "Create a weekly homework planner for a [13-year-old] with subjects [maths, science, English and Hindi]. Show how to spread work across the week, track pending tasks, and keep Sunday free for revision and family time." },
  { id: "parenting-430", title: "Help my child remember spellings easily", category: "parenting", text: "My [9-year-old] keeps misspelling common English words in dictation. Suggest simple daily spelling games, memory tricks and a weekly word list of [20 words] that we can practise together for ten minutes." },
  { id: "parenting-431", title: "Study plan before unit tests", category: "parenting", text: "My child has unit tests in [two weeks] for [four subjects]. Make a simple day-by-day revision plan that covers all chapters, includes sample questions, short notes and one mock test before each exam day." },
  { id: "parenting-432", title: "Encourage my child to read daily", category: "parenting", text: "My [10-year-old] reads only when forced to. Suggest ways to build a daily reading habit with books about [cricket and adventure], a fixed reading time, and simple questions I can ask after each chapter." },
  { id: "parenting-433", title: "Handle homework battles without shouting", category: "parenting", text: "Homework time ends in arguments every evening with my [11-year-old]. Give me calm phrases to use, a fixed homework routine, and ways to motivate [him/her] without shouting, threats or taking away playtime completely." },
  { id: "parenting-434", title: "Teach my child to take neat notes", category: "parenting", text: "Teach my [12-year-old] how to take neat class notes for [science]. Explain headings, bullet points, diagrams and colour coding in simple steps, and show a sample page layout that is easy to revise before tests." },
  { id: "parenting-435", title: "Revision plan for a slow learner", category: "parenting", text: "My [13-year-old] learns slowly and feels low when classmates finish first. Make a gentle revision plan for [maths] with small daily goals, lots of examples, regular praise and no comparison with other children." },
  { id: "parenting-436", title: "Set up a study corner at home", category: "parenting", text: "Help me set up a small study corner for my [9-year-old] in our [one-bedroom flat]. Suggest a table, light, storage for books, a pin board and ways to keep toys and phone away during study time." },
  { id: "parenting-437", title: "Help my child learn multiplication tables", category: "parenting", text: "My [10-year-old] struggles with tables from 6 to 9. Give me fun rhymes, clapping games and daily five-minute drills to learn them in [three weeks], plus a simple chart to track progress with stars." },
  { id: "parenting-438", title: "Plan science project work together", category: "parenting", text: "My [11-year-old] has a science project on [water conservation] due in [two weeks]. Help us plan the steps, choose simple materials from home, divide the work fairly, and prepare a short talk for the class." },
  { id: "parenting-439", title: "Help my child write better essays", category: "parenting", text: "My [12-year-old] writes short, jumbled essays in English. Teach [him/her] a simple plan: opening line, three main points with examples, and a closing line. Give a practice topic about [my favourite festival] with a sample outline." },
  { id: "parenting-440", title: "Morning routine before school", category: "parenting", text: "Make a calm morning routine for my [13-year-old] who leaves for school at [7.30 am]. Include wake-up time, breakfast, bag packing, revision of one topic and leaving on time without rushing or forgetting things." },
  { id: "parenting-441", title: "Help my child prepare for oral exams", category: "parenting", text: "My [9-year-old] feels nervous speaking in front of the class during oral tests. Give me simple practice ideas at home, confidence-building tips and five likely questions on [English poems] to practise together." },
  { id: "parenting-442", title: "Balance tuition and self-study time", category: "parenting", text: "My [14-year-old] goes to tuition for [maths and science] and has little time for self-study. Help me balance tuition, homework and revision in a weekly plan that still leaves one hour of free time daily." },
  { id: "parenting-443", title: "Teach my child to manage exam stress", category: "parenting", text: "My [12-year-old] worries a lot before exams and cannot sleep well. Suggest simple calming routines, breathing exercises, a realistic revision plan and reassuring words I can use during exam week." },
  { id: "parenting-444", title: "Make history revision interesting", category: "parenting", text: "My [11-year-old] finds history dates hard to remember. Suggest story-based revision, timelines, maps and quiz games for the chapter on [the freedom movement], with a simple way to test [him/her] every weekend." },
  { id: "parenting-445", title: "Help my child improve handwriting", category: "parenting", text: "My [10-year-old] writes fast but untidily, and teachers complain. Give a four-week handwriting practice plan with correct pencil grip, ruled notebooks, slow copying practice and daily [15 minutes] of guided writing." },
  { id: "parenting-446", title: "Set study goals for the term", category: "parenting", text: "Help my [13-year-old] set three realistic study goals for this school term in [maths, English and science]. Make each goal clear and measurable, with weekly steps and a simple reward when a goal is reached." },
  { id: "parenting-447", title: "Help my child understand fractions simply", category: "parenting", text: "Explain fractions to my [9-year-old] using roti, pizza and chocolate bars. Give simple examples, three practice sums and a fun kitchen activity where [he/she] cuts and shares food into equal parts." },
  { id: "parenting-448", title: "Plan holiday homework without stress", category: "parenting", text: "My [12-year-old] has a long list of holiday homework for [Diwali break]. Help us split it into small daily tasks, mix fun activities with written work, and finish everything two days before school reopens." },
  { id: "parenting-449", title: "Help my child learn a new language", category: "parenting", text: "My [11-year-old] wants to learn [Tamil] at home. Make a beginner plan with daily words, simple sentences, songs and stories, plus a weekly speaking practice where we talk only in [Tamil] for half an hour." },
  { id: "parenting-450", title: "Check homework without doing it", category: "parenting", text: "I want to check my [10-year-old] homework without doing it for [him/her]. Tell me what to look for, which questions to ask, and how to guide [him/her] to find mistakes and correct them alone." },
  { id: "parenting-451", title: "Help my child stay organised for school", category: "parenting", text: "My [14-year-old] often forgets books and misses deadlines. Help [him/her] build a simple system with a school diary, a bag-packing checklist the night before, and a weekly planner for homework and tests." },
  { id: "parenting-452", title: "Make geography fun with maps", category: "parenting", text: "My [12-year-old] finds geography dull. Suggest fun ways to learn Indian states, rivers and capitals using maps, quizzes, travel stories and a wall map, with a weekly challenge for the whole family." },
  { id: "parenting-453", title: "Help my child revise with flashcards", category: "parenting", text: "Show my [13-year-old] how to make flashcards for [science] revision. Explain what to write on each side, how many cards to revise daily, and a simple game to test them with a parent or friend." },
  { id: "parenting-454", title: "Talk about poor marks kindly", category: "parenting", text: "My [11-year-old] scored low in [maths] and feels ashamed. Give me gentle words to start the conversation, questions to understand what went wrong, and a plan to improve without scolding or comparing with siblings." },
  { id: "parenting-455", title: "Help my child learn computer basics", category: "parenting", text: "My [9-year-old] needs basic computer skills for school projects. Make a simple learning plan covering typing, making slides, saving files and safe searching, with [30 minutes] of guided practice twice a week." },
  { id: "parenting-456", title: "Study routine for exam holidays", category: "parenting", text: "Make a study routine for my [14-year-old] during the [10-day] exam holidays. Include morning revision, afternoon practice papers, evening rest, sleep timings and one outdoor break each day to stay fresh." },
  { id: "parenting-457", title: "Help my child ask questions in class", category: "parenting", text: "My [10-year-old] is too shy to ask doubts in class. Suggest ways to build confidence, practise asking questions at home, and simple phrases [he/she] can use with teachers without feeling embarrassed." },
  { id: "parenting-458", title: "Teach time management to a teenager", category: "parenting", text: "Teach my [13-year-old] basic time management using a simple weekly chart. Show how to plan study, play, chores and rest, and how to finish homework before [7 pm] most days without feeling rushed." },
  { id: "parenting-459", title: "Help my child with Hindi grammar", category: "parenting", text: "My [12-year-old] finds Hindi grammar confusing, especially [sandhi and samas]. Explain the topic in simple words with everyday examples, give five practice questions, and suggest a weekly revision routine." },
  { id: "parenting-460", title: "Create a reading list for holidays", category: "parenting", text: "Create a holiday reading list for my [11-year-old] who likes [mystery stories]. Suggest six age-suitable books available in India, with a short line on each book and a simple reading target for [four weeks]." },
  { id: "parenting-461", title: "Help my child prepare a speech", category: "parenting", text: "My [9-year-old] must give a two-minute speech on [save water] at school. Help us write a simple speech with a strong opening, three points and a closing line, plus tips for clear and confident delivery." },
  { id: "parenting-462", title: "Support my child after changing schools", category: "parenting", text: "My [12-year-old] just changed schools and finds the new syllabus hard. Suggest ways to catch up in [maths and science], settle into the new class, and build a study routine for the first month." },
  { id: "parenting-463", title: "Help my child learn tables through songs", category: "parenting", text: "My [10-year-old] learns best through songs and rhymes. Write simple sing-along lines for the tables of [7 and 8], and suggest a daily routine to sing, recite and test them in five minutes." },
  { id: "parenting-464", title: "Plan a study group with friends", category: "parenting", text: "My [13-year-old] wants to study with two friends for the [science] test. Give rules for a useful study group, a two-hour plan with revision, quiz and break, and tips to avoid chatting and wasting time." },
  { id: "parenting-465", title: "Help my child improve English speaking", category: "parenting", text: "My [14-year-old] writes good English but hesitates while speaking. Give daily speaking practice ideas, simple topics to talk about at home, and ways to build confidence without correcting every small mistake." },
  { id: "parenting-466", title: "Make a revision timetable for finals", category: "parenting", text: "Make a [three-week] revision timetable for my [12-year-old] before final exams in [five subjects]. Cover each subject twice, add practice papers, keep evenings light, and leave the last day for quick revision only." },
  { id: "parenting-467", title: "Help my child with long division", category: "parenting", text: "Explain long division step by step to my [10-year-old] with the example [432 divided by 4]. Use simple language, show each step clearly, and give three similar sums for practice with answers." },
  { id: "parenting-468", title: "Encourage my child to join debates", category: "parenting", text: "My [13-year-old] is interested in debates but fears speaking on stage. Suggest how to choose a topic like [mobile phones in school], prepare three points, practise at home and handle nervousness before the event." },
  { id: "parenting-469", title: "Help my child finish projects on time", category: "parenting", text: "My [11-year-old] always leaves school projects to the last night. Help us break a [social science] project into daily steps over [one week], with a checklist, materials list and a finish date two days early." },
  { id: "parenting-470", title: "Teach my child to proofread work", category: "parenting", text: "Teach my [12-year-old] to proofread [his/her] own homework before submitting it. Give a simple checklist for spelling, grammar, numbers and neatness, and a habit of reading the work aloud once." },
  { id: "parenting-471", title: "Help my child learn through documentaries", category: "parenting", text: "Suggest five age-suitable documentaries for my [14-year-old] on [space and nature]. Give a short line on each one, what [he/she] can learn, and two discussion questions we can talk about after watching together." },
  { id: "parenting-472", title: "Set rules for study during festivals", category: "parenting", text: "During [Diwali], my [10-year-old] stops studying completely for a week. Help me make a light festive study plan with one hour of revision daily, so [he/she] enjoys the festival and stays in touch with studies." },
  { id: "parenting-473", title: "Help my child remember science diagrams", category: "parenting", text: "My [13-year-old] forgets labels in science diagrams for [the human heart]. Give a simple drawing method, memory tricks for each part, and a weekly practice routine to draw and label it from memory." },
  { id: "parenting-474", title: "Plan weekend study and play balance", category: "parenting", text: "Plan a weekend routine for my [11-year-old] that balances study, outdoor play, family time and rest. Include two study blocks, one hobby hour, and a Sunday evening plan to get ready for school on Monday." },
  { id: "parenting-475", title: "Help my child cope with tough subjects", category: "parenting", text: "My [12-year-old] says [science] is too tough and wants to give up. Suggest ways to break the subject into small parts, find easy starting chapters, use videos and examples, and rebuild confidence step by step." },
  { id: "parenting-476", title: "Set healthy screen time limits", category: "parenting", text: "My [11-year-old] spends four hours daily on a phone and tablet. Help me set fair screen time limits, explain the reasons calmly, and suggest offline activities like reading, cycling and board games to fill the time." },
  { id: "parenting-477", title: "Make a family phone-free dinner rule", category: "parenting", text: "We want phone-free dinners for our family with a [12-year-old]. Suggest a simple rule everyone follows, conversation starters for the table, and ways to handle protests without turning dinner into a daily argument." },
  { id: "parenting-478", title: "Help my child cut down gaming time", category: "parenting", text: "My [13-year-old] plays online games for hours and neglects homework. Give a step-by-step plan to reduce gaming to [one hour] a day, with clear timings, agreed rewards, and other fun activities to replace gaming." },
  { id: "parenting-479", title: "Choose safe videos for a 10-year-old", category: "parenting", text: "My [10-year-old] watches videos alone on YouTube. Suggest how to choose safe, age-suitable channels about [science and crafts], set up parental controls, and check viewing history together every week." },
  { id: "parenting-480", title: "Talk about online safety with kids", category: "parenting", text: "Explain online safety to my [12-year-old] in simple words. Cover not sharing photos, address or school name, not talking to strangers, and what to do if a message or video feels scary or wrong." },
  { id: "parenting-481", title: "Screen-free morning routine for kids", category: "parenting", text: "My [9-year-old] asks for cartoons the moment [he/she] wakes up. Make a screen-free morning routine with breakfast, getting ready, a short story and a quick revision, so the day starts calmly without a screen." },
  { id: "parenting-482", title: "Help my child stop watching late night", category: "parenting", text: "My [14-year-old] watches videos till midnight and wakes up tired for school. Suggest a phone charging spot outside the bedroom, a fixed switch-off time of [9.30 pm], and a calming bedtime routine instead." },
  { id: "parenting-483", title: "Plan a screen-free Sunday at home", category: "parenting", text: "Plan a screen-free Sunday for our family with a [11-year-old]. Include cooking together, a board game, a walk in the park, reading time and a simple craft, so the day feels fun without phones or TV." },
  { id: "parenting-484", title: "Teach my child about social media risks", category: "parenting", text: "My [13-year-old] wants an Instagram account like friends have. Explain the risks in simple, honest words, suggest a safe age to start, and give rules for photos, followers and chatting if we allow it later." },
  { id: "parenting-485", title: "Balance online classes and play", category: "parenting", text: "My [10-year-old] has online classes and then wants more screen time for games. Help me plan the day so screen learning, outdoor play, homework and rest are balanced, with clear start and stop times." },
  { id: "parenting-486", title: "Help my child use tablets for learning", category: "parenting", text: "My [12-year-old] has a tablet for school work but uses it only for games. Suggest useful learning apps, a daily learning slot of [45 minutes], and a simple weekly check to see what [he/she] actually learnt." },
  { id: "parenting-487", title: "Set rules for TV watching time", category: "parenting", text: "Help me set fair TV rules for my [9-year-old]: how long daily, which shows are allowed, no TV during meals or homework, and a simple weekly chart where [he/she] can tick off screen-free days." },
  { id: "parenting-488", title: "Handle tantrums over phone limits", category: "parenting", text: "My [11-year-old] throws tantrums when I take the phone away. Give me calm responses to use, a warning system before switch-off time, and ways to stay firm without shouting or giving in every time." },
  { id: "parenting-489", title: "Teach my child about fake news online", category: "parenting", text: "Teach my [13-year-old] to spot fake news and false videos online. Give simple checks like looking at the source, checking the date, and asking a parent or teacher before believing or forwarding any shocking message." },
  { id: "parenting-490", title: "Make a digital detox weekend plan", category: "parenting", text: "Plan a two-day digital detox weekend for our family with a [14-year-old]. Suggest outdoor games, cooking, a family picnic, storytelling and stargazing, plus tips to handle boredom without reaching for a phone." },
  { id: "parenting-491", title: "Help my child avoid phone addiction", category: "parenting", text: "My [12-year-old] checks the phone every few minutes and gets upset without it. Suggest gradual steps to reduce checking, phone-free zones at home, hobby ideas, and signs that mean we should talk to a counsellor." },
  { id: "parenting-492", title: "Choose educational apps for kids", category: "parenting", text: "Suggest five good educational apps for my [10-year-old] for [maths and English]. Give a short line on each app, what it teaches, and how much time daily is enough, so learning stays fun and not tiring." },
  { id: "parenting-493", title: "Talk about cyberbullying with my child", category: "parenting", text: "My [13-year-old] was teased in a class WhatsApp group. Help me talk to [him/her] kindly, explain what cyberbullying is, save proof, block the bullies, and inform the teacher without making [him/her] feel blamed." },
  { id: "parenting-494", title: "Set up parental controls on devices", category: "parenting", text: "Explain in simple steps how to set up parental controls on my [11-year-old] Android phone. Cover app limits, safe search, download approvals and bedtime lock, so I can protect [him/her] without checking the phone daily." },
  { id: "parenting-495", title: "Help my child enjoy reading over reels", category: "parenting", text: "My [14-year-old] prefers short videos to books. Suggest ways to make reading attractive again with graphic novels, sports biographies and a family reading hour, plus a small reward for finishing each book." },
  { id: "parenting-496", title: "Screen time rules for holidays", category: "parenting", text: "During school holidays my [9-year-old] watches TV all day. Make a holiday screen plan with fixed viewing hours, outdoor play, craft time and family outings, so holidays stay active and screens stay limited." },
  { id: "parenting-497", title: "Teach my child to verify online information", category: "parenting", text: "Teach my [12-year-old] to check facts before trusting a video or post. Give a simple three-step check: who made it, when was it posted, and does a trusted site say the same, with an example about [health tips]." },
  { id: "parenting-498", title: "Help my child manage WhatsApp groups", category: "parenting", text: "My [13-year-old] is in many class WhatsApp groups and gets distracted all evening. Suggest rules for muting groups, checking messages twice a day, and replying politely without getting pulled into chats during study time." },
  { id: "parenting-499", title: "Plan outdoor play instead of screens", category: "parenting", text: "Suggest ten outdoor play ideas for my [10-year-old] in [Chennai] that can replace evening screen time. Include cycling, cricket, badminton and park games, with tips to invite friends and keep it a daily habit." },
  { id: "parenting-500", title: "Talk about screen time with teenagers", category: "parenting", text: "My [14-year-old] says all friends have unlimited screen time and I am strict. Give me calm, respectful words to explain our family rules, listen to [his/her] view, and agree on a fair limit together." },
  { id: "parenting-501", title: "Help my child sleep better without screens", category: "parenting", text: "My [11-year-old] sleeps late after watching videos in bed. Suggest a screen-free hour before sleep, a fixed bedtime of [9.30 pm], a story or light reading, and a morning reward for sleeping on time." },
  { id: "parenting-502", title: "Choose age-suitable games for kids", category: "parenting", text: "Suggest five age-suitable games for my [9-year-old] that build thinking and creativity. Give a short line on each game, why it suits this age, and how long daily is enough without affecting homework or sleep." },
  { id: "parenting-503", title: "Teach my child about online strangers", category: "parenting", text: "Explain to my [10-year-old] why chatting with strangers in games is unsafe. Use simple examples, clear rules about never sharing personal details, and what to do if a stranger asks for photos or a meeting." },
  { id: "parenting-504", title: "Make a screen time reward chart", category: "parenting", text: "Make a weekly screen time reward chart for my [12-year-old]. Show how finishing homework, reading and chores earns screen minutes, with a simple table, star stickers and a small weekend reward for good balance." },
  { id: "parenting-505", title: "Help my child handle online peer pressure", category: "parenting", text: "My [13-year-old] feels pressured to post photos and follow trends online. Give me words to reassure [him/her], explain that likes do not define worth, and suggest offline hobbies that build real confidence." },
  { id: "parenting-506", title: "Set a phone curfew for the family", category: "parenting", text: "Help our family set a phone curfew where all phones charge in the living room after [9 pm]. Suggest how to introduce the rule, handle resistance from my [14-year-old], and keep it going for a month." },
  { id: "parenting-507", title: "Help my child learn coding safely", category: "parenting", text: "My [12-year-old] wants to learn coding on the computer. Suggest beginner-friendly, safe platforms for kids in India, a weekly practice plan of [three sessions], and how to keep screen time balanced with play." },
  { id: "parenting-508", title: "Talk about passwords with my child", category: "parenting", text: "Teach my [11-year-old] why passwords must stay private, even from friends. Explain strong passwords, never sharing OTPs, and what to do if someone asks for a password or tries to open [his/her] account." },
  { id: "parenting-509", title: "Reduce screen time during exam season", category: "parenting", text: "During exams my [14-year-old] still spends hours on the phone. Make a simple exam-season screen plan with study blocks, one short entertainment break, and phone-free mornings so revision gets full attention." },
  { id: "parenting-510", title: "Help my child enjoy music without screens", category: "parenting", text: "Suggest screen-free music activities for my [10-year-old] who loves songs. Include singing together, learning a simple instrument, making a family playlist and a weekly music hour without any phone or TV." },
  { id: "parenting-511", title: "Explain advertisements to my child", category: "parenting", text: "Explain to my [9-year-old] that online ads try to sell things and are not always true. Give simple examples from toy and snack ads, and questions [he/she] can ask before wanting something seen in an ad." },
  { id: "parenting-512", title: "Help my child report bad content online", category: "parenting", text: "Teach my [13-year-old] how to report bad or scary content on [YouTube and Instagram]. Explain the report button, blocking, telling a parent, and why reporting helps keep others safe too." },
  { id: "parenting-513", title: "Plan a tech-free family outing", category: "parenting", text: "Plan a tech-free family outing for a Sunday with my [12-year-old] in [Bengaluru]. Suggest a park or lake visit, games to play, food to carry, and ways to enjoy the day without taking photos every few minutes." },
  { id: "parenting-514", title: "Help my child use search safely", category: "parenting", text: "Teach my [10-year-old] to search safely for school homework online. Show how to type clear questions, pick trusted sites, avoid clicking ads, and ask a parent when a result looks strange or scary." },
  { id: "parenting-515", title: "Set limits for online shopping by kids", category: "parenting", text: "My [14-year-old] keeps adding things to online shopping carts. Explain to [him/her] how online shopping works, why we check before buying, and set a rule that no order is placed without a parent." },
  { id: "parenting-516", title: "Help my child balance gaming and studies", category: "parenting", text: "My [11-year-old] loves gaming and hates homework. Help me make a daily deal: homework and reading first, then [45 minutes] of gaming as a reward, with a clear chart and a calm way to handle broken promises." },
  { id: "parenting-517", title: "Teach my child about digital footprints", category: "parenting", text: "Explain digital footprints to my [13-year-old] in simple words. Show how photos and comments stay online for years, and give five rules for posting wisely so future teachers or employers see a good picture." },
  { id: "parenting-518", title: "Help my child cope without a phone", category: "parenting", text: "My [12-year-old] feels left out because [he/she] has no personal phone yet. Suggest comforting words, fun alternatives like a shared family tablet, and a plan for when [he/she] can get a first phone." },
  { id: "parenting-519", title: "Make bedtime screen-free for kids", category: "parenting", text: "Make a screen-free bedtime routine for my [9-year-old]. Include a warm bath, a story, talking about the day and lights out by [9 pm], so [he/she] sleeps well and wakes fresh for school." },
  { id: "parenting-520", title: "Help my child choose good YouTube channels", category: "parenting", text: "Help my [14-year-old] choose good YouTube channels about [cricket and science]. List what makes a channel trustworthy, how to avoid clickbait, and a simple weekly limit for watching videos." },
  { id: "parenting-521", title: "Talk about screen time at parent meetings", category: "parenting", text: "Give me five polite questions to ask my [11-year-old] teacher about screen use in school, homework apps and online safety, so I can support the school rules at home without sounding worried or critical." },
  { id: "parenting-522", title: "Help my child avoid comparing online", category: "parenting", text: "My [13-year-old] compares [his/her] life with friends posting happy photos online. Give me gentle words to explain that posts show only the best moments, and ways to build confidence offline." },
  { id: "parenting-523", title: "Set rules for using phones at relatives", category: "parenting", text: "When we visit relatives, my [10-year-old] sits with a phone all the time. Suggest polite family rules for screen use during visits, fun games with cousins, and ways to enjoy talking together instead." },
  { id: "parenting-524", title: "Help my child learn from online videos", category: "parenting", text: "My [12-year-old] watches science videos but remembers little. Teach [him/her] a simple method: watch once, write three points, draw one diagram, and explain it to a parent the same evening." },
  { id: "parenting-525", title: "Create a family media agreement", category: "parenting", text: "Help our family write a simple media agreement for my [14-year-old]. Include screen hours, no phones at meals, safe apps only, and a monthly family review where we can change the rules together fairly." },
  { id: "parenting-526", title: "Help my shy child make friends", category: "parenting", text: "My [10-year-old] is shy and eats lunch alone at school. Suggest gentle ways to help [him/her] start conversations, join a game, invite a classmate home, and build one good friendship step by step." },
  { id: "parenting-527", title: "Handle a fight between best friends", category: "parenting", text: "My [12-year-old] had a big fight with [his/her] best friend over a game. Give me words to comfort [him/her], help [him/her] see the other side, and suggest a simple apology that can repair the friendship." },
  { id: "parenting-528", title: "Teach my child to choose good friends", category: "parenting", text: "Teach my [13-year-old] what makes a good friend: kindness, honesty, respect and support. Give examples of healthy and unhealthy friendships, and questions [he/she] can ask when choosing whom to trust." },
  { id: "parenting-529", title: "Help my child cope with being left out", category: "parenting", text: "My [11-year-old] was not invited to a birthday party and feels left out. Give me comforting words, ways to explain that one party does not define friendship, and ideas to cheer [him/her] up that weekend." },
  { id: "parenting-530", title: "Plan a playdate for a 9-year-old", category: "parenting", text: "Plan a two-hour playdate at home for my [9-year-old] and two classmates. Suggest games, a simple snack, a craft activity and ground rules, so everyone plays happily and no child feels left out." },
  { id: "parenting-531", title: "Talk about peer pressure with kids", category: "parenting", text: "My [14-year-old] feels pressured to copy friends who skip homework. Help me explain peer pressure in simple words, give [him/her] polite ways to say no, and build confidence to make independent choices." },
  { id: "parenting-532", title: "Help my child handle a bully", category: "parenting", text: "My [10-year-old] is being teased by an older boy on the school bus. Tell me how to listen calmly, teach [him/her] to stay safe, speak firmly, and when to inform the teacher or school bus staff." },
  { id: "parenting-533", title: "Teach my child to share with friends", category: "parenting", text: "My [9-year-old] refuses to share toys with friends who visit. Suggest gentle ways to teach sharing, taking turns and handling jealousy, with a simple rule we can practise before every playdate." },
  { id: "parenting-534", title: "Help my child apologise to a teacher", category: "parenting", text: "My [10-year-old] spoke rudely to a teacher and feels ashamed now. Help me guide [him/her] to apologise in person, in simple honest words. Suggest what to say first, how to listen to the teacher, and one kind act to make up for it." },
  { id: "parenting-535", title: "Support my child after losing a friend", category: "parenting", text: "My [13-year-old] best friend moved to another city and [he/she] feels lonely. Suggest ways to stay in touch, make new friends at school, and handle sadness with regular chats and shared activities." },
  { id: "parenting-536", title: "Help my child join a sports team", category: "parenting", text: "My [11-year-old] wants to join the school cricket team but fears rejection. Suggest how to practise basic skills, talk to the coach, handle trials calmly and enjoy the game even if [he/she] is not selected." },
  { id: "parenting-537", title: "Teach my child to handle jealousy", category: "parenting", text: "My [10-year-old] feels jealous when a friend gets better marks. Help me explain jealousy kindly, celebrate [his/her] own strengths, and turn comparison into learning by asking the friend for study tips." },
  { id: "parenting-538", title: "Help my child invite friends home", category: "parenting", text: "My [14-year-old] is nervous about inviting friends home for the first time. Suggest how to plan a simple evening with snacks, music and games, and how to make guests feel welcome in our home." },
  { id: "parenting-539", title: "Talk about friendship and honesty", category: "parenting", text: "Teach my [12-year-old] why honesty matters in friendship. Give everyday examples, such as admitting a mistake and keeping a promise, and simple words to use when a friend asks [him/her] to lie." },
  { id: "parenting-540", title: "Help my child deal with gossip", category: "parenting", text: "My [13-year-old] heard classmates gossiping about [her/him]. Help me explain gossip, teach [him/her] not to spread rumours, and give calm responses to use when someone shares gossip about others." },
  { id: "parenting-541", title: "Encourage my child to help friends", category: "parenting", text: "Suggest ways to encourage my [11-year-old] to help classmates who struggle with studies. Include sharing notes, explaining sums patiently, and forming a small study pair, without doing the friend homework for them." },
  { id: "parenting-542", title: "Help my child make friends after moving", category: "parenting", text: "We moved to [Pune] and my [9-year-old] knows nobody at the new school. Suggest ways to make friends in the first month, join clubs, talk to neighbours and stay positive during the settling-in period." },
  { id: "parenting-543", title: "Teach my child to respect differences", category: "parenting", text: "Teach my [12-year-old] to respect friends from different backgrounds, foods and festivals. Give simple examples, respectful questions to ask, and words to use when someone teases another child for being different." },
  { id: "parenting-544", title: "Help my child handle group projects", category: "parenting", text: "My [14-year-old] dislikes group projects because one member does no work. Suggest ways to divide tasks fairly, speak up politely, keep a record of who did what, and inform the teacher if needed." },
  { id: "parenting-545", title: "Plan a birthday party with friends", category: "parenting", text: "Plan a simple birthday party at home for my [10-year-old] with [eight friends]. Suggest games, food, decorations and a budget of [₹2,000], so the party is fun without spending too much money." },
  { id: "parenting-546", title: "Help my child say no to friends", category: "parenting", text: "My [13-year-old] cannot say no when friends ask [him/her] to bunk a class. Teach [him/her] firm but polite ways to refuse, suggest excuses that are honest, and practise the words together at home." },
  { id: "parenting-547", title: "Talk about online friends safely", category: "parenting", text: "My [12-year-old] made friends in an online game. Explain the difference between game friends and real friends, safety rules for chatting, and why meeting an online friend alone is never safe." },
  { id: "parenting-548", title: "Help my child support a sad friend", category: "parenting", text: "My [11-year-old] friend is sad because [his/her] pet died. Teach my child kind words to say, how to listen without fixing everything, and small gestures like a card or a walk together." },
  { id: "parenting-549", title: "Teach my child to take turns in games", category: "parenting", text: "My [9-year-old] gets upset when [he/she] loses a game with friends. Suggest ways to teach taking turns, handling losing gracefully, and enjoying the game, with a family game night to practise every week." },
  { id: "parenting-550", title: "Help my child handle teasing kindly", category: "parenting", text: "My [10-year-old] is teased about [his/her] glasses at school. Give me comforting words, ways to build confidence, funny but kind replies to use, and steps to take if the teasing keeps happening." },
  { id: "parenting-551", title: "Encourage my child to join school clubs", category: "parenting", text: "My [13-year-old] spends breaks alone and avoids clubs. Suggest clubs that suit [his/her] interest in [art and music], how to try one for a month, and ways to make friends through shared activities." },
  { id: "parenting-552", title: "Help my child keep a friendship diary", category: "parenting", text: "Suggest a simple friendship diary for my [12-year-old] to write about kind moments, fights and lessons learnt. Give prompts for weekly entries and ways to reflect without sharing private thoughts with others." },
  { id: "parenting-553", title: "Talk about secrets between friends", category: "parenting", text: "Teach my [11-year-old] the difference between a fun secret and a secret that must be told, like bullying or danger. Give clear examples and reassure [him/her] that telling a trusted adult is not betraying a friend." },
  { id: "parenting-554", title: "Help my child handle a jealous friend", category: "parenting", text: "My [14-year-old] has a friend who gets jealous of [his/her] marks. Suggest calm ways to handle the jealousy, keep the friendship kind, and set boundaries if the friend starts taunting or spreading rumours." },
  { id: "parenting-555", title: "Teach my child to listen to friends", category: "parenting", text: "Teach my [10-year-old] to be a good listener when friends talk. Give simple habits like looking at the speaker, not interrupting, asking one question, and remembering small details to ask about later." },
  { id: "parenting-556", title: "Help my child celebrate friends success", category: "parenting", text: "My [12-year-old] feels upset when friends win prizes. Help me teach [him/her] to celebrate others, say kind words like congratulations, and feel proud of [his/her] own efforts at the same time." },
  { id: "parenting-557", title: "Plan a group study picnic", category: "parenting", text: "Plan a group study picnic for my [13-year-old] and three friends before exams. Suggest a park, a revision plan, snacks to carry, quiz games and a finish time, so study feels light and fun." },
  { id: "parenting-558", title: "Help my child handle changing friendships", category: "parenting", text: "My [14-year-old] says old friends have changed and drifted away. Help me explain that friendships change as we grow, how to stay kind, and how to find new friends with shared interests." },
  { id: "parenting-559", title: "Teach my child about loyalty in friendship", category: "parenting", text: "Teach my [11-year-old] what loyalty means in friendship with simple examples: standing up for a friend, keeping promises and not joining others in teasing. Give a short story to discuss together." },
  { id: "parenting-560", title: "Help my child invite a new student", category: "parenting", text: "A new student joined my [9-year-old] class and sits alone. Suggest kind ways my child can invite [him/her] to play, share lunch, introduce [him/her] to friends and help [him/her] feel welcome at school." },
  { id: "parenting-561", title: "Talk about competition among friends", category: "parenting", text: "My [12-year-old] competes with friends over marks and feels stressed. Help me explain healthy competition, focusing on personal progress, and celebrating effort instead of only comparing ranks and scores." },
  { id: "parenting-562", title: "Help my child handle a broken promise", category: "parenting", text: "My [13-year-old] is upset because a friend broke a promise to share notes. Give me words to comfort [him/her], help [him/her] talk to the friend calmly, and decide when to forgive and move on." },
  { id: "parenting-563", title: "Encourage my child to play team games", category: "parenting", text: "My [10-year-old] prefers playing alone and avoids team games. Suggest fun team games like kho-kho and relay races, ways to join in slowly, and how to enjoy playing a part in a team." },
  { id: "parenting-564", title: "Help my child deal with exclusion", category: "parenting", text: "My [14-year-old] was excluded from a group chat by classmates. Give me gentle words to support [him/her], steps to understand what happened, and ways to build friendships outside that group." },
  { id: "parenting-565", title: "Teach my child to resolve conflicts peacefully", category: "parenting", text: "Teach my [11-year-old] four steps to solve fights with friends: calm down, listen, say how you feel, and find a fair solution. Give a role-play example about sharing a cricket bat." },
  { id: "parenting-566", title: "Help my child make friends in tuition", category: "parenting", text: "My [12-year-old] goes to tuition but talks to nobody there. Suggest simple ways to greet classmates, ask about homework, share notes and slowly build friendly chats before and after class." },
  { id: "parenting-567", title: "Talk about kindness towards classmates", category: "parenting", text: "Teach my [9-year-old] small acts of kindness at school, like sharing a pencil, helping a classmate who fell, and including everyone in games. Give a weekly kindness challenge we can track together." },
  { id: "parenting-568", title: "Help my child handle a friend moving away", category: "parenting", text: "My [13-year-old] best friend is shifting to [Delhi] next month. Suggest ways to enjoy the last weeks together, plan video calls and letters, and cope with missing [him/her] after the move." },
  { id: "parenting-569", title: "Teach my child to stand up for others", category: "parenting", text: "Teach my [14-year-old] to stand up safely when a classmate is bullied. Explain when to speak up, when to get a teacher, and how to support the child afterwards without putting [himself/herself] in danger." },
  { id: "parenting-570", title: "Help my child balance friends and studies", category: "parenting", text: "My [12-year-old] spends all evening chatting with friends and skips homework. Help me set a balance with study first, a fixed chat time of [30 minutes], and a weekend plan for longer time with friends." },
  { id: "parenting-571", title: "Plan a friendship day celebration", category: "parenting", text: "Plan a small Friendship Day celebration at home for my [10-year-old] and friends. Suggest handmade bands, a card-making activity, snacks and a group photo, with a total budget of [₹500]." },
  { id: "parenting-572", title: "Help my child handle rumours at school", category: "parenting", text: "A rumour about my [11-year-old] is spreading in class. Help me talk to [him/her] calmly, find out the truth, speak to the teacher if needed, and teach [him/her] not to spread rumours about others." },
  { id: "parenting-573", title: "Teach my child to respect friends boundaries", category: "parenting", text: "Teach my [13-year-old] to respect friends personal space, belongings and feelings. Give examples like asking before borrowing, not reading messages, and accepting no gracefully without getting angry." },
  { id: "parenting-574", title: "Help my child join a hobby class", category: "parenting", text: "My [9-year-old] wants to join a [drawing] class to make friends. Help me choose a good class nearby, prepare [him/her] for the first day, and encourage [him/her] to talk to other children there." },
  { id: "parenting-575", title: "Talk about true friendship with teens", category: "parenting", text: "Help me talk to my [14-year-old] about what true friendship looks like. Cover trust, respect, support in tough times and honesty, with real-life examples [he/she] can relate to from school life." },
  { id: "parenting-576", title: "Start pocket money for a 10-year-old", category: "parenting", text: "My [10-year-old] wants pocket money like friends get. Help me decide a fair weekly amount in rupees, explain what it should cover, and set simple rules for spending, saving and keeping a small record." },
  { id: "parenting-577", title: "Teach my child to save money", category: "parenting", text: "Teach my [11-year-old] to save money using three jars for spending, saving and sharing. Suggest a weekly amount of [₹100], a savings goal like a [cricket bat], and a simple chart to track progress." },
  { id: "parenting-578", title: "Help my child plan a small budget", category: "parenting", text: "Help my [13-year-old] plan a monthly budget with [₹400] pocket money. Show how to split it between snacks, stationery, saving and fun, and how to check at month end if the plan worked." },
  { id: "parenting-579", title: "Talk about needs and wants with kids", category: "parenting", text: "Teach my [9-year-old] the difference between needs and wants using everyday examples like food, shoes and toys. Give a fun sorting game and questions to ask before buying something new." },
  { id: "parenting-580", title: "Help my child earn extra money", category: "parenting", text: "My [12-year-old] wants to earn extra money at home. Suggest age-suitable tasks like helping with gardening, sorting books and washing the car, with fair payment and a clear rule that studies come first." },
  { id: "parenting-581", title: "Teach my child about bank accounts", category: "parenting", text: "Explain a savings bank account to my [14-year-old] in simple words. Cover deposits, withdrawals, interest and ATM safety, and suggest opening a minor account together with a small first deposit of [₹500]." },
  { id: "parenting-582", title: "Help my child avoid impulse buying", category: "parenting", text: "My [11-year-old] spends all pocket money on the first day. Teach [him/her] a wait-one-day rule before buying, a small wish list, and how to compare prices before spending money on toys or snacks." },
  { id: "parenting-583", title: "Set pocket money rules for the family", category: "parenting", text: "Help our family set pocket money rules for my [10-year-old]: a fixed weekly amount, no extra money for lost items, and a monthly review. Suggest how to explain the rules kindly and stick to them." },
  { id: "parenting-584", title: "Teach my child to give to others", category: "parenting", text: "Teach my [12-year-old] the joy of giving by setting aside a small part of pocket money for charity. Suggest simple ways to donate, like buying notebooks for a needy child or giving to a temple fund." },
  { id: "parenting-585", title: "Help my child save for a bicycle", category: "parenting", text: "My [13-year-old] wants a bicycle costing [₹5,000]. Make a savings plan with weekly pocket money, birthday money and small earnings, showing how many months it will take and how to track savings." },
  { id: "parenting-586", title: "Explain prices and value to kids", category: "parenting", text: "Explain to my [9-year-old] why similar toys have different prices. Use examples from a local shop, talk about quality, brand and usefulness, and help [him/her] choose wisely within a budget of [₹300]." },
  { id: "parenting-587", title: "Help my child track weekly spending", category: "parenting", text: "Make a simple weekly spending tracker for my [14-year-old] with columns for date, item, price and reason. Show how to fill it daily, review it on Sunday, and spot wasteful spending habits together." },
  { id: "parenting-588", title: "Talk about money honestly with kids", category: "parenting", text: "Help me talk honestly to my [11-year-old] about family money without worrying [him/her]. Explain that we plan spending carefully, why we say no sometimes, and how saving helps us reach family goals." },
  { id: "parenting-589", title: "Teach my child to compare shop prices", category: "parenting", text: "Teach my [12-year-old] to compare prices before buying stationery. Give a simple activity: check the same item in [three shops], note the prices, and choose the best value without compromising on quality." },
  { id: "parenting-590", title: "Help my child plan birthday spending", category: "parenting", text: "My [10-year-old] received [₹1,000] as birthday money. Help [him/her] plan how to use it: save half, spend some on a [book set], and keep a little for treats, with a simple written plan." },
  { id: "parenting-591", title: "Teach my child about saving for festivals", category: "parenting", text: "Teach my [13-year-old] to save a small amount weekly for [Diwali] shopping. Make a ten-week plan, set a goal of [₹1,000], and show how to resist spending the festival fund on daily treats." },
  { id: "parenting-592", title: "Help my child understand pocket money limits", category: "parenting", text: "My [9-year-old] thinks pocket money should never run out. Explain in simple words that money is limited, help [him/her] plan weekly spending, and teach [him/her] to wait for the next week when it finishes." },
  { id: "parenting-593", title: "Make a money jar system for kids", category: "parenting", text: "Make a money jar system for my [11-year-old] with jars labelled spend, save and share. Explain how much goes into each jar weekly, when to open the save jar, and how to celebrate reaching a goal." },
  { id: "parenting-594", title: "Teach my child to bargain politely", category: "parenting", text: "Teach my [14-year-old] to bargain politely in a local market. Give simple phrases, tips on checking quality first, knowing a fair price, and walking away kindly if the seller does not agree." },
  { id: "parenting-595", title: "Help my child choose a first wallet", category: "parenting", text: "My [12-year-old] wants a first wallet for pocket money. Suggest what to look for, how to keep money and cards safe, and simple habits like checking the wallet before leaving home and after shopping." },
  { id: "parenting-596", title: "Talk about borrowing money with kids", category: "parenting", text: "My [13-year-old] borrows money from friends for snacks. Help me explain why borrowing often is a bad habit, how to plan spending better, and how to repay quickly if [he/she] ever borrows." },
  { id: "parenting-597", title: "Help my child save for school trips", category: "parenting", text: "My [10-year-old] school trip costs [₹800] next month. Make a four-week savings plan from pocket money, with a weekly target, a progress chart, and a backup plan if [he/she] falls short by a little." },
  { id: "parenting-598", title: "Teach my child about digital payments", category: "parenting", text: "Explain digital payments to my [14-year-old] in simple words. Cover UPI, QR codes and why we never share PINs or OTPs, with clear rules that [he/she] must ask a parent before any online payment." },
  { id: "parenting-599", title: "Help my child handle lost money", category: "parenting", text: "My [9-year-old] lost [₹50] pocket money and is upset. Give me comforting words, teach [him/her] to keep money safely, retrace steps calmly, and explain that losing money sometimes happens to everyone." },
  { id: "parenting-600", title: "Make a family savings challenge", category: "parenting", text: "Make a fun family savings challenge for a month with my [11-year-old]. Set a shared goal like a [family picnic], daily saving tips, a chart on the fridge and a small celebration when we reach the target." },
  { id: "parenting-601", title: "Teach my child to read price tags", category: "parenting", text: "Teach my [12-year-old] to read price tags, MRP and expiry dates while shopping. Give a simple supermarket activity where [he/she] compares two similar products and picks the better value for our family." },
  { id: "parenting-602", title: "Help my child plan a small party budget", category: "parenting", text: "Help my [13-year-old] plan a small party for friends with a budget of [₹1,500]. List snacks, decorations and games, show how to divide the money, and keep a small amount aside for unexpected costs." },
  { id: "parenting-603", title: "Talk about advertising and spending", category: "parenting", text: "Explain to my [10-year-old] how ads make us want things we do not need. Give examples from TV and YouTube, and teach [him/her] three questions to ask before asking to buy something seen in an ad." },
  { id: "parenting-604", title: "Help my child save coins daily", category: "parenting", text: "Start a daily coin-saving habit for my [9-year-old] with a piggy bank. Suggest saving loose change every evening, counting it every Sunday, and setting a small reward after saving [₹200] in a month." },
  { id: "parenting-605", title: "Teach my child about interest simply", category: "parenting", text: "Explain interest to my [14-year-old] with a simple example: if you keep [₹1,000] in a bank for a year, the bank gives you extra money. Show how saving grows slowly and why patience pays." },
  { id: "parenting-606", title: "Help my child decide on expensive toys", category: "parenting", text: "My [11-year-old] wants an expensive toy costing [₹2,500]. Help [him/her] decide by comparing it with cheaper options, checking how often it will be used, and planning to save for it over [two months]." },
  { id: "parenting-607", title: "Set rules for lending money to friends", category: "parenting", text: "Help me set rules for my [12-year-old] about lending pocket money to friends. Explain when it is kind to help, when to say no, and why lending large amounts can spoil friendships." },
  { id: "parenting-608", title: "Teach my child to plan weekly snacks", category: "parenting", text: "Help my [10-year-old] plan weekly snacks within [₹150]. List healthy options like fruits, peanuts and homemade snacks, show how to divide the money across five school days, and avoid wasting it on one day." },
  { id: "parenting-609", title: "Help my child understand family budgets", category: "parenting", text: "Explain our family monthly budget to my [13-year-old] in simple terms. Show how money goes to food, rent, school fees and savings, and why planning together helps the whole family live comfortably." },
  { id: "parenting-610", title: "Make a pocket money diary for kids", category: "parenting", text: "Make a pocket money diary for my [14-year-old] to record money received, spent and saved. Give a simple format, a weekly review habit, and tips to learn from mistakes without feeling guilty about spending." },
  { id: "parenting-611", title: "Teach my child to save for books", category: "parenting", text: "My [9-year-old] loves storybooks and wants to buy more. Make a savings plan to buy one book a month, suggest using the library too, and show how to choose books wisely within a small budget." },
  { id: "parenting-612", title: "Help my child handle peer spending pressure", category: "parenting", text: "My [12-year-old] wants costly shoes because friends have them. Give me words to explain our budget kindly, help [him/her] feel confident without expensive things, and find a good affordable pair together." },
  { id: "parenting-613", title: "Talk about pocket money and chores", category: "parenting", text: "Should pocket money be linked to chores? Help me explain to my [11-year-old] that basic chores are family duties, while extra tasks can earn a little money, with a fair list for our home." },
  { id: "parenting-614", title: "Help my child plan a gift budget", category: "parenting", text: "Help my [13-year-old] plan a gift for a friend birthday with a budget of [₹300]. Suggest thoughtful gift ideas, how to compare prices, and how to wrap it nicely at home without extra cost." },
  { id: "parenting-615", title: "Teach my child about money and honesty", category: "parenting", text: "Teach my [10-year-old] why taking money without asking is wrong, even a small amount. Give gentle words to discuss it, explain honesty and trust, and suggest ways to ask for money when needed." },
  { id: "parenting-616", title: "Help my child save for a cricket kit", category: "parenting", text: "My [14-year-old] wants a cricket kit costing [₹3,000]. Make a savings plan with pocket money and festival gifts, show the monthly target, and suggest buying good quality items step by step." },
  { id: "parenting-617", title: "Make shopping lists with my child", category: "parenting", text: "Teach my [9-year-old] to make a shopping list before going to the market. Give a simple format with items, quantities and prices, and show how a list helps us avoid buying extra things." },
  { id: "parenting-618", title: "Help my child understand discounts", category: "parenting", text: "Explain discounts to my [12-year-old] with a simple example: a [₹500] shirt at 20 percent off costs [₹400]. Show how to check if a sale is really good value or just a marketing trick." },
  { id: "parenting-619", title: "Teach my child to keep money safe", category: "parenting", text: "Teach my [11-year-old] to keep pocket money safe at school and outside. Cover using a wallet, not showing money to strangers, keeping it in a front pocket, and telling a teacher if money goes missing." },
  { id: "parenting-620", title: "Help my child plan for a school fair", category: "parenting", text: "My [10-year-old] school fair is next week and [he/she] has [₹200] to spend. Help [him/her] plan which stalls to visit, how much to spend on games and food, and how to keep some money for later." },
  { id: "parenting-621", title: "Talk about saving for the future", category: "parenting", text: "Talk to my [13-year-old] about saving for the future in simple words. Explain goals like higher studies and a first bike, and how small weekly savings today can grow into something big later." },
  { id: "parenting-622", title: "Help my child earn through a hobby", category: "parenting", text: "My [14-year-old] is good at [drawing] and wants to earn a little money. Suggest safe, age-suitable ways like making cards for family, with clear rules that studies and safety always come first." },
  { id: "parenting-623", title: "Teach my child about coins and notes", category: "parenting", text: "Teach my [9-year-old] about Indian coins and notes through a fun game. Cover values from [₹1 to ₹500], counting change, and a simple shop game at home to practise paying and getting change." },
  { id: "parenting-624", title: "Help my child set a savings goal", category: "parenting", text: "Help my [12-year-old] set a clear savings goal for a [skateboard]. Make the goal specific, break it into weekly savings of [₹100], track it on a chart, and celebrate when the goal is reached." },
  { id: "parenting-625", title: "Review pocket money together monthly", category: "parenting", text: "Make a simple monthly pocket money review for my [11-year-old]. Include what was spent, what was saved, one money lesson learnt, and a plan for next month, so [he/she] learns budgeting step by step." },
  { id: "parenting-626", title: "Start a conversation with your teenager", category: "parenting", text: "Give me 10 gentle conversation starters I can use with my [age]-year-old teenager after school. They should feel natural, not like an interview, and help my child open up about their day, friends and feelings without pressure." },
  { id: "parenting-627", title: "When your teen answers in one word", category: "parenting", text: "My teenager only replies with one-word answers like fine or ok. Suggest 8 warm follow-up questions and simple listening habits I can use so they feel safe to share more, without me sounding like I am checking up on them." },
  { id: "parenting-628", title: "Listen without judging your teen", category: "parenting", text: "Teach me how to listen to my teenager without judging or interrupting. Give me simple phrases I can use when they tell me something difficult, and explain what to avoid saying so they keep trusting me." },
  { id: "parenting-629", title: "Talk about feelings with a teenager", category: "parenting", text: "Help me talk to my [age]-year-old about their feelings. Suggest easy words for anger, worry and sadness, a calm time of day to start, and three short activities we can do together that make sharing feelings easier." },
  { id: "parenting-630", title: "Handle a teenager who shuts down", category: "parenting", text: "My teenager goes quiet and walks away whenever I ask about school or friends. Give me a calm plan for the next two weeks, including what to say, when to wait, and how to reopen the talk without a fight." },
  { id: "parenting-631", title: "Apologise to your teenager sincerely", category: "parenting", text: "I shouted at my teenager and I want to apologise properly. Draft a short, honest apology I can say in person, with simple words that own my mistake, show I understand their feelings, and invite them to talk." },
  { id: "parenting-632", title: "Talk about puberty with your teen", category: "parenting", text: "Help me explain puberty changes to my [age]-year-old in simple, respectful words. Cover body changes, mood swings and hygiene, and give me answers to five awkward questions they might ask during the talk." },
  { id: "parenting-633", title: "Weekly check-in with your teenager", category: "parenting", text: "Plan a relaxed weekly check-in with my teenager that takes only 20 minutes. Include five gentle questions about school, friends, health and mood, plus a fun activity we can do together so it feels like bonding, not an inspection." },
  { id: "parenting-634", title: "When your teen disagrees with you", category: "parenting", text: "My teenager disagrees with almost every family rule now. Give me a calm way to hear their view, explain my reasons clearly, and reach a fair middle ground on [topic] without shouting or giving in completely." },
  { id: "parenting-635", title: "Talk about anger without shouting", category: "parenting", text: "Teach my teenager and me how to talk about anger calmly. Give us a simple three-step method to pause, name the feeling and solve the problem, with two practice examples from everyday family life in India." },
  { id: "parenting-636", title: "Ask about your teen's school day", category: "parenting", text: "Give me 12 better questions than how was school to ask my teenager each evening. They should invite real answers about lessons, teachers and friends, and work even on days when my child is tired or in a bad mood." },
  { id: "parenting-637", title: "Talk to a teen about body image", category: "parenting", text: "My teenager worries a lot about looks and weight. Help me talk about body image in a kind, honest way, with reassuring words, healthy habits to suggest, and signs that mean I should get extra help for them." },
  { id: "parenting-638", title: "Rebuild talking after a big argument", category: "parenting", text: "My teenager and I had a big argument and now we are barely speaking. Give me a gentle three-day plan to rebuild our talks, including the first thing to say, a small shared activity, and how to avoid restarting the fight." },
  { id: "parenting-639", title: "Help a shy teenager open up", category: "parenting", text: "My teenager is very shy and rarely talks about their life. Suggest seven low-pressure ways to encourage them to share, such as car rides, cooking together or evening walks, and explain how to respond so they feel safe." },
  { id: "parenting-640", title: "Talk about dreams and future plans", category: "parenting", text: "Help me talk with my teenager about their dreams for the future without pushing my own plans on them. Give me open questions about careers, studies and interests, and ways to support choices I did not expect." },
  { id: "parenting-641", title: "Settle sibling fights between teenagers", category: "parenting", text: "My two teenagers fight daily over small things like the bathroom, the TV remote and borrowed clothes. Give me a fair family plan with shared rules, calm ways to settle each clash, and a weekly check to keep the peace." },
  { id: "parenting-642", title: "Talk about money with your teenager", category: "parenting", text: "Teach me how to talk to my teenager about money in simple words. Cover pocket money, saving for something they want, and why we cannot buy everything, with a small monthly budget we can plan together." },
  { id: "parenting-643", title: "When your teen wants more freedom", category: "parenting", text: "My teenager keeps asking for more freedom, like going out alone and staying up late. Help me set fair limits step by step, explain my reasons kindly, and agree on small freedoms they can earn by showing responsibility." },
  { id: "parenting-644", title: "Talk about respect in the family", category: "parenting", text: "Help me talk with my teenager about respect at home, including how we speak to each other, privacy, and helping with chores. Give me a short family agreement we can write together and review every month." },
  { id: "parenting-645", title: "Encourage your teen without nagging", category: "parenting", text: "I want to encourage my teenager without sounding like I am nagging. Give me 10 short, warm phrases for effort, kindness and small wins, and explain when praise helps and when it is better to simply listen." },
  { id: "parenting-646", title: "Talk about a teen's bad mood", category: "parenting", text: "My teenager often comes home in a bad mood and snaps at everyone. Help me tell the difference between a normal bad day and a deeper problem, with calm responses for each and signs that mean I should seek help." },
  { id: "parenting-647", title: "Family dinner talks with teenagers", category: "parenting", text: "Plan five family dinner conversations that teenagers will actually enjoy, with fun topics, a light question each person answers, and no talk about marks or homework, so dinner becomes a time we all look forward to." },
  { id: "parenting-648", title: "Talk about chores with your teenager", category: "parenting", text: "Help me divide household chores fairly with my teenager without daily arguments. Suggest a simple weekly chart, age-wise tasks, and a calm way to handle it when chores are skipped, with a small reward for consistency." },
  { id: "parenting-649", title: "When your teen copies friends' habits", category: "parenting", text: "My teenager is copying habits from friends that worry me, like new slang, late nights and spending. Help me talk about it calmly, understand what attracts them, and guide them without banning every friend or sounding harsh." },
  { id: "parenting-650", title: "Talk about health and sleep habits", category: "parenting", text: "Help me talk to my teenager about healthy sleep, food and exercise without lecturing. Give me simple facts a teen will accept, a realistic daily routine we can build together, and ways to make healthy habits feel normal." },
  { id: "parenting-651", title: "Help your teen handle embarrassment", category: "parenting", text: "My teenager feels embarrassed easily, even over small things at school or family functions. Give me comforting words, simple coping steps they can use in the moment, and ways to build their confidence slowly over time." },
  { id: "parenting-652", title: "Talk about teachers and school problems", category: "parenting", text: "My teenager is unhappy with a teacher at school. Help me listen to their side first, decide when to speak to the teacher, and draft a polite message I can send to the school asking for a meeting." },
  { id: "parenting-653", title: "When your teen refuses to talk", category: "parenting", text: "My teenager refuses to talk about anything personal and says leave me alone. Give me a patient plan for the next month, including giving space, small everyday gestures, and how to know when silence needs professional support." },
  { id: "parenting-654", title: "Talk about gratitude with teenagers", category: "parenting", text: "Help me teach my teenager gratitude without preaching. Suggest five small daily habits, like naming one good thing at dinner, and explain how gratitude can help their mood, friendships and studies in simple words." },
  { id: "parenting-655", title: "Prepare your teen for a family function", category: "parenting", text: "We have a big family function and my teenager does not want to attend. Help me talk about it without forcing them, agree on a fair plan for how long we stay, and suggest ways to make the event less boring for them." },
  { id: "parenting-656", title: "Talk about mistakes without blame", category: "parenting", text: "My teenager made a mistake and is scared to tell me. Help me respond in a way that teaches responsibility without blame, with calm words, a plan to fix the mistake together, and a promise that honesty is safe." },
  { id: "parenting-657", title: "Help your teen manage exam stress", category: "parenting", text: "My teenager is very stressed about the coming board exams. Give me a calm home plan with a study timetable, regular breaks, good sleep, and reassuring words I can use every day to reduce their fear." },
  { id: "parenting-658", title: "Make a board exam revision plan", category: "parenting", text: "Help me make a realistic 30-day revision plan for my teenager's board exams in [subjects]. Include daily study hours, revision of old chapters, mock tests, breaks and rest days, keeping the total study time healthy and doable." },
  { id: "parenting-659", title: "Talk about exam results without pressure", category: "parenting", text: "My teenager is scared of disappointing us with exam results. Help me say the right words before and after results day, so they know our love does not depend on marks, and we can plan next steps together calmly." },
  { id: "parenting-660", title: "Stop comparing your teen with others", category: "parenting", text: "I often compare my teenager with cousins and neighbours, and I know it hurts them. Help me break this habit with kinder words to use instead, and a simple way to notice and praise my own child's progress." },
  { id: "parenting-661", title: "Help a teen who failed an exam", category: "parenting", text: "My teenager failed an important exam and feels ashamed. Give me comforting words for the first day, a calm plan to find out what went wrong, and steps for re-studying or reappearing without crushing their confidence." },
  { id: "parenting-662", title: "Calm a teen before an exam", category: "parenting", text: "My teenager panics the night before exams and cannot sleep. Give me a simple evening routine with light revision, a warm meal, a relaxing activity, and calming words that help them feel ready and safe." },
  { id: "parenting-663", title: "Plan study breaks that actually refresh", category: "parenting", text: "Help me plan short study breaks for my teenager during exam time. Suggest ten refreshing break ideas that take 10 to 15 minutes, like a walk, music or a snack, and explain which breaks to avoid before studying again." },
  { id: "parenting-664", title: "Talk about career choices after school", category: "parenting", text: "My teenager is confused about which stream to choose after class 10. Help me explore science, commerce and arts with them, listing simple questions about their interests and strengths, and how each stream can lead to a career." },
  { id: "parenting-665", title: "Handle exam-time fights at home", category: "parenting", text: "Exam time brings fights at home over study hours, phone use and sleep. Give our family a simple set of exam-time rules we can agree on together, with calm ways to settle each clash before it becomes a shouting match." },
  { id: "parenting-666", title: "Help your teen focus while studying", category: "parenting", text: "My teenager gets distracted easily while studying and keeps checking their phone. Give me a simple focus plan with a quiet study spot, 25-minute study blocks, and a phone-free routine that feels fair instead of like a punishment." },
  { id: "parenting-667", title: "Talk about fear of failing exams", category: "parenting", text: "My teenager is terrified of failing and says everyone will laugh at them. Help me talk about this fear gently, with reassuring words, real examples of people who recovered from failure, and a plan to face exams step by step." },
  { id: "parenting-668", title: "Set realistic exam goals together", category: "parenting", text: "Help me set realistic exam goals with my teenager instead of demanding top marks. Show me how to look at their past scores, pick three subjects to improve, and agree on small weekly targets we can celebrate together." },
  { id: "parenting-669", title: "Support a teen with exam anxiety", category: "parenting", text: "My teenager feels sick and nervous before every exam. Give me simple calming techniques they can use, like slow breathing and positive self-talk, plus a morning routine for exam day that keeps them calm and organised." },
  { id: "parenting-670", title: "Plan a healthy exam-time routine", category: "parenting", text: "Help me build a healthy daily routine for my teenager during exams, with fixed sleep hours, three proper meals, short exercise, study blocks and free time, so they stay fresh instead of studying late into the night." },
  { id: "parenting-671", title: "Talk about tuition and extra classes", category: "parenting", text: "My teenager is overloaded with school plus three tuitions. Help me decide which extra classes are truly needed, talk to my child about dropping one, and plan free time so they are not exhausted every single day." },
  { id: "parenting-672", title: "Help your teen revise without cramming", category: "parenting", text: "My teenager leaves everything for the last night and then panics. Teach us a simple spaced revision method with short daily reviews, flashcards and weekly tests, so learning stays steady and the last week feels calm." },
  { id: "parenting-673", title: "When your teen studies all night", category: "parenting", text: "My teenager stays up till 2 am studying before exams and is exhausted the next day. Help me explain why sleep helps memory, agree on a sensible lights-out time, and plan early morning revision that actually works better." },
  { id: "parenting-674", title: "Celebrate effort not just marks", category: "parenting", text: "I want to celebrate my teenager's effort, not only their marks. Give me ten simple ways to notice hard work, like a favourite meal or a family outing, and words of praise that build their confidence for the next exam." },
  { id: "parenting-675", title: "Talk about entrance exam pressure", category: "parenting", text: "My teenager feels huge pressure about entrance exams like [exam name]. Help me talk honestly about the exam, other good options if it does not work out, and a balanced preparation plan that protects their health and sleep." },
  { id: "parenting-676", title: "Help a teen who hates a subject", category: "parenting", text: "My teenager hates [subject] and refuses to study it. Help me find out why they dislike it, suggest fun ways to make it easier, and plan small daily steps so they can at least pass without daily tears." },
  { id: "parenting-677", title: "Prepare for parent-teacher meetings calmly", category: "parenting", text: "Help me prepare for a parent-teacher meeting about my teenager without getting angry at home afterwards. Give me five questions to ask the teacher, and a calm way to share the feedback with my child." },
  { id: "parenting-678", title: "Talk about cheating in exams", category: "parenting", text: "I heard my teenager's friends cheat in exams and I worry my child may try it too. Help me talk about honesty, the real risks of cheating, and how to handle exam fear in a better way, without accusing my child." },
  { id: "parenting-679", title: "Help your teen after a bad paper", category: "parenting", text: "My teenager came home upset after a bad exam paper and says the whole year is ruined. Give me calming words for today, a way to stop them overthinking, and a plan to focus on the next paper instead." },
  { id: "parenting-680", title: "Balance study and play during exams", category: "parenting", text: "Help me balance my teenager's study and play during exam season. Suggest a daily timetable with study blocks, outdoor play, family time and rest, so they stay fresh and do not burn out before the last paper." },
  { id: "parenting-681", title: "Talk about results day with your teen", category: "parenting", text: "Results day is coming and my teenager is very nervous. Help me plan the day calmly, with what to say whatever the result is, a small celebration for their effort, and next steps we can decide together without rushing." },
  { id: "parenting-682", title: "Set fair phone rules for teenagers", category: "parenting", text: "Help me set fair phone rules with my teenager instead of just taking the phone away. Include screen-free meal times, a night-time charging spot outside the bedroom, and a weekly review so the rules feel shared, not imposed." },
  { id: "parenting-683", title: "Talk about phone use at night", category: "parenting", text: "My teenager uses the phone late at night and wakes up tired for school. Help me talk about sleep and screen light in simple words, agree on a switch-off time, and set up a charging station outside their bedroom." },
  { id: "parenting-684", title: "Help your teen cut screen time", category: "parenting", text: "My teenager spends six hours a day on the phone. Give me a gentle four-week plan to reduce screen time, with fun offline activities, family phone-free hours, and small rewards for sticking to the new limits." },
  { id: "parenting-685", title: "Talk about social media with teens", category: "parenting", text: "Help me talk to my teenager about social media without sounding old-fashioned. Cover likes, followers, comparing lives online, and privacy, with simple questions that help them think about what they share and follow." },
  { id: "parenting-686", title: "When your teen is addicted to gaming", category: "parenting", text: "My teenager plays online games for hours and gets angry when asked to stop. Give me a calm plan with agreed gaming hours, breaks, offline hobbies to try, and what to do if gaming starts hurting studies or sleep." },
  { id: "parenting-687", title: "Talk about online strangers and safety", category: "parenting", text: "Help me talk to my teenager about staying safe online, including strangers in chats and games, sharing photos, and personal details. Give me simple safety rules and what to do if someone online makes them uncomfortable." },
  { id: "parenting-688", title: "Help a teen handle cyberbullying", category: "parenting", text: "My teenager is being teased online by classmates and feels very upset. Give me comforting words, steps to save proof, block and report, and a calm plan to talk to the school and support my child through it." },
  { id: "parenting-689", title: "Set a first phone agreement together", category: "parenting", text: "We are giving our teenager their first phone. Help me write a simple family agreement covering screen time, who they can chat with, sharing photos, and what happens if rules are broken, in words a teenager will accept." },
  { id: "parenting-690", title: "Talk about what teens watch online", category: "parenting", text: "I worry about the videos my teenager watches online. Help me talk about it without spying, with questions about what they enjoy, how to spot harmful content, and simple limits we can agree on together." },
  { id: "parenting-691", title: "Phone-free family time that works", category: "parenting", text: "Help me plan phone-free family time that my teenager will not hate. Suggest five fun activities like cooking, board games or an evening walk, plus a simple rule for phones during meals that the whole family follows." },
  { id: "parenting-692", title: "When your teen hides their phone", category: "parenting", text: "My teenager hides their phone and gets angry when I ask what they are doing. Help me talk about trust and privacy calmly, agree on basic safety checks, and rebuild openness without reading every message they send." },
  { id: "parenting-693", title: "Talk about online privacy with teens", category: "parenting", text: "Help me teach my teenager about online privacy in simple words. Cover strong passwords, location sharing, public profiles, and what never to post, with a quick checklist we can go through together this weekend." },
  { id: "parenting-694", title: "Help your teen handle online comparison", category: "parenting", text: "My teenager feels sad comparing their life with influencers and classmates online. Help me talk about how online posts show only the best moments, and suggest daily habits that build real confidence offline." },
  { id: "parenting-695", title: "Talk about reels and short videos", category: "parenting", text: "My teenager watches short videos for hours and cannot stop scrolling. Help me explain how these apps are designed to keep them watching, agree on a daily limit, and suggest healthier ways to relax in the evening." },
  { id: "parenting-696", title: "When your teen wants expensive gadgets", category: "parenting", text: "My teenager wants an expensive phone because all their friends have one. Help me talk about needs versus wants, our family budget in simple words, and a saving plan so they can work towards it over time." },
  { id: "parenting-697", title: "Talk about group chats and drama", category: "parenting", text: "My teenager is upset by fights and gossip in their class group chat. Help me guide them on when to reply, when to stay quiet, when to leave a group, and how to handle friends who share screenshots." },
  { id: "parenting-698", title: "Help your teen use phones for study", category: "parenting", text: "Help me show my teenager how to use their phone for studying instead of only entertainment. Suggest useful habits like revision videos, flashcard apps, timers and notes, with a simple daily study routine using the phone wisely." },
  { id: "parenting-699", title: "Talk about phone use during meals", category: "parenting", text: "Everyone in our family uses phones at the dinner table, including me. Help me start a phone-free meal rule we all follow, with a simple phone basket idea and three conversation topics to make meals enjoyable again." },
  { id: "parenting-700", title: "When your teen shares too much online", category: "parenting", text: "My teenager shares personal photos and details online without thinking. Help me explain the risks simply, agree on what is safe to share, and show them how to check privacy settings on their favourite apps." },
  { id: "parenting-701", title: "Talk about digital footprint with teens", category: "parenting", text: "Help me explain digital footprint to my teenager in simple words, showing how posts and photos can stay online for years. Give me real examples and a checklist for cleaning up old posts before college applications." },
  { id: "parenting-702", title: "Help a teen who lost their phone", category: "parenting", text: "My teenager lost their phone and is very upset. Help me stay calm, report the loss, lock the device, and talk about responsibility without shouting, plus a simple plan to prevent losing it again." },
  { id: "parenting-703", title: "Set screen limits without daily fights", category: "parenting", text: "Every day we fight about screen time with my teenager. Help me set clear, written limits we both agree on, with a warning before time ends, and calm consequences that stay the same every day, so fights reduce." },
  { id: "parenting-704", title: "Talk about online friends your teen made", category: "parenting", text: "My teenager has made friends online through games and I do not know who they are. Help me ask about these friends without sounding suspicious, and agree on safety rules for chatting and gaming with people they have never met." },
  { id: "parenting-705", title: "Help your teen sleep without screens", category: "parenting", text: "My teenager cannot fall asleep without watching videos on their phone. Give me a calming bedtime routine with no screens for the last hour, a book or music instead, and gentle words to make the change easier." },
  { id: "parenting-706", title: "Talk about your teen's best friend", category: "parenting", text: "My teenager talks about their best friend all the time and I want to know them better. Give me warm questions to ask about this friendship, how to welcome the friend home, and what to do if I have worries about them." },
  { id: "parenting-707", title: "Help your teen make new friends", category: "parenting", text: "My teenager just changed schools and has no friends yet. Give me gentle tips to help them join clubs, talk to classmates, and invite someone home, plus encouraging words for lonely days at their new school." },
  { id: "parenting-708", title: "Talk about peer pressure with teens", category: "parenting", text: "Help me talk to my teenager about peer pressure in simple, honest words. Cover saying no to risky dares, handling teasing for refusing, and practising confident replies they can use when friends push them too far." },
  { id: "parenting-709", title: "When your teen's friend is a bad influence", category: "parenting", text: "I worry one of my teenager's friends is a bad influence. Help me talk about it without banning the friendship outright, listen to my child's view, and set sensible limits that protect them while keeping trust." },
  { id: "parenting-710", title: "Help a teen after a friendship breakup", category: "parenting", text: "My teenager's best friend has stopped talking to them and they are heartbroken. Give me comforting words, ways to help them understand what happened, and gentle ideas to rebuild confidence and make new friends." },
  { id: "parenting-711", title: "Talk about bullying at school", category: "parenting", text: "My teenager may be facing bullying at school but will not tell me clearly. Give me gentle questions to ask, signs to watch for, and a step-by-step plan to support them and speak to the school safely." },
  { id: "parenting-712", title: "When your teen bullies someone else", category: "parenting", text: "I found out my teenager has been teasing a classmate. Help me talk about it firmly but kindly, understand why it happened, guide them to apologise sincerely, and plan how to make things right at school." },
  { id: "parenting-713", title: "Talk about jealousy between teen friends", category: "parenting", text: "My teenager feels jealous when their friends do better in exams or get more attention. Help me talk about jealousy honestly, with words that normalise the feeling and simple habits to focus on their own strengths." },
  { id: "parenting-714", title: "Help your teen handle gossip", category: "parenting", text: "My teenager is upset because classmates are gossiping about them. Give me calming words, practical steps like ignoring rumours and talking to one trusted adult, and ways to rebuild their confidence at school." },
  { id: "parenting-715", title: "Talk about sleepovers and outings", category: "parenting", text: "My teenager wants to go for sleepovers and late outings with friends. Help me set fair rules about where, with whom and till when, plus safety checks I can do without embarrassing them in front of friends." },
  { id: "parenting-716", title: "When your teen feels left out", category: "parenting", text: "My teenager feels left out because their friends made plans without them. Give me comforting words, help them see it may not be personal, and suggest ways to reach out, join new groups, and build stronger friendships." },
  { id: "parenting-717", title: "Talk about crushes with your teenager", category: "parenting", text: "My teenager has a crush on someone at school and I want to talk about it without embarrassing them. Give me light, respectful questions, simple advice on handling feelings, and boundaries that keep things healthy and safe." },
  { id: "parenting-718", title: "Help your teen choose good friends", category: "parenting", text: "Help me talk to my teenager about what makes a good friend, like kindness, honesty and respect. Give me simple examples they can use to judge friendships, and questions to ask themselves when a friendship feels wrong." },
  { id: "parenting-719", title: "Talk about parties and late nights", category: "parenting", text: "My teenager wants to attend late-night parties with friends. Help me talk about safety, transport, and knowing when to call home, and agree on a fair curfew and check-in plan we can both live with." },
  { id: "parenting-720", title: "When your teen argues about friends", category: "parenting", text: "We argue every time I question my teenager's choice of friends. Give me a calmer way to raise my worries, listen to their side, and agree on simple safety rules instead of fighting about the friends themselves." },
  { id: "parenting-721", title: "Help a teen who has no friends", category: "parenting", text: "My teenager says they have no real friends and eats lunch alone. Give me a gentle plan to build their social confidence, find clubs or activities they enjoy, and practise small conversation skills step by step." },
  { id: "parenting-722", title: "Talk about sharing and secrets with friends", category: "parenting", text: "My teenager shares everything with friends, including family matters. Help me talk about what is private, why some things stay in the family, and how to be a loyal friend without sharing things that are not theirs." },
  { id: "parenting-723", title: "Help your teen apologise to a friend", category: "parenting", text: "My teenager hurt a friend's feelings and does not know how to apologise. Draft a simple, sincere apology they can say or write, and explain why a real apology needs honesty, not excuses, and how to rebuild the friendship." },
  { id: "parenting-724", title: "Talk about teamwork and group projects", category: "parenting", text: "My teenager struggles with group projects because classmates do not do their share. Give me advice on talking to the group, dividing work fairly, handling free riders, and telling the teacher without sounding like a complainer." },
  { id: "parenting-725", title: "When friends pressure your teen to spend", category: "parenting", text: "My teenager feels pressured to spend money like their friends on cafes, movies and branded clothes. Help me talk about peer spending, set a fair monthly budget, and give them confident replies to use with friends." },
  { id: "parenting-726", title: "Talk about trust with your teenager", category: "parenting", text: "Help me talk to my teenager about trust in our family, what it means, how it is built through small honest acts, and how it can be repaired after a mistake, with a simple agreement we can both sign." },
  { id: "parenting-727", title: "When your teen lies to you", category: "parenting", text: "I caught my teenager lying about where they were. Help me respond calmly instead of shouting, understand why they lied, and rebuild honesty with clear consequences and a promise that telling the truth is safe." },
  { id: "parenting-728", title: "Help your teen keep your trust", category: "parenting", text: "My teenager wants more freedom and I want to trust them. Give me a simple trust plan with small responsibilities they can earn, regular check-ins, and clear consequences, so freedom grows as trust grows." },
  { id: "parenting-729", title: "Talk about secrets your teen keeps", category: "parenting", text: "My teenager keeps secrets from me and I worry. Help me talk about the difference between private thoughts and dangerous secrets, and show them they can tell me anything difficult without fear of punishment." },
  { id: "parenting-730", title: "Rebuild trust after a broken promise", category: "parenting", text: "My teenager broke an important promise and our trust is damaged. Give me a step-by-step plan to repair trust, including an honest talk, small consistent actions over four weeks, and how to forgive without forgetting the lesson." },
  { id: "parenting-731", title: "Talk about dating with your teenager", category: "parenting", text: "I think my teenager may be dating someone. Help me start this talk gently, without prying or judging, covering respect, boundaries, safety and studies, and agree on simple family rules about meeting and messaging." },
  { id: "parenting-732", title: "Set a fair curfew with your teen", category: "parenting", text: "Help me set a fair curfew with my teenager for outings and functions. Suggest age-wise timings, how to handle special occasions, what happens if they are late, and a check-in message system that feels respectful." },
  { id: "parenting-733", title: "Talk about pocket money honestly", category: "parenting", text: "Help me talk to my teenager about pocket money, including how much is fair, what it should cover, saving for bigger wishes, and what to do if they spend it all in the first week of the month." },
  { id: "parenting-734", title: "When your teen breaks a house rule", category: "parenting", text: "My teenager broke a clear house rule about [rule]. Help me handle it calmly with a fair consequence, a talk about why the rule exists, and a fresh start, instead of shouting or punishing for days." },
  { id: "parenting-735", title: "Talk about alcohol and smoking risks", category: "parenting", text: "Help me talk to my teenager about alcohol, smoking and other risky habits in honest, simple words. Cover health risks, peer pressure, and what to do if a friend offers them something at a party." },
  { id: "parenting-736", title: "Help your teen own their mistakes", category: "parenting", text: "My teenager blames others whenever something goes wrong. Help me teach them to own mistakes kindly, with simple words for saying sorry, fixing what they can, and learning from the experience without shame." },
  { id: "parenting-737", title: "Talk about privacy and personal space", category: "parenting", text: "My teenager wants more privacy, like a locked diary and knocking before entering. Help me respect their space while keeping basic safety, with a simple family agreement on privacy, rooms and personal belongings." },
  { id: "parenting-738", title: "When your teen wants to travel alone", category: "parenting", text: "My teenager wants to travel alone with friends to [place]. Help me weigh safety, age and distance, talk through my worries honestly, and agree on conditions like check-ins, money and emergency contacts if we allow it." },
  { id: "parenting-739", title: "Talk about honesty in small things", category: "parenting", text: "My teenager tells small lies about homework and chores. Help me talk about why small honesty matters, with everyday examples, gentle consequences, and praise when they choose to tell the truth even when it is hard." },
  { id: "parenting-740", title: "Help your teen handle a strict teacher", category: "parenting", text: "My teenager feels a teacher is too strict and unfair. Help me listen without taking sides at once, teach them how to handle strict teachers calmly, and decide when I should speak to the school about it." },
  { id: "parenting-741", title: "Talk about body changes and confidence", category: "parenting", text: "My teenager feels awkward about body changes and avoids family photos and functions. Help me talk about growing up with kindness, normalise these changes, and suggest ways to rebuild their confidence gently." },
  { id: "parenting-742", title: "When your teen compares families", category: "parenting", text: "My teenager says other families are cooler and more relaxed than ours. Help me respond without getting hurt, understand what they really want, and find small changes we can make while keeping our family values." },
  { id: "parenting-743", title: "Talk about festivals with your teenager", category: "parenting", text: "My teenager finds family festivals boring and wants to stay in their room. Help me involve them in planning, give them a role they enjoy, and agree on a fair balance between family time and time with friends." },
  { id: "parenting-744", title: "Help your teen manage mood swings", category: "parenting", text: "My teenager's moods change quickly and the whole house feels tense. Help me understand normal teenage mood swings, respond calmly, give them space when needed, and know the signs that mean extra support is needed." },
  { id: "parenting-745", title: "Talk about staying safe while out", category: "parenting", text: "Help me talk to my teenager about staying safe when they go out with friends, including telling us where they are, keeping their phone charged, travelling in groups, and what to do if they feel unsafe." },
  { id: "parenting-746", title: "When your teen wants a part-time job", category: "parenting", text: "My teenager wants a part-time job during holidays. Help me talk about the pros and cons, check it will not hurt studies, agree on safe work and timings, and plan how they will save or spend what they earn." },
  { id: "parenting-747", title: "Talk about self-respect with teens", category: "parenting", text: "Help me talk to my teenager about self-respect in simple words, including saying no to disrespect, choosing kind friends, and standing up for themselves, with everyday examples from school and family life." },
  { id: "parenting-748", title: "Help your teen prepare for interviews", category: "parenting", text: "My teenager has a school interview for [purpose] and feels nervous. Help me prepare them with practise questions, confident body language, simple answers about their strengths, and a calm morning routine for the big day." },
  { id: "parenting-749", title: "Talk about food and eating habits", category: "parenting", text: "My teenager skips meals and eats too much junk food. Help me talk about food without nagging, plan tasty home meals they will enjoy, and agree on simple rules for snacks, soft drinks and eating on time." },
  { id: "parenting-750", title: "When your teen stays up too late", category: "parenting", text: "My teenager stays up late every night and struggles to wake for school. Help me agree on a realistic bedtime, a wind-down routine without screens, and a morning plan that makes waking up less of a daily battle." },
  { id: "parenting-751", title: "Talk about handling disappointment gracefully", category: "parenting", text: "My teenager takes every disappointment very hard, like losing a match or missing a chance. Help me teach them to handle setbacks calmly, with comforting words and a simple way to try again without losing hope." },
  { id: "parenting-752", title: "Help your teen set personal goals", category: "parenting", text: "Help me guide my teenager to set three personal goals for this year, covering studies, health and a hobby. Show us how to break each goal into small weekly steps and celebrate progress every month together." },
  { id: "parenting-753", title: "Talk about kindness towards elders", category: "parenting", text: "Help me talk to my teenager about being kind and patient with grandparents and elders at home. Give me simple examples, like listening to their stories and helping with small tasks, and words to use when my teen is rude." },
  { id: "parenting-754", title: "When your teen wants to quit an activity", category: "parenting", text: "My teenager wants to quit [activity] after months of classes. Help me talk through their reasons, decide together if it is boredom, pressure or a real dislike, and agree on a fair way to pause or change activities." },
  { id: "parenting-755", title: "Talk about exam fear with younger siblings", category: "parenting", text: "My teenager's exam stress is affecting their younger sibling at home. Help me talk to both children calmly, keep the house peaceful during exams, and give the younger one simple ways to support their elder brother or sister." },
  { id: "parenting-756", title: "Help your teen revise with friends", category: "parenting", text: "My teenager wants to study with friends before exams. Help me set up a useful group study plan with fixed timings, topics to cover, and rules against chatting, so the group helps revision instead of wasting time." },
  { id: "parenting-757", title: "Talk about choosing subjects for class 11", category: "parenting", text: "My teenager must choose subjects for class 11 and feels confused. Help us compare the options simply, look at their marks and interests, and talk to a teacher or counsellor before making the final choice together." },
  { id: "parenting-758", title: "When your teen is scared of the future", category: "parenting", text: "My teenager worries a lot about the future, jobs and whether they will succeed. Help me reassure them with honest words, break big worries into small steps, and show them that many paths can lead to a good life." },
  { id: "parenting-759", title: "Talk about handling exam competition", category: "parenting", text: "My teenager feels crushed by competition with classmates over ranks and marks. Help me talk about healthy competition, focusing on personal progress, and simple daily habits that build steady improvement without constant comparison." },
  { id: "parenting-760", title: "Help your teen use a study timetable", category: "parenting", text: "Help me create a simple weekly study timetable for my teenager with school, homework, revision, play and rest. Make it flexible enough for bad days and include a Sunday review so we can adjust it together." },
  { id: "parenting-761", title: "Talk about phone addiction honestly", category: "parenting", text: "My teenager admits they cannot stop using their phone. Help me talk about phone addiction without blame, agree on a gradual reduction plan, and find offline activities they enjoy, like sport, music or cooking together." },
  { id: "parenting-762", title: "When your teen watches adult content", category: "parenting", text: "I found adult content on my teenager's phone and I am worried. Help me stay calm, talk about it honestly without shaming them, explain why it is harmful at their age, and set clear safety rules going forward." },
  { id: "parenting-763", title: "Talk about online gaming friends", category: "parenting", text: "My teenager spends hours talking to gaming friends online. Help me understand this world better, ask the right safety questions, and agree on limits for gaming time and sharing personal details with strangers." },
  { id: "parenting-764", title: "Help your teen handle exam-time phone rules", category: "parenting", text: "During exams my teenager wants their phone for study videos but gets distracted. Help me set exam-time phone rules with fixed study apps, a timer, and a phone box during deep study, so the phone helps instead of harming." },
  { id: "parenting-765", title: "Talk about sharing passwords safely", category: "parenting", text: "My teenager shares passwords with friends and I worry about their accounts. Help me explain password safety in simple words, why sharing is risky, and how to create strong passwords they can remember easily." },
  { id: "parenting-766", title: "When your teen is trolled online", category: "parenting", text: "My teenager was trolled online and feels humiliated. Give me comforting words, steps to block and report the trolls, save proof if needed, and ways to help them feel safe and confident online again." },
  { id: "parenting-767", title: "Talk about fake news and online rumours", category: "parenting", text: "My teenager believes everything they see in forwarded messages and videos. Help me teach them to check facts simply, ask who shared it, and pause before forwarding, with three fun examples we can test together." },
  { id: "parenting-768", title: "Help your teen build a morning routine", category: "parenting", text: "My teenager wakes up late and rushes to school every day. Help me build a calm morning routine with a fixed wake-up time, a phone-free first 30 minutes, breakfast, and a school bag packed the night before." },
  { id: "parenting-769", title: "Talk about friendship and loyalty", category: "parenting", text: "Help me talk to my teenager about loyalty in friendship, including standing by a friend in trouble, keeping promises, and knowing when loyalty should not mean covering up something wrong or dangerous." },
  { id: "parenting-770", title: "When your teen's friend visits often", category: "parenting", text: "My teenager's friend visits our home almost every day. Help me set friendly house rules about timings, noise and sharing space, and welcome the friend warmly while keeping our family routine peaceful." },
  { id: "parenting-771", title: "Talk about handling a toxic friendship", category: "parenting", text: "My teenager is in a friendship that feels toxic, with constant put-downs and control. Help me talk about the warning signs gently, support them without forcing a breakup, and plan steps to step back safely." },
  { id: "parenting-772", title: "Help your teen join a team sport", category: "parenting", text: "My teenager wants to join a team sport but feels shy and unfit. Give me encouraging words, a simple plan to try a trial session, and ways to handle early struggles so they keep going and make new friends." },
  { id: "parenting-773", title: "Talk about respect for teachers", category: "parenting", text: "Help me talk to my teenager about respecting teachers even when they disagree. Give me simple words for handling unfair moments calmly, raising concerns politely, and learning from teachers they find difficult." },
  { id: "parenting-774", title: "When your teen lies about homework", category: "parenting", text: "My teenager lies about finishing homework and I only find out from the teacher. Help me talk about it calmly, find out if the work is too hard or boring, and set up a simple daily homework check that feels supportive." },
  { id: "parenting-775", title: "Talk about giving your teen responsibility", category: "parenting", text: "Help me give my teenager more responsibility at home, like managing their own timetable, laundry or a small budget. Suggest age-wise tasks, how to let them fail safely, and how to praise growing independence." },
  { id: "parenting-776", title: "Help your teen handle a family move", category: "parenting", text: "We are moving to a new city and my teenager is upset about leaving friends and school. Help me talk about the move honestly, involve them in small choices, and plan ways to stay in touch and settle in." },
  { id: "parenting-777", title: "Talk about handling peer rejection", category: "parenting", text: "My teenager was rejected by a friend group and feels worthless. Give me comforting words, help them understand rejection is not about their value, and suggest new groups and activities where they can belong." },
  { id: "parenting-778", title: "When your teen wants to dye hair", category: "parenting", text: "My teenager wants to dye their hair or change their look drastically. Help me talk about it calmly, understand what it means to them, and agree on a safe, school-friendly option instead of a flat no." },
  { id: "parenting-779", title: "Talk about celebrating small wins", category: "parenting", text: "Help me celebrate my teenager's small wins, like finishing a tough chapter or helping at home. Give me ten simple celebration ideas that cost little or nothing and words that make them feel truly seen." },
  { id: "parenting-780", title: "Help your teen cope with exam failure", category: "parenting", text: "My teenager failed a subject and thinks their future is over. Give me gentle words for the first week, a plan to understand what went wrong, and options like re-exams, extra help or a new approach to the subject." },
  { id: "parenting-781", title: "Talk about study pressure from relatives", category: "parenting", text: "Relatives keep pressuring my teenager about marks at every family gathering. Help me protect my child with polite replies, talk to relatives privately, and reassure my teenager that their worth is not their rank." },
  { id: "parenting-782", title: "When your teen compares phones with friends", category: "parenting", text: "My teenager feels ashamed of their old phone because friends have new ones. Help me talk about value versus show-off, plan a fair upgrade timeline, and build confidence that is not tied to gadgets." },
  { id: "parenting-783", title: "Talk about online challenges and dares", category: "parenting", text: "My teenager's friends are doing risky online challenges and dares. Help me explain the dangers simply, teach them to say no confidently, and agree on what to do if a friend pressures them to join." },
  { id: "parenting-784", title: "Help your teen manage time better", category: "parenting", text: "My teenager wastes hours and then rushes homework at midnight. Help me teach simple time management with a daily to-do list, fixed phone-free study hours, and a small reward for finishing work on time." },
  { id: "parenting-785", title: "Talk about trust after checking their phone", category: "parenting", text: "I checked my teenager's phone without asking and now they feel betrayed. Help me apologise honestly, explain my worry, and agree on open safety checks we both accept, so trust can be rebuilt." },
  { id: "parenting-786", title: "Help your teen talk to grandparents", category: "parenting", text: "My teenager barely talks to their grandparents and it hurts them. Help me bridge the gap with shared activities, like cooking a family recipe or looking at old photos, and gentle words to encourage regular calls and visits." },
  { id: "parenting-787", title: "Talk about handling exam-time anxiety", category: "parenting", text: "My teenager feels anxious for weeks before exams, with headaches and poor sleep. Give me a calm daily plan with breathing exercises, light exercise, limited revision hours, and reassuring words to ease their worry." },
  { id: "parenting-788", title: "When your teen wants to skip school", category: "parenting", text: "My teenager often wants to skip school and says they feel sick. Help me find out if it is fear, boredom or bullying, talk to the school if needed, and make mornings easier without forcing them out of bed." },
  { id: "parenting-789", title: "Talk about good manners with teens", category: "parenting", text: "Help me talk to my teenager about good manners, like greeting elders, saying please and thank you, and speaking politely to helpers and shopkeepers, with simple examples and a gentle reminder system at home." },
  { id: "parenting-790", title: "Help your teen handle a strict curfew", category: "parenting", text: "My teenager thinks our curfew is unfair compared to their friends. Help me explain our reasons calmly, listen to their view, and agree on a slightly later time for special occasions with clear check-in rules." },
  { id: "parenting-791", title: "Talk about saving money with teens", category: "parenting", text: "Help me teach my teenager to save money with a simple plan, like saving a part of pocket money every week, setting a goal for something they want, and tracking savings in a notebook or a small jar." },
  { id: "parenting-792", title: "When your teen is glued to headphones", category: "parenting", text: "My teenager wears headphones all day and ignores the family. Help me talk about it without a fight, agree on headphone-free times like meals, and find music or podcasts we can enjoy together sometimes." },
  { id: "parenting-793", title: "Talk about handling online hate", category: "parenting", text: "My teenager saw hateful comments about them in a group and feels hurt. Give me comforting words, steps to report and block, and a plan to talk to a teacher or parent of the other child if it continues." },
  { id: "parenting-794", title: "Help your teen prepare for a competition", category: "parenting", text: "My teenager is entering a [competition type] competition and feels nervous. Help me prepare them with a practise schedule, calming words for the day, and a reminder that effort matters more than winning." },
  { id: "parenting-795", title: "Talk about friendship across genders", category: "parenting", text: "My teenager has close friends of the opposite gender and relatives are gossiping. Help me talk about healthy friendships with respect, handle relatives' comments calmly, and reassure my child that good friends matter most." },
  { id: "parenting-796", title: "When your teen breaks curfew", category: "parenting", text: "My teenager came home two hours late without calling. Help me handle it calmly tonight, listen to their reason first, agree on a fair consequence, and set a simple check-in rule for next time they go out." },
  { id: "parenting-797", title: "Talk about volunteering with your teen", category: "parenting", text: "Help me talk to my teenager about volunteering, like helping at a food drive or teaching younger kids. Suggest five easy options in [your city], and explain how volunteering builds confidence, skills and new friendships." },
  { id: "parenting-798", title: "Help your teen handle a new school", category: "parenting", text: "My teenager is starting a new school and feels anxious about fitting in. Give me a two-week plan with tips for the first day, joining activities, and encouraging words for hard days when they miss old friends." },
  { id: "parenting-799", title: "Talk about exam results with relatives", category: "parenting", text: "Relatives ask my teenager about exam results in front of everyone. Help me prepare polite replies my child can use, and a plan for me to step in kindly so results are never discussed like a public scorecard." },
  { id: "parenting-800", title: "When your teen wants a social media account", category: "parenting", text: "My teenager wants their first social media account and I am unsure. Help me decide on a safe age and app, set privacy rules together, agree on screen limits, and plan regular check-ins about what they see online." },
  { id: "parenting-801", title: "Talk about handling exam-time comparisons", category: "parenting", text: "During exams my teenager compares marks with friends after every paper. Help me talk about why this hurts confidence, suggest a no-comparison rule at home, and focus their energy on the next paper instead." },
  { id: "parenting-802", title: "Help your teen build study confidence", category: "parenting", text: "My teenager says I am dumb and cannot learn this subject. Help me rebuild their study confidence with small wins, breaking topics into tiny steps, and praise for effort, so they start believing they can improve." },
  { id: "parenting-803", title: "Talk about phone use on family trips", category: "parenting", text: "On family trips my teenager is on their phone the whole time. Help me set fun phone limits for the trip, like photo time and phone-free meals, and plan activities they will enjoy so the trip feels shared." },
  { id: "parenting-804", title: "When your teen trusts the wrong person", category: "parenting", text: "My teenager trusts someone online who worries me. Help me talk about it without accusing them, explain warning signs of unsafe people, and agree on safety steps, including telling a trusted adult if anything feels wrong." },
  { id: "parenting-805", title: "Talk about handling exam stress together", category: "parenting", text: "Exam stress is making our whole family tense. Help us handle it together with a calm home routine, daily check-ins, shared meals without exam talk, and a family walk or game every evening to relax." },
  { id: "parenting-806", title: "Help your teen say no to friends", category: "parenting", text: "My teenager cannot say no to friends, even when it costs them time and money. Teach them simple, firm ways to refuse, like I cannot today or my parents will not allow it, and practise the replies together." },
  { id: "parenting-807", title: "Talk about your teen's role models", category: "parenting", text: "Help me talk to my teenager about their role models, like sports stars or online creators. Ask what they admire, discuss the good and the unrealistic parts, and help them choose values worth following in real life." },
  { id: "parenting-808", title: "When your teen is secretive about school", category: "parenting", text: "My teenager never tells me anything about school and changes the topic. Help me find gentle ways to learn what is happening, like talking to teachers, watching their mood, and creating safe moments for them to open up." },
  { id: "parenting-809", title: "Talk about handling a teen's first heartbreak", category: "parenting", text: "My teenager is going through their first heartbreak and feels devastated. Give me gentle, non-judging words, ways to help them heal slowly, and signs that mean they may need extra support from a counsellor." },
  { id: "parenting-810", title: "Help your teen balance phone and study", category: "parenting", text: "Help me create a daily balance for my teenager between phone time and study time. Suggest a simple timetable with phone breaks after study blocks, a charging spot outside the study room, and a weekly review together." },
  { id: "parenting-811", title: "Talk about trust and growing up", category: "parenting", text: "Help me talk to my teenager about growing up and earning trust step by step. Explain how small honest choices lead to bigger freedoms, and agree on three freedoms they can earn this year by showing responsibility." },
  { id: "parenting-812", title: "When your teen argues in public", category: "parenting", text: "My teenager argues with me in public and it embarrasses us both. Help me handle it calmly in the moment, agree on a private way to discuss disagreements later, and set a simple family rule about public arguments." },
  { id: "parenting-813", title: "Talk about exam-time food and energy", category: "parenting", text: "Help me plan simple, energising meals for my teenager during exams, with brain-friendly foods, enough water, and light snacks for study breaks, so they stay alert without heavy meals that make them sleepy." },
  { id: "parenting-814", title: "Help your teen handle a rude classmate", category: "parenting", text: "A classmate is rude to my teenager every day. Give me advice on staying calm, setting firm boundaries, when to ignore and when to tell a teacher, and how to keep their confidence strong at school." },
  { id: "parenting-815", title: "Talk about your teen's online reputation", category: "parenting", text: "Help me talk to my teenager about their online reputation, including what teachers and future colleges might see. Give me a simple checklist to review profiles, photos and comments together every few months." },
  { id: "parenting-816", title: "When your teen wants to study abroad", category: "parenting", text: "My teenager dreams of studying abroad after school. Help me talk about it realistically, covering costs, exams, and other good options in India, and plan small steps like research and saving to explore the dream." },
  { id: "parenting-817", title: "Talk about handling sibling jealousy", category: "parenting", text: "My teenager feels jealous of their younger sibling getting more attention. Help me talk about it honestly, give them one-on-one time each week, and show them they are valued for who they are, not compared." },
  { id: "parenting-818", title: "Help your teen cope with a move", category: "parenting", text: "My teenager is struggling after our move to [city], with no friends and a new school. Give me a gentle settling-in plan with activities, ways to stay in touch with old friends, and patience for the first months." },
  { id: "parenting-819", title: "Talk about exam-time screen rules", category: "parenting", text: "Help me set screen rules for my teenager during exam time that feel fair. Include study apps that are allowed, entertainment limits, a phone-free hour before bed, and a small reward for following the plan." },
  { id: "parenting-820", title: "When your teen hides exam marks", category: "parenting", text: "My teenager hides their test marks from me because they fear my reaction. Help me respond with calm and kindness, show them marks are information not punishment, and agree on a weekly marks check that feels safe." },
  { id: "parenting-821", title: "Talk about friendship and study balance", category: "parenting", text: "My teenager spends all their time with friends and ignores studies. Help me talk about balance without banning friends, agree on study hours first, and plan friend time as a reward after work is done." },
  { id: "parenting-822", title: "Help your teen handle exam-day nerves", category: "parenting", text: "My teenager feels sick with nerves on exam mornings. Give me a calm exam-day plan with an early wake-up, a light breakfast, reaching the centre early, and breathing exercises to use while waiting outside the hall." },
  { id: "parenting-823", title: "Talk about saying sorry as a parent", category: "parenting", text: "I want to show my teenager that parents can say sorry too. Help me talk about a time I was wrong, apologise sincerely, and explain how owning mistakes makes our family stronger and more honest." },
  { id: "parenting-824", title: "When your teen wants more pocket money", category: "parenting", text: "My teenager keeps asking for more pocket money. Help me talk about our family budget honestly, review what the money covers, and agree on ways they can earn extra through chores or small holiday work." },
  { id: "parenting-825", title: "Build a trusting bond with your teenager", category: "parenting", text: "Help me build a stronger trusting bond with my teenager over the next three months. Give me a simple weekly plan with one-on-one time, honest talks, shared activities, and small promises I keep, so trust grows steadily." },
  { id: "parenting-826", title: "Plan a weekly family dinner menu", category: "parenting", text: "Help me plan a simple family dinner menu for one week, with one vegetarian dish each night. Use ingredients we can buy easily in [your city], keep cooking time under 40 minutes, and include one dish each child can help prepare." },
  { id: "parenting-827", title: "Make breakfast together on Sundays", category: "parenting", text: "Suggest a fun Sunday breakfast that our family of [number] can cook together in one hour. Give simple jobs for a [age]-year-old child, list the ingredients with quantities, and add a tip for cleaning up together afterwards." },
  { id: "parenting-828", title: "Start a no-phones dinner rule", category: "parenting", text: "Help our family start a no-phones rule at dinner without arguments. Suggest a gentle way to explain it to children aged [ages], a simple phone basket idea, and three conversation starters we can use at the table each evening." },
  { id: "parenting-829", title: "Cook one new dish every week", category: "parenting", text: "Help us cook one new dish together every week for two months. Suggest eight simple Indian recipes for beginners, list the ingredients for each, and give each family member a small cooking job so everyone takes part." },
  { id: "parenting-830", title: "Plan healthy tiffins the family likes", category: "parenting", text: "Plan five healthy tiffin ideas for our family that children will actually finish. Each tiffin should take under 20 minutes to pack, use seasonal vegetables, and include one fruit. Add a note on keeping food fresh till lunch." },
  { id: "parenting-831", title: "Teach children to set the table", category: "parenting", text: "Teach my [age]-year-old how to set the dinner table correctly in a simple, fun way. Explain where the plate, glass, spoon and bowl go, give a short daily checklist, and suggest a small reward for doing it without being reminded." },
  { id: "parenting-832", title: "Create a family recipe book together", category: "parenting", text: "Help our family create a simple recipe book with 10 favourite family dishes. For each dish, ask for the ingredients, steps and who taught us the recipe. Suggest a neat layout we can print and keep in the kitchen." },
  { id: "parenting-833", title: "Plan a picnic lunch for the family", category: "parenting", text: "Plan a simple picnic lunch for our family of [number] at [place]. Suggest five foods that travel well without a fridge, a packing list, games for children, and what to carry for shade, water and cleaning up after the picnic." },
  { id: "parenting-834", title: "Handle fussy eaters at family meals", category: "parenting", text: "My [age]-year-old refuses most vegetables at family meals. Suggest five gentle ways to encourage trying new foods without forcing or scolding, plus three simple recipes that hide vegetables in dishes children already enjoy eating." },
  { id: "parenting-835", title: "Plan a Jain-friendly family feast", category: "parenting", text: "Plan a Jain-friendly family feast for [number] people for [occasion]. Suggest a starter, two main dishes, one sweet and a drink, all without onion, garlic or root vegetables. Keep the recipes simple and list the shopping needed." },
  { id: "parenting-836", title: "Make Friday dinner a family ritual", category: "parenting", text: "Help us turn Friday dinner into a special family ritual. Suggest a simple theme for each week, a dish everyone helps to make, one question each person answers at the table, and a short closing habit that ends the week happily." },
  { id: "parenting-837", title: "Teach children about balanced meals", category: "parenting", text: "Explain a balanced meal to my [age]-year-old in simple words using an Indian thali as an example. Use everyday foods like dal, rice, roti, curd and vegetables, and suggest a fun drawing activity that helps the child remember each food group." },
  { id: "parenting-838", title: "Plan meals for a busy school week", category: "parenting", text: "Plan our family meals for a busy school week when both parents work. Give a five-day dinner plan with dishes that take under 30 minutes, a Sunday prep list, and ideas for using leftover rice and vegetables the next day." },
  { id: "parenting-839", title: "Cook with grandparents on weekends", category: "parenting", text: "Suggest a weekend cooking activity where our children cook one traditional dish with their grandparents. Give a simple recipe, jobs for a [age]-year-old, questions children can ask about the dish, and a way to record the recipe for the future." },
  { id: "parenting-840", title: "Plan a healthy birthday dinner at home", category: "parenting", text: "Plan a healthy birthday dinner at home for [age]-year-old with [number] guests. Suggest a simple menu with one special dish, a homemade cake idea, decorations we can make together, and games that keep children happy without too many sweets." },
  { id: "parenting-841", title: "Start a family fruit tasting evening", category: "parenting", text: "Plan a family fruit tasting evening with five seasonal Indian fruits. For each fruit, give one fun fact, a simple way to serve it, and a question for children to answer. Add a scoring sheet so everyone can pick a favourite fruit." },
  { id: "parenting-842", title: "Teach children to wash vegetables safely", category: "parenting", text: "Teach my [age]-year-old how to wash vegetables and fruits safely before cooking. Explain the steps in simple words, say which vegetables need extra care, and suggest a fun song or rhyme that helps the child remember the steps." },
  { id: "parenting-843", title: "Plan a monthly family cooking challenge", category: "parenting", text: "Create a monthly family cooking challenge for [number] people with a different theme each month, such as dosa, chaat or soup. Give simple judging rules, a small prize idea, and a way to keep score fairly so younger children also enjoy it." },
  { id: "parenting-844", title: "Make lunch boxes children open happily", category: "parenting", text: "Suggest five lunch box ideas that my [age]-year-old will open happily at school. Each box should be colourful, easy to eat with hands, not too spicy, and ready in 15 minutes. Add one small surprise note idea for each day." },
  { id: "parenting-845", title: "Plan a family meal on a budget", category: "parenting", text: "Plan a tasty family dinner for [number] people with a budget of ₹[amount]. Use seasonal vegetables, dal and rice, list the shopping with approximate prices, and suggest two ways to use leftovers so nothing is wasted the next day." },
  { id: "parenting-846", title: "Teach table manners through family meals", category: "parenting", text: "Help me teach table manners to children aged [ages] during family meals. Give five simple rules in child-friendly words, a gentle way to correct mistakes, and a weekly family game that practises polite eating without making dinner feel like a lesson." },
  { id: "parenting-847", title: "Plan a rain-day family cooking afternoon", category: "parenting", text: "Plan a rainy afternoon cooking session for our family with two simple recipes, one savoury snack and one sweet. Give jobs for children aged [ages], a list of ingredients, and a tidy-up plan so the kitchen is clean before evening." },
  { id: "parenting-848", title: "Create a family food traditions list", category: "parenting", text: "Help our family list the food traditions we want to keep, such as Sunday lunch, festival sweets and grandmother's recipes. Ask questions that help us remember each tradition, then organise them into a simple one-page family food traditions list." },
  { id: "parenting-849", title: "Plan a simple family brunch at home", category: "parenting", text: "Plan a simple family brunch at home for [number] people on a holiday. Suggest three dishes that suit both children and elders, a drink, a seating plan for a small home, and a short activity after brunch that everyone can enjoy together." },
  { id: "parenting-850", title: "Help children learn food hygiene basics", category: "parenting", text: "Explain food hygiene basics to my [age]-year-old in simple words. Cover washing hands before eating, keeping cooked and raw food apart, storing leftovers, and checking expiry dates. Add a short quiz with five easy questions for the child." },
  { id: "parenting-851", title: "Plan a family dinner with elders visiting", category: "parenting", text: "Plan a family dinner for [number] people when grandparents visit, including soft foods for elders and mild dishes for children. Suggest a menu, seating that helps elders feel comfortable, and a short after-dinner activity the whole family can share." },
  { id: "parenting-852", title: "Start a weekly family salad day", category: "parenting", text: "Help our family start a weekly salad day with three simple Indian salads using cucumber, carrot, beetroot and sprouts. Give the recipes, a dressing idea children will like, and a fun way to let each child choose one salad ingredient every week." },
  { id: "parenting-853", title: "Teach children to make simple sandwiches", category: "parenting", text: "Teach my [age]-year-old to make three simple sandwiches safely without using the stove. Give the ingredients, steps and a safety tip for each sandwich, plus ideas for packing them for a school trip or a short family outing." },
  { id: "parenting-854", title: "Plan a family meal for a festival evening", category: "parenting", text: "Plan a family meal for [festival] evening for [number] people. Suggest a traditional menu with one sweet, a simple cooking order so dishes finish together, and jobs for children so they feel part of the festival cooking." },
  { id: "parenting-855", title: "Make grocery shopping a family activity", category: "parenting", text: "Turn our weekly grocery shopping into a fun family activity for children aged [ages]. Give a simple shopping list game, a budget of ₹[amount], jobs for each child, and three questions that teach them to choose fresh vegetables and check prices." },
  { id: "parenting-856", title: "Plan a no-cook family dinner night", category: "parenting", text: "Plan a no-cook family dinner night with five healthy foods that need no stove, such as curd, fruits, sprouts and bread. Give a simple menu, a serving plan, and a fun table game so the evening still feels special without cooking." },
  { id: "parenting-857", title: "Teach children about food waste at home", category: "parenting", text: "Help me teach my [age]-year-old about food waste at home in simple words. Explain why we save leftovers, give three ways to use leftover rice, roti and vegetables, and suggest a weekly family challenge to finish food before cooking more." },
  { id: "parenting-858", title: "Plan a family breakfast before school", category: "parenting", text: "Plan a quick family breakfast routine for school mornings that takes under 20 minutes. Suggest five breakfast options, a night-before prep list, and a simple rota so each family member has one small morning job to do." },
  { id: "parenting-859", title: "Create a family snack box for travel", category: "parenting", text: "Create a family snack box for a [hours]-hour train journey with children aged [ages]. Suggest six snacks that stay fresh, are easy to share, and do not make a mess. Add a packing list and a tip for storing water and fruits safely." },
  { id: "parenting-860", title: "Plan a family meal after a long day", category: "parenting", text: "Plan a comforting family meal for a long, tiring day when nobody wants to cook much. Suggest a one-pot dish, a quick side and a simple sweet, with total cooking time under 30 minutes and ingredients from a basic Indian kitchen." },
  { id: "parenting-861", title: "Help children try foods from other states", category: "parenting", text: "Help our family try foods from four different Indian states over one month. For each state, suggest one simple dish, its main ingredients, and one interesting fact about the food. Keep the recipes easy for a beginner cook." },
  { id: "parenting-862", title: "Plan a family dinner conversation game", category: "parenting", text: "Create a dinner conversation game for our family of [number] with 20 simple questions about the day, school, dreams and funny moments. Make the questions suitable for children aged [ages] and add a rule that everyone listens without interrupting." },
  { id: "parenting-863", title: "Teach children to serve food politely", category: "parenting", text: "Teach my [age]-year-old to serve food politely at family meals. Explain how to offer food to elders first, serve the right portion, and pass dishes carefully. Add a short role-play activity we can practise together at home." },
  { id: "parenting-864", title: "Plan a healthy family dinner for summer", category: "parenting", text: "Plan a light, healthy family dinner for a hot summer evening for [number] people. Suggest cooling foods like curd, cucumber and buttermilk, a simple main dish, and tips for keeping the family hydrated through the day in summer heat." },
  { id: "parenting-865", title: "Start a family gratitude moment at meals", category: "parenting", text: "Help our family start a short gratitude moment before dinner. Suggest a simple sentence each person can say, a way to include young children who cannot read yet, and three gentle prompts for days when someone feels shy or upset." },
  { id: "parenting-866", title: "Build a calm family morning routine", category: "parenting", text: "Help our family build a calm morning routine for school days that starts at [time]. Give a minute-by-minute plan for waking, bathing, breakfast and packing bags, plus one tip for avoiding last-minute rush and arguments before leaving home." },
  { id: "parenting-867", title: "Create a family evening wind-down routine", category: "parenting", text: "Create a 45-minute evening wind-down routine for our family with children aged [ages]. Include bath time, a story, packing school bags, and a screen-free hour. Make it simple enough to follow every night, even on busy days." },
  { id: "parenting-868", title: "Make a family chore chart that works", category: "parenting", text: "Make a weekly family chore chart for [number] people, including children aged [ages]. Give each person two age-appropriate jobs, a fair rota for washing dishes and tidying rooms, and a simple way to track who finished their jobs each day." },
  { id: "parenting-869", title: "Plan a screen-free family hour daily", category: "parenting", text: "Help our family enjoy one screen-free hour every evening. Suggest 10 activities for children aged [ages], such as board games, drawing and talking, plus a gentle way to start the habit and handle complaints in the first week." },
  { id: "parenting-870", title: "Organise a family weekend cleaning routine", category: "parenting", text: "Organise a two-hour family cleaning routine for Saturday mornings. Give each person a clear job, a simple checklist for rooms, kitchen and bathroom, and a fun reward after cleaning, such as a family walk or a favourite snack together." },
  { id: "parenting-871", title: "Create a bedtime routine for young children", category: "parenting", text: "Create a 30-minute bedtime routine for my [age]-year-old that helps the child sleep on time. Include a bath, brushing teeth, one story and a quiet song. Add tips for handling nights when the child refuses to sleep." },
  { id: "parenting-872", title: "Plan family time after school each day", category: "parenting", text: "Plan 30 minutes of family time after school each day for children aged [ages]. Suggest simple activities like talking about the day, playing a game or going for a walk, and explain how to keep homework and playtime clearly separate." },
  { id: "parenting-873", title: "Set a family homework time routine", category: "parenting", text: "Help our family set a fixed homework time from [time] to [time] each evening. Suggest a quiet study corner, a short break plan, and a simple rule for when parents help and when children try alone first before asking." },
  { id: "parenting-874", title: "Build a family Sunday planning habit", category: "parenting", text: "Help our family hold a short Sunday planning meeting of 15 minutes. Suggest an agenda covering the school week, meals, outings and chores, plus a simple notebook format so children can also share what they look forward to." },
  { id: "parenting-875", title: "Create a family reading time each night", category: "parenting", text: "Create a 20-minute family reading time each night for children aged [ages]. Suggest how to choose books, where to sit together, and a simple question each person answers after reading, so even young children feel included in the habit." },
  { id: "parenting-876", title: "Plan a family walk after dinner", category: "parenting", text: "Plan a 20-minute family walk after dinner in our area near [place]. Suggest a safe route, three talking points for children, and a simple way to make the walk fun, such as spotting birds, trees or counting steps together as a family." },
  { id: "parenting-877", title: "Teach children to pack their school bag", category: "parenting", text: "Teach my [age]-year-old to pack a school bag alone the night before. Give a simple checklist for books, tiffin, water bottle and homework, plus a picture chart idea for younger children and a tip for checking the bag together on Sunday." },
  { id: "parenting-878", title: "Create a family prayer or quiet time", category: "parenting", text: "Help our family create a short daily prayer or quiet time of 10 minutes that suits children aged [ages]. Suggest a simple format, a short verse or thought, and a calm closing habit that helps everyone start the day peacefully together." },
  { id: "parenting-879", title: "Organise family laundry with children helping", category: "parenting", text: "Organise a simple family laundry routine where children aged [ages] help in safe ways. Give jobs like sorting colours, folding towels and putting clothes away, plus a weekly schedule and a tip for teaching children to care for their own clothes." },
  { id: "parenting-880", title: "Plan a family budget meeting for children", category: "parenting", text: "Plan a simple monthly family budget meeting that children aged [ages] can understand. Explain income, food, school and savings in easy words, and suggest one family saving goal, such as a trip or a festival, that everyone contributes ideas towards." },
  { id: "parenting-881", title: "Build a family routine for exam weeks", category: "parenting", text: "Build a calm family routine for exam weeks for a child in class [class]. Give a daily timetable with study blocks, breaks, meals and sleep, plus tips for parents on encouraging the child without adding pressure or comparing with others." },
  { id: "parenting-882", title: "Create a family weekend outing routine", category: "parenting", text: "Create a simple family weekend outing routine with one outing every Sunday. Suggest low-cost ideas near [your city], such as parks, temples and libraries, a packing checklist, and a way to let children take turns choosing the outing each week." },
  { id: "parenting-883", title: "Teach children to tidy their room daily", category: "parenting", text: "Teach my [age]-year-old to tidy a bedroom in 10 minutes every evening. Give a step-by-step routine for bed, toys, books and clothes, a simple storage idea, and a fun timer game that makes tidying feel quick and easy for the child." },
  { id: "parenting-884", title: "Plan a family routine for school holidays", category: "parenting", text: "Plan a balanced family routine for school holidays with children aged [ages]. Include wake-up time, reading, play, helping at home and one outing a week. Keep it flexible so holidays still feel relaxed and fun for the whole family." },
  { id: "parenting-885", title: "Start a family journal for daily moments", category: "parenting", text: "Help our family start a simple daily journal where each person writes or draws one happy moment. Suggest a notebook format, prompts for young children who cannot write yet, and a weekly time to read favourite entries together as a family." },
  { id: "parenting-886", title: "Create a family rule for sharing devices", category: "parenting", text: "Help our family create a fair rule for sharing one tablet among children aged [ages]. Suggest time slots, a rota, what to do when time ends, and a simple agreement that everyone signs, so arguments about the device reduce at home." },
  { id: "parenting-887", title: "Plan a family morning exercise routine", category: "parenting", text: "Plan a 20-minute family morning exercise routine for parents and children aged [ages]. Include simple stretching, walking and a fun game, with no equipment needed. Add safety tips and a way to keep the routine going for four weeks." },
  { id: "parenting-888", title: "Organise a family festival cleaning day", category: "parenting", text: "Organise a family cleaning day before [festival] with jobs for everyone, including children aged [ages]. Give a room-by-room checklist, a schedule for the day, and a simple celebration after cleaning, such as a special dinner or a family film." },
  { id: "parenting-889", title: "Build a family routine for new babies", category: "parenting", text: "Help our family build a gentle daily routine after a new baby arrives, with older children aged [ages] included. Suggest feeding, sleep and play timings, jobs older children can do safely, and a way to give each child special attention every day." },
  { id: "parenting-890", title: "Create a family checklist for school mornings", category: "parenting", text: "Create a school-morning checklist for our family that covers uniform, tiffin, water bottle, homework and shoes. Make it simple enough for a [age]-year-old to follow alone, and suggest where to display it so mornings run smoothly without repeated reminders." },
  { id: "parenting-891", title: "Plan a family evening without television", category: "parenting", text: "Plan a television-free family evening once a week for children aged [ages]. Suggest five activities, such as cooking, storytelling, puzzles and music, plus a simple plan for the evening from 7 pm to 9 pm that everyone can enjoy." },
  { id: "parenting-892", title: "Teach children to care for their belongings", category: "parenting", text: "Teach my [age]-year-old to care for school books, shoes and toys. Give five simple daily habits, a storage idea for each type of item, and a gentle way to handle lost or broken things without scolding the child." },
  { id: "parenting-893", title: "Create a family routine for visiting relatives", category: "parenting", text: "Help our family prepare a simple routine for visiting relatives with children aged [ages]. Suggest what to pack, how to explain good behaviour before the visit, and a polite way for children to greet elders and spend time with cousins." },
  { id: "parenting-894", title: "Plan a family day for a public holiday", category: "parenting", text: "Plan a full family day for a public holiday with children aged [ages] and a budget of ₹[amount]. Suggest a morning activity, a simple lunch, an afternoon rest, and an evening outing near [your city], with timings for each part of the day." },
  { id: "parenting-895", title: "Build a family sleep schedule that works", category: "parenting", text: "Help our family build a sleep schedule where children aged [ages] sleep by [time] and wake by [time]. Give a wind-down plan, tips for handling late nights on weekends, and a simple chart to track sleep for two weeks." },
  { id: "parenting-896", title: "Create a family tradition for birthdays", category: "parenting", text: "Help our family create a simple birthday tradition for each child. Suggest a morning surprise, a favourite meal, a handmade card from siblings, and a short family moment, such as sharing one memory from the past year together." },
  { id: "parenting-897", title: "Plan a family routine when parents work late", category: "parenting", text: "Plan a family routine for days when one parent works late. Suggest who handles dinner, homework and bedtime, a simple meal plan, and a short video call or message ritual so the working parent still connects with the children that evening." },
  { id: "parenting-898", title: "Teach children to help with younger siblings", category: "parenting", text: "Teach my [age]-year-old to help care for a younger sibling safely. Give five simple jobs, such as reading a story, fetching a toy or singing a song, plus clear rules about what only adults should do, like feeding and bathing." },
  { id: "parenting-899", title: "Organise a family game night every week", category: "parenting", text: "Organise a weekly family game night for [number] people with children aged [ages]. Suggest five games that need no screen, a simple rota for choosing games, and rules that keep the evening friendly even when someone loses a game." },
  { id: "parenting-900", title: "Create a family calendar everyone can see", category: "parenting", text: "Help our family create a simple wall calendar showing school events, birthdays, festivals and holidays. Suggest a layout, colour codes for each person, and a weekly habit of updating it together on Sunday evening so nobody misses important dates." },
  { id: "parenting-901", title: "Plan a family routine for monsoon days", category: "parenting", text: "Plan a family routine for rainy monsoon days when children aged [ages] stay indoors. Suggest indoor games, a cooking activity, reading time and a simple safety talk about wet roads, umbrellas and staying away from flooded areas." },
  { id: "parenting-902", title: "Build a family habit of saying sorry", category: "parenting", text: "Help our family build a habit of saying sorry and forgiving each other. Suggest simple words children aged [ages] can use, a calm way for parents to apologise first, and a short family talk that helps everyone repair hurt feelings after an argument." },
  { id: "parenting-903", title: "Create a family morning prayer and breakfast", category: "parenting", text: "Create a simple morning routine that combines a short prayer, breakfast and a kind word for the day. Give a 20-minute plan for a family with children aged [ages], plus a way to include elders who wake early and children who wake late." },
  { id: "parenting-904", title: "Plan a family routine for shifting house", category: "parenting", text: "Plan a family routine for the week we shift to a new house in [your city]. Suggest packing jobs for children aged [ages], a first-night essentials box, and a simple way to help children settle into the new home and neighbourhood." },
  { id: "parenting-905", title: "Teach children to follow a daily timetable", category: "parenting", text: "Teach my [age]-year-old to follow a simple daily timetable with pictures for waking, school, play, study and sleep. Give a sample timetable, a way to track it with ticks, and a gentle reward for following it for five days in a row." },
  { id: "parenting-906", title: "Celebrate Diwali together as a family", category: "parenting", text: "Plan a family Diwali celebration at home for [number] people, including children aged [ages]. Suggest safe diya lighting, a simple rangoli, a sweet to cook together, and a gift exchange with a budget of ₹[amount] per person." },
  { id: "parenting-907", title: "Make a family rangoli for festivals", category: "parenting", text: "Teach our family to make a simple rangoli together for [festival]. Suggest three easy designs for beginners, a list of colours and materials, jobs for children aged [ages], and tips for keeping the rangoli neat through the day." },
  { id: "parenting-908", title: "Plan a family Pongal celebration at home", category: "parenting", text: "Plan a family Pongal celebration at home with children aged [ages]. Explain the festival in simple words, suggest a pongal dish to cook together, a kolam idea, and a short family activity that teaches children about harvest and gratitude." },
  { id: "parenting-909", title: "Celebrate Raksha Bandhan with children", category: "parenting", text: "Help our family celebrate Raksha Bandhan in a simple, happy way. Suggest how to explain the festival to children aged [ages], a handmade rakhi idea, a sweet to prepare, and a small gift plan with a budget of ₹[amount]." },
  { id: "parenting-910", title: "Plan a family Holi celebration safely", category: "parenting", text: "Plan a safe family Holi celebration for children aged [ages]. Suggest natural colours, old clothes, a simple snack menu, and safety tips for skin, eyes and hair. Add a gentle clean-up plan and a family photo idea after playing." },
  { id: "parenting-911", title: "Teach children about Janmashtami stories", category: "parenting", text: "Teach my [age]-year-old the story of Janmashtami in simple words. Retell the story of baby Krishna in five short parts, suggest a drawing activity, a simple prasadam to prepare, and a question the child can answer after the story." },
  { id: "parenting-912", title: "Plan a family Christmas celebration simply", category: "parenting", text: "Plan a simple family Christmas celebration at home for [number] people. Suggest a small tree decoration activity, a cake to bake together, a gift plan with a budget of ₹[amount], and a carol or song that children aged [ages] can learn." },
  { id: "parenting-913", title: "Celebrate Eid together with the family", category: "parenting", text: "Help our family celebrate Eid together with children aged [ages]. Suggest a simple way to explain the festival, a sweet dish to prepare, a greeting children can learn, and a small gift or Eidi plan with a budget of ₹[amount]." },
  { id: "parenting-914", title: "Plan a family Navratri celebration at home", category: "parenting", text: "Plan a nine-day family Navratri celebration with a simple daily activity for children aged [ages]. Suggest a colour for each day, a short prayer, a golu or decoration idea, and a simple fasting-friendly snack for the family." },
  { id: "parenting-915", title: "Make festival cards together as family", category: "parenting", text: "Help our family make handmade festival cards for [festival] to send to relatives. Suggest three simple card designs, materials we need, a message children aged [ages] can write, and a way to post or share the cards on time." },
  { id: "parenting-916", title: "Plan a family Onam sadya at home", category: "parenting", text: "Plan a simple family Onam sadya at home for [number] people. Suggest five dishes that beginners can cook, a serving order on a banana leaf, a pookkalam idea, and jobs for children so they feel part of the celebration." },
  { id: "parenting-917", title: "Teach children about Dussehra traditions", category: "parenting", text: "Teach my [age]-year-old about Dussehra traditions in simple words. Explain the story of good winning over evil, suggest a craft activity, a simple sweet to make, and a family discussion about one good habit to practise after the festival." },
  { id: "parenting-918", title: "Plan a family visit to a temple festival", category: "parenting", text: "Plan a family visit to a temple festival in [your city] with children aged [ages]. Suggest what time to go, what to carry, how to explain the rituals simply, and safety tips for crowds, footwear and keeping children close in busy places." },
  { id: "parenting-919", title: "Create a family festival photo album", category: "parenting", text: "Help our family create a festival photo album with pictures from [festival] over three years. Suggest how to organise photos by year, captions children can write, and a simple way to print or store the album so the family can enjoy it together." },
  { id: "parenting-920", title: "Plan a family gift exchange for Diwali", category: "parenting", text: "Plan a family gift exchange for Diwali for [number] people with a budget of ₹[amount] each. Suggest a simple draw system, gift ideas for children and elders, and a wrapping activity where children decorate the gift paper themselves at home." },
  { id: "parenting-921", title: "Teach children to make festival sweets", category: "parenting", text: "Teach our family to make three simple festival sweets together, such as ladoo, kheer and halwa. Give the ingredients, steps and safety tips for children aged [ages], plus a plan for sharing the sweets with neighbours and relatives." },
  { id: "parenting-922", title: "Plan a family Ganesh Chaturthi celebration", category: "parenting", text: "Plan a family Ganesh Chaturthi celebration at home with children aged [ages]. Suggest an eco-friendly clay Ganesh idea, a simple modak recipe, a decoration plan, and a gentle explanation of the festival story for young children." },
  { id: "parenting-923", title: "Celebrate a family harvest festival together", category: "parenting", text: "Help our family celebrate a harvest festival together, such as Pongal or Baisakhi. Explain the festival in simple words for children aged [ages], suggest a traditional dish, a folk song, and a family game linked to farming and harvest." },
  { id: "parenting-924", title: "Plan a family New Year celebration at home", category: "parenting", text: "Plan a simple family New Year celebration at home for [number] people. Suggest a special dinner, a resolution activity where each person picks one kind habit, and a midnight or early-evening countdown that suits children aged [ages]." },
  { id: "parenting-925", title: "Teach children about festival food traditions", category: "parenting", text: "Teach my [age]-year-old about festival food traditions in our family. Explain why we cook certain dishes for [festival], suggest a tasting activity with three foods, and ask the child to draw a favourite festival dish with its name." },
  { id: "parenting-926", title: "Plan a family Ramzan iftar together", category: "parenting", text: "Plan a family iftar together during Ramzan for [number] people, including children aged [ages]. Suggest a simple menu with dates, fruit and a light main dish, a prayer time plan, and a kind act the family can do together each evening." },
  { id: "parenting-927", title: "Make a family festival decoration together", category: "parenting", text: "Help our family make simple festival decorations for [festival] using paper, flowers and lights. Suggest three decoration ideas, a materials list with a budget of ₹[amount], and jobs for children aged [ages] so everyone helps decorate the home." },
  { id: "parenting-928", title: "Plan a family story night for festivals", category: "parenting", text: "Plan a family story night for [festival] where grandparents tell one festival story. Suggest questions children can ask, a simple snack to serve, and a way to record the story in a notebook so the family keeps it for next year." },
  { id: "parenting-929", title: "Teach children to share during festivals", category: "parenting", text: "Teach my [age]-year-old to share sweets and gifts during festivals. Suggest three simple sharing activities, a way to pack food for neighbours, and gentle words parents can use to praise sharing without making the child feel forced." },
  { id: "parenting-930", title: "Plan a family Bhai Dooj celebration simply", category: "parenting", text: "Plan a simple family Bhai Dooj celebration for siblings aged [ages]. Explain the festival in easy words, suggest a tilak and gift idea, a sweet to prepare together, and a fun activity that brothers and sisters can enjoy as a family." },
  { id: "parenting-931", title: "Create a family festival calendar together", category: "parenting", text: "Help our family create a festival calendar for the year with [festival names]. For each festival, note the date, one dish, one activity and one story to tell children. Make it colourful and simple enough for a [age]-year-old to follow." },
  { id: "parenting-932", title: "Plan a family Karva Chauth evening gently", category: "parenting", text: "Plan a gentle family Karva Chauth evening where children aged [ages] understand the tradition. Suggest a simple explanation, a sargi idea, a story to tell, and a family dinner plan after the moonrise that everyone can enjoy together." },
  { id: "parenting-933", title: "Teach children about lighting diyas safely", category: "parenting", text: "Teach my [age]-year-old to light diyas safely during Diwali. Explain the steps in simple words, list what adults must handle, and give safety rules for clothes, hair, water nearby, and keeping diyas away from curtains and paper." },
  { id: "parenting-934", title: "Plan a family Independence Day celebration", category: "parenting", text: "Plan a family Independence Day celebration at home with children aged [ages]. Suggest a flag-hoisting activity, a tricolour snack, a short story about freedom fighters, and a family discussion about one good deed for the country." },
  { id: "parenting-935", title: "Make a family festival memory box", category: "parenting", text: "Help our family make a festival memory box for [festival]. Suggest what to keep inside, such as cards, photos, a recipe and a small decoration, plus a label for the box and a yearly habit of opening it together before the next festival." },
  { id: "parenting-936", title: "Plan a family visit to a local fair", category: "parenting", text: "Plan a family visit to a local fair or mela in [your city] with children aged [ages]. Suggest the best time to go, a budget of ₹[amount], rides and stalls to try, and safety tips for crowds, food and keeping the family together." },
  { id: "parenting-937", title: "Teach children festival songs and rhymes", category: "parenting", text: "Teach my [age]-year-old three simple festival songs or rhymes for [festival]. Give the words in easy language, a simple tune idea, and a family singing activity where everyone learns one song together before the festival day." },
  { id: "parenting-938", title: "Plan a family Lohri celebration at home", category: "parenting", text: "Plan a simple family Lohri celebration at home for [number] people. Suggest a bonfire safety plan, traditional foods like rewari and popcorn, a folk song, and a fun activity where children aged [ages] share one happy memory of winter." },
  { id: "parenting-939", title: "Create a family tradition for every festival", category: "parenting", text: "Help our family create one small tradition for every festival, such as a special dish, a story or a gift. Suggest a simple list for five festivals, with jobs for children aged [ages], so each festival feels special and familiar every year." },
  { id: "parenting-940", title: "Plan a family Ugadi celebration simply", category: "parenting", text: "Plan a simple family Ugadi celebration at home with children aged [ages]. Explain the six tastes of Ugadi pachadi in simple words, suggest a decoration idea, a festive lunch, and a family talk about new beginnings for the year ahead." },
  { id: "parenting-941", title: "Teach children about Guru Nanak Jayanti", category: "parenting", text: "Teach my [age]-year-old about Guru Nanak Jayanti in simple words. Explain one teaching about kindness and sharing, suggest a visit to a gurudwara, a langar experience, and a simple good deed the family can do together that week." },
  { id: "parenting-942", title: "Plan a family Mahavir Jayanti morning", category: "parenting", text: "Plan a calm family Mahavir Jayanti morning with children aged [ages]. Suggest a simple prayer, a story about kindness to all living beings, a Jain-friendly breakfast, and a family activity such as feeding birds or planting a sapling together." },
  { id: "parenting-943", title: "Celebrate a family milestone together simply", category: "parenting", text: "Plan a simple family celebration for [milestone], such as a first school day or a grandparent's birthday. Suggest a small decoration, a favourite meal, a photo moment, and a short speech or toast that children aged [ages] can help prepare." },
  { id: "parenting-944", title: "Plan a family festival quiz night", category: "parenting", text: "Create a family festival quiz night with 20 easy questions about [festival], Indian food, stories and traditions. Make the questions suitable for children aged [ages], add a simple scoring system, and suggest a small prize for the winning team." },
  { id: "parenting-945", title: "Teach children to greet elders at festivals", category: "parenting", text: "Teach my [age]-year-old to greet elders politely at festivals. Give simple greeting words for [festival], explain when to touch feet or fold hands, and suggest a role-play game so the child practises greetings happily before meeting relatives." },
  { id: "parenting-946", title: "Tell bedtime stories from family history", category: "parenting", text: "Help me tell bedtime stories from our family history to my [age]-year-old. Suggest five story ideas from grandparents' childhood, a simple storytelling structure, and questions that help the child remember and retell one story the next day." },
  { id: "parenting-947", title: "Create a family storytelling night weekly", category: "parenting", text: "Create a weekly family storytelling night for children aged [ages]. Suggest a rota for storytellers, three story themes, a cosy seating plan, and a simple rule that everyone listens quietly and asks one question after each story ends." },
  { id: "parenting-948", title: "Play a family memory game together", category: "parenting", text: "Plan a family memory game night for [number] people with children aged [ages]. Suggest three games that improve memory, such as recalling objects on a tray, a simple scoring system, and a way to make younger children feel included and successful." },
  { id: "parenting-949", title: "Start a family book club at home", category: "parenting", text: "Start a simple family book club where everyone reads one book a month. Suggest how to choose books for children aged [ages], three discussion questions, and a fun meeting format with snacks that makes reading feel like a family celebration." },
  { id: "parenting-950", title: "Plan a family puzzle evening together", category: "parenting", text: "Plan a family puzzle evening with a 100-piece puzzle suitable for children aged [ages]. Suggest how to sort pieces, divide jobs fairly, and keep the puzzle safe overnight. Add a tip for celebrating together when the puzzle is finished." },
  { id: "parenting-951", title: "Create a family photo storytelling game", category: "parenting", text: "Create a photo storytelling game using old family photos. Each person picks one photo and tells the story behind it in two minutes. Suggest prompts for children aged [ages] and a way to record the best stories in a family notebook." },
  { id: "parenting-952", title: "Plan a family music evening at home", category: "parenting", text: "Plan a family music evening at home for [number] people with children aged [ages]. Suggest five simple songs everyone knows, a homemade instrument idea, and a turn-taking plan so each person sings or plays once during the evening." },
  { id: "parenting-953", title: "Teach children a traditional family story", category: "parenting", text: "Teach my [age]-year-old one traditional story from our family or region in simple words. Break the story into five parts, suggest a drawing for each part, and give three questions that help the child understand the lesson in the story." },
  { id: "parenting-954", title: "Plan a family drawing and colouring afternoon", category: "parenting", text: "Plan a family drawing and colouring afternoon for children aged [ages]. Suggest three themes, such as my family, my dream house and a festival, a materials list, and a simple way to display everyone's drawings on a wall at home." },
  { id: "parenting-955", title: "Create a family treasure hunt at home", category: "parenting", text: "Create a family treasure hunt at home with 10 clues for children aged [ages]. Give clue ideas that use rooms, books and kitchen items, a simple prize, and safety rules so the hunt stays fun and nobody rushes or breaks anything." },
  { id: "parenting-956", title: "Plan a family board game tournament", category: "parenting", text: "Plan a family board game tournament over four Sundays for [number] people. Suggest three games suitable for children aged [ages], a fair scoring system, and a small prize for the winner, plus a rule that keeps the tournament friendly and fun." },
  { id: "parenting-957", title: "Start a family gratitude jar together", category: "parenting", text: "Help our family start a gratitude jar where each person adds one note every day. Suggest simple prompts for children aged [ages], a jar decoration idea, and a weekly time to read notes together and talk about the happy moments of the week." },
  { id: "parenting-958", title: "Plan a family stargazing night simply", category: "parenting", text: "Plan a simple family stargazing night from our terrace or balcony with children aged [ages]. Suggest the best time, three things to spot in the sky, a story about the moon, and a checklist of blankets, water and mosquito protection for the night." },
  { id: "parenting-959", title: "Create a family dance party at home", category: "parenting", text: "Create a fun family dance party at home for 30 minutes with children aged [ages]. Suggest a playlist of five happy songs, a simple dance game, and a safe space plan so furniture is moved aside and nobody slips while dancing together." },
  { id: "parenting-960", title: "Teach children to write family letters", category: "parenting", text: "Teach my [age]-year-old to write a short letter to a grandparent or relative. Give a simple letter format, sentence starters for children, and ideas for drawings to include. Add a tip for posting the letter or sharing it on a video call." },
  { id: "parenting-961", title: "Plan a family nature walk on Sunday", category: "parenting", text: "Plan a family nature walk on Sunday morning near [your city] for children aged [ages]. Suggest a safe route, five things to spot, such as birds, leaves and flowers, and a simple notebook activity where children draw one thing they saw." },
  { id: "parenting-962", title: "Create a family cooking story book", category: "parenting", text: "Help our family create a small story book about cooking together, with drawings by children aged [ages]. Suggest a simple story plot, five pages with text and pictures, and a way to bind the book so the family can read it together." },
  { id: "parenting-963", title: "Plan a family talent show at home", category: "parenting", text: "Plan a family talent show at home for [number] people where each person performs for five minutes. Suggest act ideas for children aged [ages], a simple stage setup, and judging rules that praise effort so every performer feels happy and proud." },
  { id: "parenting-964", title: "Start a family garden project together", category: "parenting", text: "Start a small family garden project on a balcony or in a yard with children aged [ages]. Suggest three easy plants, such as tulsi, mint and tomato, daily watering jobs, and a simple chart to track growth and first harvest together as a family." },
  { id: "parenting-965", title: "Plan a family picnic in the park", category: "parenting", text: "Plan a family picnic in a park near [your city] for [number] people. Suggest a food list, games like badminton and hide-and-seek, a packing checklist, and safety tips for sun, insects and keeping children within sight during the picnic." },
  { id: "parenting-966", title: "Create a family scrapbook of the year", category: "parenting", text: "Help our family create a scrapbook of this year with photos, tickets, drawings and notes. Suggest 12 monthly pages, captions children aged [ages] can write, and a simple way to store the scrapbook so the family can look through it every year." },
  { id: "parenting-967", title: "Teach children family values through stories", category: "parenting", text: "Teach my [age]-year-old family values like honesty, kindness and sharing through three short stories. For each story, give a simple plot, a discussion question, and a real-life example the family can practise together during the week." },
  { id: "parenting-968", title: "Plan a family movie night at home", category: "parenting", text: "Plan a family movie night at home for children aged [ages]. Suggest how to choose a film everyone enjoys, a simple snack menu, a seating plan with blankets, and a short discussion after the film about the favourite character and lesson." },
  { id: "parenting-969", title: "Create a family time capsule together", category: "parenting", text: "Help our family create a time capsule to open in five years. Suggest 10 items to include, such as letters, photos and drawings, a safe container, and a note with the opening date. Add a family discussion about hopes for the future." },
  { id: "parenting-970", title: "Plan a family cycling outing on Sunday", category: "parenting", text: "Plan a safe family cycling outing on Sunday morning near [your city] for children aged [ages]. Suggest a flat route, safety gear, water and snacks to carry, and a rest stop plan, plus rules for riding together and staying on the correct side." },
  { id: "parenting-971", title: "Start a family kindness challenge week", category: "parenting", text: "Start a one-week family kindness challenge where each person does one kind act daily. Suggest seven simple acts for children aged [ages], such as helping a sibling or feeding birds, and a chart to track acts and share stories each evening." },
  { id: "parenting-972", title: "Plan a family visit to grandparents village", category: "parenting", text: "Plan a family visit to grandparents' village for [number] days with children aged [ages]. Suggest what to pack, activities like visiting fields and listening to stories, and a simple way to help children feel comfortable in a village home." },
  { id: "parenting-973", title: "Create a family song for special days", category: "parenting", text: "Help our family create a simple song for birthdays and special days. Suggest a tune everyone knows, easy words about our family, and a way for children aged [ages] to add one line each, so the song feels personal and fun to sing." },
  { id: "parenting-974", title: "Plan a family art exhibition at home", category: "parenting", text: "Plan a small family art exhibition at home displaying drawings by children aged [ages]. Suggest how to choose 10 artworks, display them on a wall, invite grandparents on a video call, and praise each artist with one kind comment about their work." },
  { id: "parenting-975", title: "Teach children to interview grandparents", category: "parenting", text: "Teach my [age]-year-old to interview grandparents about their childhood. Give 10 simple questions about school, food, games and festivals, a way to record answers in a notebook, and a tip for turning the answers into a short family story." },
  { id: "parenting-976", title: "Plan a family volunteering day together", category: "parenting", text: "Plan a family volunteering day suitable for children aged [ages] in [your city]. Suggest three safe activities, such as cleaning a park, donating books or serving food, plus a family talk afterwards about what everyone learned from helping others." },
  { id: "parenting-977", title: "Create a family bedtime song routine", category: "parenting", text: "Create a bedtime song routine for my [age]-year-old with two gentle songs and a quiet closing habit. Suggest simple song choices, a calm singing plan, and a way to help the child feel safe and sleepy without screens before bed." },
  { id: "parenting-978", title: "Plan a family day trip by train", category: "parenting", text: "Plan a one-day family trip by train from [your city] to [place] with children aged [ages]. Suggest train timings, a food and water plan, games for the journey, and a simple sightseeing plan that keeps the day relaxed and enjoyable." },
  { id: "parenting-979", title: "Start a family photo of the week", category: "parenting", text: "Start a family photo of the week habit where one person takes a photo each week. Suggest themes for children aged [ages], a simple album to store photos, and a monthly time to look through photos together and choose a favourite for the month." },
  { id: "parenting-980", title: "Plan a family kite flying afternoon", category: "parenting", text: "Plan a family kite flying afternoon in an open ground near [your city] for children aged [ages]. Suggest how to choose kites, safety tips for strings and open spaces, snacks to carry, and a simple contest that keeps the afternoon fun for everyone." },
  { id: "parenting-981", title: "Plan a family health checkup every year", category: "parenting", text: "Help our family plan a yearly health checkup for parents and children aged [ages]. List the basic tests to ask a doctor about, documents to carry, and a simple way to prepare children so they feel calm and not scared before the visit." },
  { id: "parenting-982", title: "Teach children about handwashing and hygiene", category: "parenting", text: "Teach my [age]-year-old about handwashing and hygiene in simple words. Explain when to wash hands, the steps for 20 seconds, and why clean hands keep the family healthy. Add a fun rhyme and a chart to track handwashing for one week." },
  { id: "parenting-983", title: "Plan healthy family meals for immunity", category: "parenting", text: "Plan healthy family meals that support immunity using everyday Indian foods like turmeric, ginger, seasonal fruits and green vegetables. Give a three-day menu, simple recipes, and tips for drinking enough water through the day in every season." },
  { id: "parenting-984", title: "Help children understand vaccination visits", category: "parenting", text: "Help me explain a vaccination visit to my [age]-year-old in calm, simple words. Describe what happens at the clinic, why vaccines protect us, and three ways to comfort the child before and after the visit, including a small reward afterwards." },
  { id: "parenting-985", title: "Create a family first-aid box at home", category: "parenting", text: "Help our family create a first-aid box at home with basic items like bandages, antiseptic and a thermometer. List what to keep, where to store it safely away from young children, and a simple guide for treating small cuts and scrapes." },
  { id: "parenting-986", title: "Teach children about drinking enough water", category: "parenting", text: "Teach my [age]-year-old why drinking enough water matters. Explain in simple words how much water children need, signs of thirst, and fun ways to remember, such as a colourful bottle and a family water-drinking challenge for one week." },
  { id: "parenting-987", title: "Plan a family eye checkup for children", category: "parenting", text: "Help our family plan an eye checkup for children aged [ages]. Explain what happens during the test in simple words, signs that a child may need glasses, and tips for reducing screen time and protecting eyes while reading and studying." },
  { id: "parenting-988", title: "Help children build healthy sleep habits", category: "parenting", text: "Help my [age]-year-old build healthy sleep habits. Give a bedtime of [time], a screen-free hour before sleep, and a calm routine with reading and brushing teeth. Add tips for handling nights when the child wakes up or feels scared." },
  { id: "parenting-989", title: "Plan a family dental checkup visit", category: "parenting", text: "Help our family plan a dental checkup visit for children aged [ages]. Explain what a dentist does in simple, friendly words, how to brush twice daily, and foods that protect teeth. Add a tip for calming a nervous child before the visit." },
  { id: "parenting-990", title: "Teach children about healthy snacks choices", category: "parenting", text: "Teach my [age]-year-old to choose healthy snacks. Compare five common snacks, such as fruits, nuts, sprouts, biscuits and chips, in simple words, and suggest a snack box plan for school with one healthy option for each day of the week." },
  { id: "parenting-991", title: "Create a family exercise challenge month", category: "parenting", text: "Create a one-month family exercise challenge for parents and children aged [ages]. Suggest daily activities like walking, skipping and stretching, a simple tracking chart, and a small celebration at the end of the month for everyone who took part." },
  { id: "parenting-992", title: "Help children cope with fever at home", category: "parenting", text: "Give general information about caring for a child with a mild fever at home, including rest, fluids and when to call a doctor. Keep the advice general and safe, list warning signs that need urgent care, and suggest ways to comfort the child." },
  { id: "parenting-993", title: "Plan a family health record folder", category: "parenting", text: "Help our family organise a health record folder for each child with vaccination cards, prescriptions and checkup reports. Suggest a simple filing system, what to carry on a doctor visit, and a yearly reminder to update the folder." },
  { id: "parenting-994", title: "Teach children about sun safety outdoors", category: "parenting", text: "Teach my [age]-year-old about sun safety in simple words. Explain why we wear hats, drink water and stay in shade during hot afternoons, plus a simple routine for applying sunscreen before playing outside in Indian summer heat." },
  { id: "parenting-995", title: "Plan a family yoga morning together", category: "parenting", text: "Plan a 20-minute family yoga morning with five simple poses suitable for children aged [ages] and elders. Give step-by-step instructions, breathing tips, and a calm closing moment. Add safety advice for practising on a mat at home." },
  { id: "parenting-996", title: "Help children understand a balanced diet", category: "parenting", text: "Explain a balanced diet to my [age]-year-old using a colourful plate idea with grains, dal, vegetables, curd and fruit. Suggest a drawing activity, a weekly menu check, and one new healthy food to try together every week as a family." },
  { id: "parenting-997", title: "Create a family medicine safety routine", category: "parenting", text: "Help our family create a medicine safety routine at home. Explain why children must never take medicine alone, where to store medicines safely, how to check expiry dates, and what to do if a child takes the wrong medicine by mistake." },
  { id: "parenting-998", title: "Teach children about cough and cold care", category: "parenting", text: "Give general information about caring for a child with a common cough and cold at home, including rest, warm fluids and steam. List signs that need a doctor visit, and suggest comfort measures such as honey water for older children and quiet rest." },
  { id: "parenting-999", title: "Plan a family walking challenge week", category: "parenting", text: "Plan a one-week family walking challenge for parents and children aged [ages]. Set a daily step goal, suggest safe walking routes near [your city], a simple tracking chart, and a small family reward for everyone who completes the week together." },
  { id: "parenting-1000", title: "Help children stay healthy during monsoon", category: "parenting", text: "Help our family stay healthy during monsoon with children aged [ages]. Give general tips on clean drinking water, avoiding street food, drying clothes properly, and preventing mosquito bites, plus a simple home checklist for the rainy season." },
  { id: "parenting-1001", title: "Teach children about dental care daily", category: "parenting", text: "Teach my [age]-year-old daily dental care in simple steps. Explain brushing twice a day, using the right amount of toothpaste, cleaning the tongue, and limiting sweets. Add a two-minute brushing song and a chart to track brushing for two weeks." },
  { id: "parenting-1002", title: "Plan a family health talk with children", category: "parenting", text: "Plan a gentle family health talk with children aged [ages] about growing bodies, food and exercise. Suggest simple words for explaining changes, questions children may ask, and a calm, honest way for parents to answer without embarrassment or fear." },
  { id: "parenting-1003", title: "Create a family emergency contacts list", category: "parenting", text: "Help our family create an emergency contacts list for children aged [ages]. Include parents, grandparents, a neighbour and a doctor, with phone numbers displayed clearly at home. Teach children when and how to call for help safely." },
  { id: "parenting-1004", title: "Help children handle minor injuries calmly", category: "parenting", text: "Teach my [age]-year-old to handle minor injuries calmly, such as a small cut or a bruise. Explain the steps of cleaning, applying a bandage and telling an adult, plus what never to do alone, and a simple first-aid rhyme to remember the steps." },
  { id: "parenting-1005", title: "Plan a family food allergy awareness talk", category: "parenting", text: "Help our family talk about food allergies in simple words for children aged [ages]. Explain what an allergy means, foods to avoid, how to read labels, and what to tell teachers and friends, so the child stays safe at school and at parties." },
  { id: "parenting-1006", title: "Teach children about mental health simply", category: "parenting", text: "Teach my [age]-year-old about feelings and mental health in simple words. Explain that feeling sad or worried is normal, give three ways to feel better, such as talking, drawing and playing, and explain when to ask a trusted adult for help." },
  { id: "parenting-1007", title: "Plan a family checkup before school starts", category: "parenting", text: "Plan a family health checkup before the new school year for children aged [ages]. List vision, dental and general health checks to discuss with a doctor, plus a shopping list for school health essentials like a water bottle and a lunch box." },
  { id: "parenting-1008", title: "Help children build a healthy screen habit", category: "parenting", text: "Help my [age]-year-old build a healthy screen habit with clear time limits. Suggest a daily screen schedule, screen-free zones at home, and five fun offline activities, so the child enjoys play, reading and family time without feeling punished." },
  { id: "parenting-1009", title: "Create a family relaxation time each evening", category: "parenting", text: "Create a 15-minute family relaxation time each evening for parents and children aged [ages]. Suggest deep breathing, quiet music and gentle stretching, plus a simple way to share one good thing from the day before going to sleep." },
  { id: "parenting-1010", title: "Teach children about safe medicines storage", category: "parenting", text: "Teach my [age]-year-old why medicines must stay in a safe, locked place at home. Explain in simple words that only adults give medicine, how to read a label with a parent, and what to do if a younger sibling finds a medicine bottle." },
  { id: "parenting-1011", title: "Plan a family weekend with grandparents", category: "parenting", text: "Plan a weekend with grandparents for our family of [number], including children aged [ages]. Suggest a shared meal, a story session, a gentle walk, and a photo activity, plus tips for helping elders rest and children listen patiently during the visit." },
  { id: "parenting-1012", title: "Create a family tradition with grandparents", category: "parenting", text: "Help our family create a tradition with grandparents, such as a monthly lunch or a festival story. Suggest a simple format, jobs for children aged [ages], and a way to record memories in a notebook so the tradition continues every year." },
  { id: "parenting-1013", title: "Teach children to respect elders daily", category: "parenting", text: "Teach my [age]-year-old to respect elders in daily life. Give five simple habits, such as greeting politely, listening without interrupting and offering a seat, plus a role-play activity the family can practise together at home each week." },
  { id: "parenting-1014", title: "Plan a family reunion at home simply", category: "parenting", text: "Plan a simple family reunion at home for [number] relatives, including children aged [ages]. Suggest a potluck menu, games for cousins, a photo corner, and a schedule from morning to evening that keeps everyone relaxed and happy together." },
  { id: "parenting-1015", title: "Help children bond with cousins happily", category: "parenting", text: "Help my [age]-year-old bond happily with cousins during family gatherings. Suggest five group games, a shared craft activity, and a gentle way to handle disagreements, so cousins enjoy time together and look forward to the next meeting." },
  { id: "parenting-1016", title: "Create a family video call with relatives", category: "parenting", text: "Help our family hold a weekly video call with relatives living in another city. Suggest a fixed time, three talking points for children aged [ages], and a fun activity like showing a drawing or singing a song together on the call." },
  { id: "parenting-1017", title: "Teach children about family roots simply", category: "parenting", text: "Teach my [age]-year-old about our family roots in simple words. Explain where our family comes from, what our ancestors did, and one tradition we still follow. Suggest a family tree drawing activity the child can complete with grandparents." },
  { id: "parenting-1018", title: "Plan a family gift for grandparents", category: "parenting", text: "Plan a thoughtful family gift for grandparents with a budget of ₹[amount]. Suggest five handmade gift ideas from children aged [ages], such as a photo frame, a card and a story book, plus a simple presentation moment during a family meal." },
  { id: "parenting-1019", title: "Help children learn from grandparents stories", category: "parenting", text: "Help my [age]-year-old learn from grandparents' stories about their school days, work and festivals. Give 10 questions to ask, a way to write answers in a notebook, and a family sharing time where the child retells one story to everyone." },
  { id: "parenting-1020", title: "Create a family prayer together on Sundays", category: "parenting", text: "Create a simple family prayer together on Sunday mornings for parents, children aged [ages] and elders. Suggest a short prayer, a moment of silence, and a kind thought for the week ahead, so the whole family starts Sunday peacefully together." },
  { id: "parenting-1021", title: "Plan a family outing with extended family", category: "parenting", text: "Plan a family outing with extended family to [place] for [number] people, including children aged [ages] and elders. Suggest transport, food, a meeting point, and activities that suit both young children and older relatives on the same day." },
  { id: "parenting-1022", title: "Teach children to care for elderly relatives", category: "parenting", text: "Teach my [age]-year-old to care for elderly relatives in simple, kind ways. Suggest five actions, such as fetching water, reading aloud and walking slowly together, plus a talk about patience and listening when elders repeat a story." },
  { id: "parenting-1023", title: "Create a family album with grandparents photos", category: "parenting", text: "Help our family create an album with grandparents' old photos and new family pictures. Suggest how to organise photos by decade, captions children aged [ages] can write, and a yearly habit of adding new photos together as a family." },
  { id: "parenting-1024", title: "Plan a family celebration for grandparents anniversary", category: "parenting", text: "Plan a simple celebration for grandparents' wedding anniversary at home for [number] people. Suggest a cake, a photo slideshow, a speech by grandchildren aged [ages], and a small gift with a budget of ₹[amount] from the whole family." },
  { id: "parenting-1025", title: "Build a family bond through shared chores", category: "parenting", text: "Help our family build a stronger bond through shared chores, such as cooking, cleaning and gardening together. Suggest a weekly rota for [number] people, jobs for children aged [ages], and a fun reward after finishing chores as a team." },
];
